local config = {
  ui_story_5086_50860100_1_dialog_content = "... PlayerName, Elvis... Eu...",
  ui_story_5086_50860100_2_dialog_content = "Hã... Jeno?",
  ui_story_5086_50860100_3_dialog_content = "O que você disse? Eu não consigo te ouvir...",
  ui_story_5086_50860100_4_dialog_content = "Senti um momento em que uma maré milagrosa subiu.",
  ui_story_5086_50860100_5_dialog_content = "Chegou a hora de eu perseguir um ponto crucial determinado pelo destino.",
  ui_story_5086_50860100_6_dialog_content = "Então, por favor...",
  ui_story_5086_50860100_7_dialog_content = "Espere, Jeno!",
  ui_story_5086_50860100_8_dialog_content = "... Eu estava sonhando agora?",
  ui_story_5086_50860100_9_dialog_content = "Que sonho estranho e incerto.",
  ui_story_5086_50860100_10_dialog_content = "Será que é por causa daquela carta que recebi ontem?",
  ui_story_5086_50860100_11_dialog_content = "<color=#e8d9bb>\"Minhas desculpas por enviar uma carta tão urgente. Deixei uma mensagem para você em Harbor City. Por favor, venha sozinho para recebê-la. —Jeno\"</color>",
  ui_story_5086_50860100_12_dialog_content = "A carta dele também é estranha e incerta... mas parece que ele está falando sério.",
  ui_story_5086_50860100_13_dialog_content = "Ele especificamente me pediu para vir sozinha... Isso significa que ele não quer que eu traga Vice ou Carleen? Eu me pergunto o que poderia ser...",
  ui_story_5086_50860100_14_dialog_content = "<color=#e8d9bb>A brisa do mar sopra suavemente enquanto as ruas da cidade normalmente pacífica fervilham com multidões de turistas.</color>",
  ui_story_5086_50860100_15_dialog_content = "Não parece que tanto tempo passou, mas parece que Harbour City finalmente se recuperou daquela crise.",
  ui_story_5086_50860100_16_dialog_content = "Se apenas Elvis estivesse aqui para ver isso, tenho certeza de que ele estaria tão orgulhoso... Hã?",
  ui_story_5086_50860100_17_dialog_content = "Isso é estranho... O Emerald estava ancorado bem aqui, não estava?",
  ui_story_5086_50860100_18_dialog_content = "Como um navio tão grande poderia desaparecer?",
  ui_story_5086_50860100_19_dialog_content = "Você está aqui para ver as apresentações, amigo?",
  ui_story_5086_50860100_20_dialog_content = "Odeio ter que te dizer isso, mas você perdeu sua chance. O circo levantou âncora e partiu há alguns dias.",
  ui_story_5086_50860100_21_dialog_content = "Decolou? Mas por quê?",
  ui_story_5086_50860100_22_dialog_content = "Não sei, mas ouvi dizer que tinha algo a ver com alguém que se machucou no caos anterior.",
  ui_story_5086_50860100_23_dialog_content = "Não, não, você entendeu tudo errado!",
  ui_story_5086_50860100_24_dialog_content = "Todos sabem que o mestre de cerimônias teve uma grande briga com seu amante, então ele partiu para ir encontrá-los!",
  ui_story_5086_50860100_25_dialog_content = "O quê? Eu pensei que era porque uma besta maravilhosa escapou do navio!",
  ui_story_5086_50860100_26_dialog_content = "Todos vocês viram, não viram? Aquela baleia enorme estava liderando o caminho!",
  ui_story_5086_50860100_27_dialog_content = "Bem, eles realmente saíram com pressa... Isso é certo.",
  ui_story_5086_50860100_28_dialog_content = "Eu só espero que nada de ruim tenha acontecido.",
  ui_story_5086_50860100_29_dialog_content = "Então, onde eu deveria encontrar Jeno agora?",
  ui_story_5086_50860100_30_dialog_content = "A carta não dizia... Espere, há um endereço escrito no verso! Acho que não percebi isso antes.",
  ui_story_5086_50860100_31_dialog_content = "130 Rua Coral—",
  ui_story_5086_50860100_32_dialog_content = "Bem-vindo ao maravilhoso mundo submarino de Harbour City, um lugar onde os sonhos e o mar se encontram!",
  ui_story_5086_50860100_33_dialog_content = "Você gostaria de nadar com tubarões?",
  ui_story_5086_50860100_34_dialog_content = "Ou talvez relaxar e descansar com uma tartaruga marinha?",
  ui_story_5086_50860100_35_dialog_content = "Você pode até se juntar àquelas águas-vivas e soprar bolhas lindas!",
  ui_story_5086_50860100_36_dialog_content = "Tudo é possível neste lugar fantástico!",
  ui_story_5086_50860100_37_dialog_content = "... Um aquário?",
  ui_story_5086_50860100_38_dialog_content = "Isso mesmo, um aquário!",
  ui_story_5086_50860100_39_dialog_content = "Temos todos os tipos de adoráveis criaturas marinhas que com certeza vão conquistar seu coração! Esta é a sua primeira vez aqui?",
  ui_story_5086_50860100_40_dialog_content = "Se for assim, posso sugerir começar pelo lado esquerdo do primeiro andar...",
  ui_story_5086_50860100_41_dialog_content = "Er... O que estava em exposição lá novamente? Desculpe, tenho uma péssima memória de curto prazo. Deixe-me apenas verificar minhas anotações...",
  ui_story_5086_50860100_42_dialog_content = "Uh, eu não estou aqui para-",
  ui_story_5086_50860100_43_dialog_content = "Ah, lá está! É a exposição de recifes de coral!",
  ui_story_5086_50860100_44_dialog_content = "Também estamos organizando um evento interativo hoje! Convidados podem tocar algumas estrelas do mar lá, enquanto crianças de dez anos ou menos são gratuitas!",
  ui_story_5086_50860100_45_dialog_content = "Eu definitivamente pareço mais velho que dez anos, você não acha?",
  ui_story_5086_50860100_46_dialog_content = "Hmm... Acho que sim.",
  ui_story_5086_50860100_47_dialog_content = "Vamos tentar isso em vez disso!",
  ui_story_5086_50860100_48_dialog_content = "<color=#e8d9bb>A jovem garota de repente cobre seu olho direito com a mão.</color>",
  ui_story_5086_50860100_49_dialog_content = "Como só consigo ver metade de você, isso significa que tenho que considerar você como sendo metade da sua idade normal!",
  ui_story_5086_50860100_50_dialog_content = "Ótimo, agora você pode entrar de graça!",
  ui_story_5086_50860100_51_dialog_content = "Desculpe, senhorita... Maya, certo? Eu agradeço o pensamento, mas vim aqui por um assunto bastante sério. Se me der licença-",
  ui_story_5086_50860100_52_dialog_content = "<color=#e8d9bb>Pimba!</color>",
  ui_story_5086_50860100_53_dialog_content = "Ah! Eu sinto muito!",
  ui_story_5086_50860100_54_dialog_content = "Essa voz...",
  ui_story_5086_50860100_55_dialog_content = "Perdoe a interrupção, senhorita, mas meu companheiro acidentalmente derrubou seu cartaz de exibição na entrada.",
  ui_story_5086_50860100_56_dialog_content = "Por favor, permita-nos compensá-lo integralmente pelos danos.",
  ui_story_5086_50860100_57_dialog_content = "Tudo bem, eu apenas rabisquei aquele sinal eu mesmo. Estou apenas feliz que nenhum de vocês se machucou.",
  ui_story_5086_50860100_58_dialog_content = "Eu realmente, verdadeiramente sinto muito por isso...",
  ui_story_5086_50860100_59_dialog_content = "Minos! Sanae! Realmente são vocês dois!",
  ui_story_5086_50860100_60_dialog_content = "Sr. PlayerName! Não esperava te ver aqui... Ah! Me desculpe, essa não é maneira de cumprimentar um amigo!",
  ui_story_5086_50860100_61_dialog_content = "Um, c-como você tem estado...",
  ui_story_5086_50860100_62_dialog_content = "Eu tenho estado bem, Sanae. É bom ver você e Minos novamente.",
  ui_story_5086_50860100_63_dialog_content = "Bom dia, Sr. PlayerName. Fico feliz em ver que você está bem depois de todo esse tempo.",
  ui_story_5086_50860100_64_dialog_content = "Nina não está com vocês?",
  ui_story_5086_50860100_65_dialog_content = "Receio que não... A senhorita Nina está atualmente ocupada com um novo design... então ela me pediu para... conduzir uma investigação da indústria em seu lugar.",
  ui_story_5086_50860100_66_dialog_content = "De fato. Eu, por outro lado, estou aqui para ajudar no assunto.",
  ui_story_5086_50860100_67_dialog_content = "... Tem certeza de que não está confundindo seus papéis?",
  ui_story_5086_50860100_68_dialog_content = "Não se preocupe, senhor. Embora Sanae ainda tenha muito a aprender como donzela—",
  ui_story_5086_50860100_69_dialog_content = "Como alguém da mesma idade que nossa mocinha, ela acontece de compartilhar várias de suas sensibilidades nobres também.",
  ui_story_5086_50860100_70_dialog_content = "O mais importante, no entanto, é o fato de que a senhorita Nina estava disposta a depositar sua confiança nela.",
  ui_story_5086_50860100_71_dialog_content = "Enquanto ela continuar a atender às expectativas de nossa senhora, não tenho motivo para interferir em seus deveres.",
  ui_story_5086_50860100_72_dialog_content = "Minha senhora deseja se envolver nesta indústria, mas como mordomo da família Andersen, se eu descobrir que existem muitos fatores instáveis em jogo...",
  ui_story_5086_50860100_73_dialog_content = "O olhar em seus olhos de repente é muito mais aterrorizante, Minos.",
  ui_story_5086_50860100_74_dialog_content = "É mesmo? Então, por favor, perdoe minha grosseria. Eu simplesmente quis dizer que tomaria uma ação corretiva se fosse esse o caso.",
  ui_story_5086_50860100_75_dialog_content = "<color=#e8d9bb>De repente, um grande alvoroço pode ser ouvido logo fora da porta—</color>",
  ui_story_5086_50860100_76_dialog_content = "O que está acontecendo lá fora?",
  ui_story_5086_50860100_77_dialog_content = "Maya, venha rápido! Algumas pessoas suspeitas estão tentando entrar no aquário!",
  ui_story_5086_50860100_78_dialog_content = "<color=#e8d9bb>Um casal de crianças aparece na porta, bloqueando freneticamente a entrada de duas pessoas pesadamente vestidas.</color>",
  ui_story_5086_50860100_79_dialog_content = "Skado! Sebastian! Formações defensivas! Não deixem nenhum desses dois invadir o saguão!",
  ui_story_5086_50860100_80_dialog_content = "Mais fácil falar do que fazer, Froude! O baixinho não deve ser um problema, mas como vamos impedir aquele cara alto de entrar?",
  ui_story_5086_50860100_81_dialog_content = "Ratos... Isso é realmente o fim?",
  ui_story_5086_50860100_82_dialog_content = "Heheheh, vocês crianças são tão enérgicas, mas posso garantir, não somos caras maus.",
  ui_story_5086_50860100_83_dialog_content = "Isso é exatamente o que um cara mau diria!",
  ui_story_5086_50860100_84_dialog_content = "Além disso, quem veste tanta roupa para o aquário quando está tão quente lá fora?",
  ui_story_5086_50860100_85_dialog_content = "Se você não consegue apreciar a legalidade de nossas roupas, então ainda tem um longo caminho a percorrer antes de poder se chamar de fanfarrões como nós.",
  ui_story_5086_50860100_86_dialog_content = "Swash-que agora?",
  ui_story_5086_50860100_87_dialog_content = "O quê—Você quer dizer que não sabe sobre a profissão mais legal do mundo? Então permita-me—",
  ui_story_5086_50860100_88_dialog_content = "Tudo bem, vocês dois, isso é o suficiente agora.",
  ui_story_5086_50860100_89_dialog_content = "!",
  ui_story_5086_50860100_90_dialog_content = "<color=#e8d9bb>Em algum momento durante a discussão, Maya conseguiu aparecer atrás deles de alguma forma.</color>",
  ui_story_5086_50860100_91_dialog_content = "<color=#e8d9bb>Com um único movimento ágil, ela arranca os óculos de sol e as máscaras de seus rostos.</color>",
  ui_story_5086_50860100_92_dialog_content = "Goldie? Sadie?",
  ui_story_5086_50860100_93_dialog_content = "Uh-oh...",
  ui_story_5086_50860100_94_dialog_content = "Ela se aproximou de nós sem chamar nossa atenção de forma alguma! Quem no mundo é você?",
  ui_story_5086_50860100_95_dialog_content = "Meu nome é Maya. Sou uma funcionária aqui no aquário.",
  ui_story_5086_50860100_96_dialog_content = "Desculpe, mas tenho que pedir para você evitar usar roupas tão assustadoras aqui. Há muitas crianças correndo pelo aquário, sabe.",
  ui_story_5086_50860100_97_dialog_content = "Além disso, você não preferiria aproveitar para ver todas as lindas criaturas do mar sem usar tudo isso?",
  ui_story_5086_50860100_98_dialog_content = "Humpf, eu não vim aqui para me divertir.",
  ui_story_5086_50860100_99_dialog_content = "Ouvi falar sobre algo terrível acontecendo em Harbor City. Como um nobre espadachim, vim aqui para fazer justiça!",
  ui_story_5086_50860100_100_dialog_content = "Algo terrível? Em Harbour City?",
  ui_story_5086_50860100_101_dialog_content = "Por favor, não ofenda nossos convidados, Maya.",
  ui_story_5086_50860100_102_dialog_content = "Mas Senhorita Stellandine—",
  ui_story_5086_50860100_103_dialog_content = "Peço desculpas a todos. Meu nome é Stellandine e sou a proprietária deste aquário.",
  ui_story_5086_50860100_104_dialog_content = "Meu funcionário pode agir um pouco precipitadamente às vezes. Desculpe se isso impactou negativamente sua visita ao nosso estabelecimento hoje.",
  ui_story_5086_50860100_105_dialog_content = "Não, nós também temos culpa aqui.",
  ui_story_5086_50860100_106_dialog_content = "Então, como proprietária do aquário, permita-me convidar todos vocês para uma refeição como um sinal de nosso pedido de desculpas.",
  ui_story_5086_50860100_107_dialog_content = "Antes disso, sinta-se à vontade para observar qualquer uma das exposições que temos a oferecer.",
  ui_story_5086_50860100_108_dialog_content = "Mas, como diz Maya, muitos de nossos convidados são crianças pequenas, então, por favor, evite qualquer comportamento que possa perturbá-las.",
  ui_story_5086_50860100_109_dialog_content = "Se tiver mais alguma dúvida, pode me perguntar a qualquer momento.",
  ui_story_5086_50860100_110_dialog_content = "Não vamos interromper sua visualização por mais tempo. Venha, Maya.",
  ui_story_5086_50860100_111_dialog_content = "Mas o sinal de exibição na entrada...",
  ui_story_5086_50860100_112_dialog_content = "Ainda preciso organizar alguns arquivos. Você poderia me ajudar com isso?",
  ui_story_5086_50860100_113_dialog_content = "Com certeza! Deixe comigo!",
  ui_story_5086_50860100_114_dialog_content = "Que chefe bondoso.",
  ui_story_5086_50860100_115_dialog_content = "De qualquer forma, há tantos rostos familiares aqui hoje.",
  ui_story_5086_50860100_116_dialog_content = "A última vez que algo assim aconteceu foi na Casa Assombrada Andersen, e então...",
  ui_story_5086_50860100_117_dialog_content = "Mesmo que eu não ache que algo assim acontecerá novamente, devo perguntar sobre isso apenas para estar seguro.",
  ui_story_5086_50860100_118_dialog_content = "Oi Sadie, qual é essa coisa terrível que você ouviu falar?",
  ui_story_5086_50860100_119_dialog_content = "Ah sim, aquela coisa terrível! Qualquer verdadeiro espadachim viria correndo até mesmo ao menor sinal de problemas!",
  ui_story_5086_50860100_120_dialog_content = "Então... Isso significa que você veio aqui só porque ouviu um boato?",
  ui_story_5086_50860100_121_dialog_content = "Pode ter sido apenas um rumor, mas é ver pra acreditar, afinal.",
  ui_story_5086_50860100_122_dialog_content = "Se houver algum sinal de perigo, tenho o dever de confrontá-lo. Mesmo que se revele um boato, não me sentirei à vontade até ver a verdade com meus próprios olhos.",
  ui_story_5086_50860100_123_dialog_content = "Prevenir até mesmo as crises mais improváveis de acontecer é tudo parte de ser um fanfarrão!",
  ui_story_5086_50860100_124_dialog_content = "A verdade é, nos deparamos com uma série de rumores preocupantes.",
  ui_story_5086_50860100_125_dialog_content = "Mas cada um era um pouco diferente do último. Algumas pessoas afirmavam que uma baleia colossal estava à espreita nas águas de Harbour City, esperando para devorar qualquer um tolo o suficiente para nadar no mar.",
  ui_story_5086_50860100_126_dialog_content = "Outros afirmaram que as pessoas continuavam desaparecendo após pegar cartões estranhos espalhados pela cidade.",
  ui_story_5086_50860100_127_dialog_content = "Foi muito difícil discernir a verdade todo o caminho desde Umbraton, então Sadie insistiu em vir aqui e verificar as coisas por si mesma.",
  ui_story_5086_50860100_128_dialog_content = "Sempre há uma chance de que isso possa levar a uma batalha gloriosa e fatídica, uma que fará meu nome famoso em toda a terra.",
  ui_story_5086_50860100_129_dialog_content = "Eu estava um pouco preocupado com Sadie vindo para cá sozinho, então decidi acompanhar.",
  ui_story_5086_50860100_130_dialog_content = "Mas realmente, não esperávamos te encontrar aqui, PlayerName. Que feliz coincidência!",
  ui_story_5086_50860100_131_dialog_content = "Vejo que o Sr. Minos também está aqui, é melhor irmos dizer olá. Gostaria de vir conosco, PlayerName?",
  ui_story_5086_50860100_132_dialog_content = "Na verdade, tenho algo importante para resolver agora.",
  ui_story_5086_50860100_133_dialog_content = "Então tá, esperamos te ver por aí novamente!",
  ui_story_5086_50860100_134_dialog_content = "Claro.",
  ui_story_5086_50860100_135_dialog_content = "(Se ao menos eu pudesse me deparar com a mensagem de Jeno assim também.)",
  ui_story_5086_50860201_1_dialog_content = "Isso é exaustivo.",
  ui_story_5086_50860201_2_dialog_content = "Estive andando em círculos o dia todo, mas ainda não encontrei nada.",
  ui_story_5086_50860201_3_dialog_content = "Talvez eu vá apenas fazer uma pausa na área de descanso por enquanto.",
  ui_story_5086_50860201_4_dialog_content = "Jeno disse que deixou uma mensagem para mim aqui, o que significa que ele provavelmente a confiou a alguém.",
  ui_story_5086_50860201_5_dialog_content = "Como ele também incluiu o endereço deste aquário, deve significar que essa pessoa está em algum lugar por aqui.",
  ui_story_5086_50860201_6_dialog_content = "Essas são as únicas duas pistas que tenho agora.",
  ui_story_5086_50860201_7_dialog_content = "Tenho quase certeza de que é apenas uma coincidência que tantos dos meus amigos também estão aqui, mas talvez um deles seja o mensageiro? Se for, devo perguntar a eles sobre isso?",
  ui_story_5086_50860201_8_dialog_content = "Não, isso iria contra o propósito de manter as coisas em segredo. Não seria diferente de contar a todo o Astra sobre isso.",
  ui_story_5086_50860201_9_dialog_content = "Isso conclui o evento interativo de hoje, todos! É hora do nosso adorável estrela-do-mar ir para casa para um merecido descanso.",
  ui_story_5086_50860201_10_dialog_content = "Também é hora de vocês, crianças, irem para casa. Lembrem-se de não brincar na rua no caminho de volta.",
  ui_story_5086_50860201_11_dialog_content = "Ah! Mas ainda é tão cedo! Eu não quero ir para casa ainda! E você ainda não nos contou uma história!",
  ui_story_5086_50860201_12_dialog_content = "Suas histórias são sempre tão divertidas, Maya!",
  ui_story_5086_50860201_13_dialog_content = "Eu também quero ouvir um.",
  ui_story_5086_50860201_14_dialog_content = "Você nos prometeu uma história na semana passada, mas parece que você já esqueceu, Maya.",
  ui_story_5086_50860201_15_dialog_content = "Ah, é mesmo? Eu realmente devo ter esquecido... Desculpe.",
  ui_story_5086_50860201_16_dialog_content = "Venha sentar conosco, Maya.",
  ui_story_5086_50860201_17_dialog_content = "Certo, vou te contar uma história que li outro dia, mas depois disso, você tem que ir direto para casa. Combinado?",
  ui_story_5086_50860201_18_dialog_content = "Negócio!",
  ui_story_5086_50860201_19_dialog_content = "Há muito, muito tempo atrás, havia um garoto que se perdeu durante suas viagens...",
  ui_story_5086_50860201_20_dialog_content = "(Bem, Jeno provavelmente não sabia quando eu viria procurar sua mensagem.)",
  ui_story_5086_50860201_21_dialog_content = "(Em vez de confiar a um viajante, ele provavelmente escolheu alguém que está quase sempre no aquário.)",
  ui_story_5086_50860201_22_dialog_content = "(Além de Maya, a única outra pessoa que se encaixa é a proprietária...)",
  ui_story_5086_50860201_23_dialog_content = "(Assim que ela terminar de contar a história, tentarei trazer o assunto discretamente.)",
  ui_story_5086_50860201_24_dialog_content = "Ele viajou por florestas densas e desertos vazios e até chegou às margens do mar na borda do mundo. Mas, durante todo o tempo, ele nunca conseguiu descobrir para qual direção estava indo.",
  ui_story_5086_50860201_25_dialog_content = "Ele me soa meio bobo.",
  ui_story_5086_50860201_26_dialog_content = "Se eu fosse ele, traria toneladas de mapas comigo para nunca me perder.",
  ui_story_5086_50860201_27_dialog_content = "Eu vejo! Você gosta de se preparar para tudo, não é Skado?",
  ui_story_5086_50860201_28_dialog_content = "Mas o garoto desta história não teve tanta sorte.",
  ui_story_5086_50860201_29_dialog_content = "Embora geralmente estivesse cercado por seus amigos, havia algumas jornadas que ele tinha que enfrentar sozinho.",
  ui_story_5086_50860201_30_dialog_content = "Mas, felizmente, um pequeno gatinho apareceu para salvá-lo de sua solidão.",
  ui_story_5086_50860201_31_dialog_content = "Era um gato muito amigável. Sem mais nada para fazer, o garoto decidiu brincar com ele.",
  ui_story_5086_50860201_32_dialog_content = "Então, os dois deram um passeio pela praia e observaram as ondas espumosas quebrando sobre o recife de corais.",
  ui_story_5086_50860201_33_dialog_content = "Eles observaram enquanto os peixes voadores saltavam da água com um ruído de assobio.",
  ui_story_5086_50860201_34_dialog_content = "Eles rolaram na areia e riram enquanto observavam um caranguejo desajeitado cambaleando para frente e para trás.",
  ui_story_5086_50860201_35_dialog_content = "No final do dia, eles se enrolaram sob uma palmeira e deixaram a suave brisa do mar levá-los ao sono.",
  ui_story_5086_50860201_36_dialog_content = "Parece tão bom!",
  ui_story_5086_50860201_37_dialog_content = "Quando o garotinho acordou, ficou chocado ao ver uma pequena cidade diante de seus olhos.",
  ui_story_5086_50860201_38_dialog_content = "Eu digo que era uma pequena cidade, mas era tão movimentada quanto uma grande cidade. Havia lojas de armas, lojas de itens e todos os tipos de pousadas.",
  ui_story_5086_50860201_39_dialog_content = "As ruas estavam cheias de bravos aventureiros equipados com todos os tipos de armas e armaduras, bem como viajantes em trajes maravilhosos.",
  ui_story_5086_50860201_40_dialog_content = "Na verdade, havia um monstro do mar escondido em algum lugar da cidade.",
  ui_story_5086_50860201_41_dialog_content = "Durante o dia, tudo estava perfeitamente tranquilo. Mas à noite, um som de lamento podia ser ouvido vindo do mar.",
  ui_story_5086_50860201_42_dialog_content = "Foi um som tão aterrorizante, então todos pensaram que era o grito de um monstro marinho.",
  ui_story_5086_50860201_43_dialog_content = "Deve ser por isso que havia tantos aventureiros na cidade! Aposto que eles pensaram que quem derrotasse o monstro poderia reivindicar seu tesouro!",
  ui_story_5086_50860201_44_dialog_content = "Faz sentido, já que existem muitas pessoas que pensam como você, Froude. Mas por que havia tantos viajantes também?",
  ui_story_5086_50860201_45_dialog_content = "Se houvesse um monstro naquela cidade, eu nunca iria querer ir lá por nada.",
  ui_story_5086_50860201_46_dialog_content = "Talvez fosse porque o monstro nunca mostrou seu verdadeiro rosto, mesmo que seus gritos fossem tão assustadores. Não importa quantas pessoas aparecessem, ele nunca aparecia diante de ninguém.",
  ui_story_5086_50860201_47_dialog_content = "Embora houvesse muitas pessoas que afirmavam ter visto o monstro, o resto da cidade descobriu que todos estavam mentindo.",
  ui_story_5086_50860201_48_dialog_content = "Então os rumores em torno do monstro assustador só pioraram.",
  ui_story_5086_50860201_49_dialog_content = "(Ei, eu também já li essa história antes.)",
  ui_story_5086_50860201_50_dialog_content = "(Se eu me lembro corretamente, termina com o garoto e o gato descobrindo uma caverna escondida.)",
  ui_story_5086_50860201_51_dialog_content = "(Em vez de encontrar um monstro marinho lá, tudo que encontraram foi uma garotinha chorando sozinha.)",
  ui_story_5086_50860201_52_dialog_content = "(Ela não tinha família ou amigos, então passava todas as noites chorando sozinha naquela caverna.)",
  ui_story_5086_50860201_53_dialog_content = "(O choro silencioso dela ecoava pela caverna até que toda a cidade pudesse ouvi-lo, foi assim que começaram os rumores sobre o monstro do mar.)",
  ui_story_5086_50860201_54_dialog_content = "(O garotinho a animou e prometeu ser seu amigo.)",
  ui_story_5086_50860201_55_dialog_content = "(Depois disso, a vila nunca mais ouviu o \"monstro do mar\" à noite, mas...)",
  ui_story_5086_50860201_56_dialog_content = "Mas...",
  ui_story_5086_50860201_57_dialog_content = "(Huh? Ela já está nesta parte da história?)",
  ui_story_5086_50860201_58_dialog_content = "Infelizmente, não me lembro do resto da história!",
  ui_story_5086_50860201_59_dialog_content = "Pffft! *Cof Cof*...",
  ui_story_5086_50860201_60_dialog_content = "Sabia...",
  ui_story_5086_50860201_61_dialog_content = "Isso não é surpreendente de jeito nenhum...",
  ui_story_5086_50860201_62_dialog_content = "Está bem, já estamos acostumados.",
  ui_story_5086_50860201_63_dialog_content = "Todos nós sabemos como a memória de Maya é ruim, afinal. Às vezes, ela até esquece coisas que aconteceram cinco minutos atrás.",
  ui_story_5086_50860201_64_dialog_content = "Isso realmente nos faz preocupar.",
  ui_story_5086_50860201_65_dialog_content = "Hahaha, eu realmente não tenho certeza de como proceder...",
  ui_story_5086_50860201_66_dialog_content = "O que vocês crianças fariam se estivessem no lugar do garotinho?",
  ui_story_5086_50860201_67_dialog_content = "Ah, eu sei! Eu iria direto para uma loja de armas para comprar uma nova espada e escudo!",
  ui_story_5086_50860201_68_dialog_content = "Não gosto de lutar, mas compraria uma poção de cura apenas para estar seguro.",
  ui_story_5086_50860201_69_dialog_content = "Ambos fazem bons pontos. Tenho certeza de que o garotinho também pensa assim.",
  ui_story_5086_50860201_70_dialog_content = "(De jeito nenhum! E quando isso se transformou em uma história de alta fantasia?)",
  ui_story_5086_50860201_71_dialog_content = "Após comprar um conjunto completo de equipamentos, o garotinho partiu para a toca do monstro marinho e o desafiou para uma batalha final.",
  ui_story_5086_50860201_72_dialog_content = "Ele passou por anos de treinamento e superou inúmeros obstáculos—",
  ui_story_5086_50860201_73_dialog_content = "(A história só acontece em uma pequena cidade, porém!)",
  ui_story_5086_50860201_74_dialog_content = "O enorme monstro marinho finalmente reconheceu o poder e a bravura do garoto, e então ele se levantou das profundezas para aceitar seu desafio!",
  ui_story_5086_50860201_75_dialog_content = "Deseja reivindicar meu tesouro? Então você deve primeiro me derrotar em batalha!",
  ui_story_5086_50860201_76_dialog_content = "O monstro do mar riu arrogantemente do garotinho.",
  ui_story_5086_50860201_77_dialog_content = "(Com certeza já li essas linhas em algum outro lugar antes! Ela está começando a contar uma história completamente diferente!)",
  ui_story_5086_50860201_78_dialog_content = "Uau!",
  ui_story_5086_50860201_79_dialog_content = "E assim o garoto desembainhou sua lâmina e enfrentou a enorme fera em uma última batalha!",
  ui_story_5086_50860302_1_dialog_content = "<color=#e8d9bb>Enquanto as crianças comemoram animadamente a história de Maya, mais algumas pessoas entram na área de descanso.</color>",
  ui_story_5086_50860302_2_dialog_content = "Parece que podemos fazer uma pausa rápida aqui, Sadie.",
  ui_story_5086_50860302_3_dialog_content = "Mas ainda não encontramos nenhuma pista sobre a coisa terrível que está acontecendo aqui!",
  ui_story_5086_50860302_4_dialog_content = "Pode parecer calmo e tranquilo por aqui, mas alguém pode estar precisando desesperadamente de nossa ajuda agora. Não podemos nos dar ao luxo de relaxar.",
  ui_story_5086_50860302_5_dialog_content = "Eu sei como você se sente, mas você tem corrido por aí desde que acordou esta manhã.",
  ui_story_5086_50860302_6_dialog_content = "Já procuramos quase metade da cidade por sinais de perigo. Nesse ritmo, vamos nos esgotar antes de conseguirmos ajudar alguém.",
  ui_story_5086_50860302_7_dialog_content = "Equilibrar trabalho e descanso, manter-se em ótima condição física—",
  ui_story_5086_50860302_8_dialog_content = "É assim que os ídolos se mantêm no topo de seus jogos... e tenho certeza de que o mesmo se aplica aos fanfarrões.",
  ui_story_5086_50860302_9_dialog_content = "Douradinho...",
  ui_story_5086_50860302_10_dialog_content = "O que seria?",
  ui_story_5086_50860302_11_dialog_content = "O que você disse agora... Foi realmente muito legal.",
  ui_story_5086_50860302_12_dialog_content = "Entendo. Vou descansar o máximo que posso agora mesmo!",
  ui_story_5086_50860302_13_dialog_content = "Uh, claro. Vamos passar as próximas horas recuperando nossas forças.",
  ui_story_5086_50860302_14_dialog_content = "Já exploramos Harbour City durante o dia, então talvez nosso próximo passo seja vigiar a cidade à noite.",
  ui_story_5086_50860302_15_dialog_content = "Afinal, muitas coisas só se mostram sob o manto da escuridão.",
  ui_story_5086_50860302_16_dialog_content = "Eu mesma não poderia ter dito melhor, Senhorita Goldie.",
  ui_story_5086_50860302_17_dialog_content = "Sanae, seria bom você também realizar uma observação noturna.",
  ui_story_5086_50860302_18_dialog_content = "Ah... Entendido! Assim que voltarmos... Não, vou começar a planejar minha nova tarefa de investigação agora mesmo!",
  ui_story_5086_50860302_19_dialog_content = "Eu pretendia te perguntar sobre isso antes.",
  ui_story_5086_50860302_20_dialog_content = "O que exatamente vocês dois estão investigando? Qual nova indústria a Nina está tentando entrar?",
  ui_story_5086_50860302_21_dialog_content = "Peço que você se abstenha de me procurar por respostas, Sanae. Afinal, esta é a sua tarefa.",
  ui_story_5086_50860302_22_dialog_content = "Uh... O-Ok então, deixa eu te explicar...",
  ui_story_5086_50860302_23_dialog_content = "Bem, hum, você vê, a Srta. Nina diz que um verdadeiro empresário não se limita a apenas uma indústria, e então...",
  ui_story_5086_50860302_24_dialog_content = "E assim, ela quer criar uma cadeia de negócios expandindo além da casa mal-assombrada.",
  ui_story_5086_50860302_25_dialog_content = "Muitas mudanças têm acontecido aqui em Harbor City, então a Senhorita Nina nos pediu para vir e procurar possíveis oportunidades de negócio.",
  ui_story_5086_50860302_26_dialog_content = "Como comprar um aquário bem conhecido e usá-lo para treinar novos funcionários, depois abrir um semelhante em Umbraton... ou algo assim...",
  ui_story_5086_50860302_27_dialog_content = "A ideia de abrir um aquário em Umbraton enche minha cabeça com algumas imagens bem assustadoras...",
  ui_story_5086_50860302_28_dialog_content = "Você não acha que deveriam reconsiderar? Até onde eu sei, Umbraton nunca teve algo assim antes.",
  ui_story_5086_50860302_29_dialog_content = "Isso... Isso é o que torna uma oportunidade tão única! Umbraton também fica perto de um corpo de água, então faz sentido.",
  ui_story_5086_50860302_30_dialog_content = "Não são vocês que me preocupam, mas os seus futuros visitantes.",
  ui_story_5086_50860302_31_dialog_content = "Mas a senhorita Nina está determinada a estabelecer essa cadeia de negócios... é por isso que eu tenho que...",
  ui_story_5086_50860302_32_dialog_content = "A-De qualquer forma, ainda tenho que perguntar se eles querem vender o aquário—",
  ui_story_5086_50860302_33_dialog_content = "Nós nunca faríamos isso!",
  ui_story_5086_50860302_34_dialog_content = "Maya? Você não estava contando uma história para aquelas crianças? ... Ah, eles já foram para casa.",
  ui_story_5086_50860302_35_dialog_content = "Eu não sei o que vocês dois estão procurando, mas—",
  ui_story_5086_50860302_36_dialog_content = "Este aquário existe para trazer um sorriso a cada convidado que passa por suas portas.",
  ui_story_5086_50860302_37_dialog_content = "É um lugar cheio de lembranças queridas e felizes, e isso significa muito para as pessoas daqui.",
  ui_story_5086_50860302_38_dialog_content = "Nenhuma quantidade de dinheiro jamais poderia comprá-lo.",
  ui_story_5086_50860302_39_dialog_content = "Ah... D-Desculpe...",
  ui_story_5086_50860302_40_dialog_content = "Você está sendo rude com nossos convidados de novo, Maya?",
  ui_story_5086_50860302_41_dialog_content = "Não acho que eu tenha dito algo errado.",
  ui_story_5086_50860302_42_dialog_content = "Você também acha, não é, Senhorita Stellandine? Afinal, você é quem mais desistiu por causa deste aquário.",
  ui_story_5086_50860302_43_dialog_content = "Heheh, estou feliz que você pense tão bem de mim, Maya.",
  ui_story_5086_50860302_44_dialog_content = "Mas ainda temos que ganhar algum dinheiro.",
  ui_story_5086_50860302_45_dialog_content = "Como mais posso cuidar de você e do resto dos nossos amigos aqui no aquário?",
  ui_story_5086_50860302_46_dialog_content = "Eles já foram forçados a sair de suas casas no mar. Tudo que posso fazer é tornar suas vidas aqui o mais confortável possível.",
  ui_story_5086_50860302_47_dialog_content = "Tenho feito o meu melhor para ganhar dinheiro e cuidar de todos também! Um... Só um segundo, por favor!",
  ui_story_5086_50860302_48_dialog_content = "Dê uma olhada nisso, Senhorita Stellandine! Já fiz duzentos e trinta e três Noitium para nós!",
  ui_story_5086_50860302_49_dialog_content = "Isso é incrível, Maya! Tenho certeza que o cofrinho no seu quarto também foi bem alimentado.",
  ui_story_5086_50860302_50_dialog_content = "Heehee!",
  ui_story_5086_50860302_51_dialog_content = "Se algum dia tiver problemas com dinheiro, pode sempre contar com a minha ajuda, Senhorita Stellandine!",
  ui_story_5086_50860302_52_dialog_content = "Não me importo em te dar todo o último Nightium se for para o aquário.",
  ui_story_5086_50860302_53_dialog_content = "Obrigado, Maya. Estarei contando com você.",
  ui_story_5086_50860302_54_dialog_content = "Apenas deixe comigo!",
  ui_story_5086_50860302_55_dialog_content = "Meu... Que surpresa.",
  ui_story_5086_50860302_56_dialog_content = "Você disse alguma coisa? Minos?",
  ui_story_5086_50860302_57_dialog_content = "Nada mesmo, meu caro amigo. Não me dê atenção, estou apenas fazendo algumas anotações insignificantes.",
  ui_story_5086_50860302_58_dialog_content = "Afinal, observar o ambiente cultural local também é parte de nossa investigação.",
  ui_story_5086_50860302_59_dialog_content = "Você é tão diligente como sempre, Minos.",
  ui_story_5086_50860302_60_dialog_content = "Mas é claro.",
  ui_story_5086_50860401_1_dialog_content = "Já que todos já se reuniram aqui, talvez seja hora de cumprir minha palavra.",
  ui_story_5086_50860401_2_dialog_content = "Gostaria de se juntar a nós para almoçar?",
  ui_story_5086_50860401_3_dialog_content = "Claro! Eu também estava começando a sentir fome.",
  ui_story_5086_50860401_4_dialog_content = "Não faço ideia de como é a comida de Harbour City, mas estou realmente ansioso para experimentá-la.",
  ui_story_5086_50860401_5_dialog_content = "Maya, vamos mostrar aos nossos convidados o restaurante.",
  ui_story_5086_50860401_6_dialog_content = "OK! Por aqui, todos!",
  ui_story_5086_50860401_7_dialog_content = "Também vamos, Minos?",
  ui_story_5086_50860401_8_dialog_content = "Por favor, não se preocupem por nossa causa.",
  ui_story_5086_50860401_9_dialog_content = "Sanae ainda precisa compilar seu relatório sobre as descobertas desta manhã.",
  ui_story_5086_50860401_10_dialog_content = "Assim que ela terminar o trabalho dela, eu a acompanharei até o restaurante.",
  ui_story_5086_50860401_11_dialog_content = "Por favor, aproveite sua refeição.",
  ui_story_5086_50860401_12_dialog_content = "Huh? Q-Quero dizer... sim, estaremos aí em breve.",
  ui_story_5086_50860401_13_dialog_content = "Continue com o bom trabalho, Sanae.",
  ui_story_5086_50860401_14_dialog_content = "Eu... Farei o meu melhor...",
  ui_story_5086_50860401_15_dialog_content = "Veremos vocês daqui a pouco então... Espere, para qual lado Maya e Stellandine foram?",
  ui_story_5086_50860401_16_dialog_content = "Além da exposição de tubarões à esquerda, há uma escada. Siga-a até o segundo andar e vire à esquerda, então você encontrará o restaurante.",
  ui_story_5086_50860401_17_dialog_content = "Obrigado, Minos.",
  ui_story_5086_50860401_18_dialog_content = "Vire à esquerda no segundo andar... Huh, eu me pergunto por que Minos sabe como chegar aqui...",
  ui_story_5086_50860401_19_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5086_50860401_20_dialog_content = "Ai...",
  ui_story_5086_50860401_21_dialog_content = "Maya! Me desculpe, eu não te vi correndo por aqui.",
  ui_story_5086_50860401_22_dialog_content = "Tudo bem?",
  ui_story_5086_50860401_23_dialog_content = "Heehee, estou bem! Além disso, eu deveria estar me desculpando.",
  ui_story_5086_50860401_24_dialog_content = "Eu estava tão ocupado liderando o caminho que esqueci de ver se você ainda estava seguindo... Ah!",
  ui_story_5086_50860401_25_dialog_content = "<color=#e8d9bb>Com um susto, Maya de repente tira seu caderno e folheia-o freneticamente.</color>",
  ui_story_5086_50860401_26_dialog_content = "Oh não. Onde eu anotei isso?",
  ui_story_5086_50860401_27_dialog_content = "O que você está procurando?",
  ui_story_5086_50860401_28_dialog_content = "Sinto muito, senhor.",
  ui_story_5086_50860401_29_dialog_content = "Mas parece que esqueci de anotar seu nome!",
  ui_story_5086_50860401_30_dialog_content = "Não acho que você vai encontrar isso nas suas anotações. Afinal, eu ainda não me apresentei adequadamente.",
  ui_story_5086_50860401_31_dialog_content = "Meu nome é PlayerName, e eu sou um celestita. É um prazer conhecer você, Maya.",
  ui_story_5086_50860401_32_dialog_content = "Eu sou Maya, uma estagiária trabalhando no aquário!",
  ui_story_5086_50860401_X32_dialog_content = "E agora que nos apresentamos, isso nos torna amigos!",
  ui_story_5086_50860401_33_dialog_content = "Por aqui, PlayerName! Não foi fácil, mas eu guardei o melhor lugar da casa só para você.",
  ui_story_5086_50860401_34_dialog_content = "Uau, eu consigo ver o tanque inteiro daqui de cima!",
  ui_story_5086_50860401_35_dialog_content = "Que vista incrível para acompanhar nosso almoço!",
  ui_story_5086_50860401_36_dialog_content = "O restaurante é tão grande e luxuoso também. Isso é realmente uma parte do aquário?",
  ui_story_5086_50860401_37_dialog_content = "Você é muito perspicaz, PlayerName.",
  ui_story_5086_50860401_38_dialog_content = "Falando estritamente, este restaurante não pertence apenas ao nosso aquário, não.",
  ui_story_5086_50860401_39_dialog_content = "Devido ao rápido desenvolvimento de resorts turísticos na área, alguns dos pequenos negócios locais sofreram sérios contratempos financeiros.",
  ui_story_5086_50860401_40_dialog_content = "Para aliviar parte da tensão, vários empresários decidiram se unir para competir na crescente indústria do turismo.",
  ui_story_5086_50860401_41_dialog_content = "Este restaurante é apenas um desses empreendimentos.",
  ui_story_5086_50860401_42_dialog_content = "Todos trabalham muito duro para este restaurante, e a comida aqui é incrível!",
  ui_story_5086_50860401_43_dialog_content = "No meu primeiro dia aqui, estava determinado a comer todos os pratos do cardápio.",
  ui_story_5086_50860401_44_dialog_content = "Mas até hoje, só consegui experimentar alguns deles.",
  ui_story_5086_50860401_45_dialog_content = "Ainda há muito tempo, Maya. Não precisa ter pressa.",
  ui_story_5086_50860401_46_dialog_content = "Agora então, o que devemos comer hoje?",
  ui_story_5086_50860401_47_dialog_content = "Isso depende, o que nós comemos ontem? Hmm...",
  ui_story_5086_50860401_48_dialog_content = "Eu não anotei isso nas minhas notas. Eu esqueci de fazer isso também?",
  ui_story_5086_50860401_49_dialog_content = "Ah bem, peça o que você quiser—",
  ui_story_5086_50860401_50_dialog_content = "Vou perguntar a um dos garçons sobre o que você comeu ontem.",
  ui_story_5086_50860401_51_dialog_content = "Ah, você não precisa fazer isso. Não é nada demais ou algo assim.",
  ui_story_5086_50860401_52_dialog_content = "Mas você estabeleceu uma meta para si mesma, não foi Maya?",
  ui_story_5086_50860401_53_dialog_content = "Não é problema nenhum. Mesmo que você esqueça seus pedidos, o restaurante tem um cardápio só para você, na verdade.",
  ui_story_5086_50860401_54_dialog_content = "Você está sempre tão disposto a ajudar a todos, então eles querem ajudá-lo a realizar seu objetivo também.",
  ui_story_5086_50860401_55_dialog_content = "Eu volto já.",
  ui_story_5086_50860401_56_dialog_content = "A Srta. Stellandine é uma pessoa tão legal.",
  ui_story_5086_50860401_57_dialog_content = "Certo? Ela é a pessoa mais simpática do mundo inteiro!",
  ui_story_5086_50860401_58_dialog_content = "Ela é tão gentil e delicada, e cuida pessoalmente de todos os animais no aquário.",
  ui_story_5086_50860401_59_dialog_content = "Não só isso, mas ela me disse que o aquário poderia ser meu lar quando eu não tivesse para onde ir.",
  ui_story_5086_50860401_60_dialog_content = "Hã? Então isso significa que você é novo aqui?",
  ui_story_5086_50860401_61_dialog_content = "Sério, PlayerName? Eu sei que sou esquecida e meio desastrada, mas não sou completamente inútil, sabe!",
  ui_story_5086_50860401_62_dialog_content = "Se eu estivesse aqui há muito tempo, você realmente acha que eu ainda seria um estagiário?",
  ui_story_5086_50860401_63_dialog_content = "Eu poderia dizer muito mais sobre isso... mas você realmente tem um bom ponto, Maya.",
  ui_story_5086_50860401_64_dialog_content = "Você parece ser realmente popular por aqui.",
  ui_story_5086_50860401_65_dialog_content = "Mesmo que sua memória fraca tenha te impedido de lembrar o final da sua história, as crianças adoraram do mesmo jeito.",
  ui_story_5086_50860401_66_dialog_content = "Hã? Que história?",
  ui_story_5086_50860401_67_dialog_content = "Aquele que você contou para as crianças na área de descanso mais cedo.",
  ui_story_5086_50860401_68_dialog_content = "Oh, eu realmente contei a eles uma história?",
  ui_story_5086_50860401_69_dialog_content = "<size=50>Você quer dizer que já esqueceu?</size>",
  ui_story_5086_50860401_70_dialog_content = "Bem, não parece que eu anotei isso nas minhas notas—",
  ui_story_5086_50860401_71_dialog_content = "Se você tivesse que anotar cada pequeno detalhe assim, eu não acho que um único caderno seria suficiente para um dia.",
  ui_story_5086_50860401_72_dialog_content = "Mas você ainda se lembra da história, então pode me contar! Por favor, PlayerName, eu realmente quero ouvi-la!",
  ui_story_5086_50860401_73_dialog_content = "M-Muito perto! Vou te contar a história, mas me dê um pouco de espaço—",
  ui_story_5086_50860401_74_dialog_content = "Vamos ver, era sobre um garotinho...",
  ui_story_5086_50860402_1_dialog_content = "Que história emocionante. Você inventou isso de novo, Maya?",
  ui_story_5086_50860402_2_dialog_content = "Senhorita Stellandine! Você consegue ler mentes?",
  ui_story_5086_50860402_3_dialog_content = "Não, Maya, é apenas que suas histórias são muito especiais.",
  ui_story_5086_50860402_4_dialog_content = "Não importa o que aconteça nelas, ou se os personagens são bons ou maus—",
  ui_story_5086_50860402_5_dialog_content = "Suas histórias sempre terminam com todos se unindo e vivendo felizes para sempre.",
  ui_story_5086_50860402_6_dialog_content = "Bem, é assim que os contos de fadas devem ser, mesmo os que eu invento.",
  ui_story_5086_50860402_7_dialog_content = "...",
  ui_story_5086_50860402_8_dialog_content = "Suponho que você esteja certo. Além disso, mesmo que você leia uma história triste, vai esquecê-la no dia seguinte.",
  ui_story_5086_50860402_9_dialog_content = "Ainda assim, o esquecimento de Maya é muito mais sério do que qualquer coisa que eu já vi. Não deveríamos nos preocupar mais com isso?",
  ui_story_5086_50860402_10_dialog_content = "Talvez... Mas eu a levei para ver um médico, e os resultados de saúde dela estavam perfeitamente normais.",
  ui_story_5086_50860402_11_dialog_content = "O doutor também não conseguiu identificar a origem do esquecimento dela.",
  ui_story_5086_50860402_12_dialog_content = "Não deve ser fácil, viver assim...",
  ui_story_5086_50860402_13_dialog_content = "Sem brincadeira. Como você pretende acompanhar um mangá se nem consegue se lembrar do que aconteceu na última edição?",
  ui_story_5086_50860402_14_dialog_content = "E sobre todas as coisas legais que você viu na vida? Nenhuma experiência no mundo vale muito se você nem consegue se lembrar delas.",
  ui_story_5086_50860402_15_dialog_content = "Sadie! Você não deveria falar sobre a senhorita Maya assim, ou sobre qualquer outra pessoa, aliás. É rude.",
  ui_story_5086_50860402_16_dialog_content = "Ah, você está certo. Desculpe por isso, Maya.",
  ui_story_5086_50860402_17_dialog_content = "Ahh... Pobre Senhorita Maya.",
  ui_story_5086_50860402_18_dialog_content = "Ei, não devemos falar sobre as pessoas assim.",
  ui_story_5086_50860402_19_dialog_content = "Eu sei, mas... quando penso em quão difícil deve ser a vida dela, eu...",
  ui_story_5086_50860402_20_dialog_content = "Senhorita Maya, por que você não se torna uma empregada como eu?",
  ui_story_5086_50860402_21_dialog_content = "O trabalho pode ser um pouco difícil às vezes... mas você sempre estará cercado por boas pessoas...",
  ui_story_5086_50860402_22_dialog_content = "?",
  ui_story_5086_50860402_23_dialog_content = "Obrigado, todos! Embora eu realmente não saiba o que está acontecendo, todos vocês parecem realmente preocupados comigo.",
  ui_story_5086_50860402_24_dialog_content = "Mas você deve saber, estou realmente muito feliz aqui.",
  ui_story_5086_50860402_25_dialog_content = "Viu? Se algo importante acontece na minha vida, eu sempre anoto em minhas notas para não esquecer.",
  ui_story_5086_50860402_26_dialog_content = "Ontem, Maya se perdeu na rua. A velhinha de avental ajudou Maya a encontrar o caminho e ainda deu a ela uma laranja.",
  ui_story_5086_50860402_27_dialog_content = "Isso porque você salvou o neto dela de se afogar no oceano naquele dia. Ela estava agradecendo a você, Maya.",
  ui_story_5086_50860402_28_dialog_content = "No dia anterior, esqueci que nossa geladeira estava quebrada, então não pude fazer gelo para alguns de nossos animais. Mas, felizmente, um gentil vendedor de lanches me deu um grande balde disso.",
  ui_story_5086_50860402_29_dialog_content = "Também me lembro disso. Você estava ajudando-o a atrair mais clientes, já que o negócio dele estava indo tão mal naquele dia. Você também teve algumas ideias realmente exageradas.",
  ui_story_5086_50860402_30_dialog_content = "Na semana passada, quando perdi meu fluxograma para nosso evento interativo, as crianças se uniram para me ajudar a conduzir o show. Foi incrível!",
  ui_story_5086_50860402_31_dialog_content = "Ninguém estava disposto a participar no início, mas graças à habilidade de Maya de trabalhar tão bem com crianças, o evento se tornou um grande sucesso.",
  ui_story_5086_50860402_32_dialog_content = "E na semana anterior a essa, e no mês passado, e até mesmo no ano passado...",
  ui_story_5086_50860402_33_dialog_content = "<color=#e8d9bb>Cada página do caderno de Maya está cheia de memórias brilhantes e positivas.</color>",
  ui_story_5086_50860402_34_dialog_content = "<color=#e8d9bb>Ela descreve esses momentos coloridos de sua vida cotidiana com perfeita clareza.</color>",
  ui_story_5086_50860402_35_dialog_content = "<color=#e8d9bb>De repente, um cartão cai das páginas do caderno.</color>",
  ui_story_5086_50860402_36_dialog_content = "<color=#e8d9bb>Rabiscado nele estão algumas linhas de escrita. Embora a caligrafia pareça infantil, ela carrega uma certa gravidade.</color>",
  ui_story_5086_50860402_37_dialog_content = "O que você gravou naquele cartão, Maya?",
  ui_story_5086_50860402_38_dialog_content = "Ah, isso? Sou eu!",
  ui_story_5086_50860402_39_dialog_content = "Você?",
  ui_story_5086_50860402_40_dialog_content = "Isso mesmo! Sempre que algo super-duper-extra importante acontece na minha vida, eu escrevo neste cartão e leio todos os dias.",
  ui_story_5086_50860402_41_dialog_content = "Mesmo que eu não consiga me lembrar de nada escrito nela, essas memórias são uma grande parte de mim.",
  ui_story_5086_50860402_42_dialog_content = "<color=#e8d9bb>Maya pega delicadamente o cartão e fecha os olhos.</color>",
  ui_story_5086_50860402_43_dialog_content = "<color=#e8d9bb>Claramente, ela não precisa olhar o cartão para saber o que está escrito.</color>",
  ui_story_5086_50860402_44_dialog_content = "Elvis deseja-me uma vida longa e feliz.",
  ui_story_5086_50860402_45_dialog_content = "A senhorita Stellandine me deu um lar em seu aquário.",
  ui_story_5086_50860402_46_dialog_content = "Eu amo todos aqui em Harbour City.",
  ui_story_5086_50860402_47_dialog_content = "Ah, Senhorita Maya...",
  ui_story_5086_50860402_48_dialog_content = "Se você quiser visitar Umbraton, vou garantir que cuidarei bem de você. É o mínimo que um fanfarrão poderia fazer.",
  ui_story_5086_50860402_49_dialog_content = "Acho que você tem potencial para se tornar uma ídola também, Senhorita Maya. Quer tentar?",
  ui_story_5086_50860402_50_dialog_content = "Hã? Espere, acabei de dizer que realmente gosto da minha vida aqui. Não quero ir para nenhum outro lugar—",
  ui_story_5086_50860402_51_dialog_content = "Senhorita Stellandine, ela mencionou alguém chamado Elvis agora mesmo...",
  ui_story_5086_50860402_52_dialog_content = "O senhor da cidade, sim. Ele foi gentil o suficiente para cuidar de Maya no passado, já que ela não tinha pais para falar e sua memória ainda era pouco confiável. Isso era conhecido por todos na cidade.",
  ui_story_5086_50860402_53_dialog_content = "Ela também era conhecida por correr pela cidade e ajudar qualquer pessoa em necessidade.",
  ui_story_5086_50860402_54_dialog_content = "Por essa razão, alguns dos nossos moradores da cidade começaram a chamá-la de Princesa Mendiga de Harbour City.",
  ui_story_5086_50860402_55_dialog_content = "Quando Harbour City foi atacada durante a crise recente, Maya parece ter desaparecido também.",
  ui_story_5086_50860402_56_dialog_content = "Ninguém sabia se algo havia acontecido com ela, ou se o Senhor da Cidade tinha algo a ver com isso...",
  ui_story_5086_50860402_57_dialog_content = "Como ela não consegue se lembrar de nada sobre isso, discernir a verdade agora é praticamente impossível.",
  ui_story_5086_50860402_58_dialog_content = "Tudo que sei é que alguns dias após o incidente, ela apareceu de repente na entrada do aquário, pedindo um emprego.",
  ui_story_5086_50860402_59_dialog_content = "Vendo que ela não tinha mais um guardião, ofereci a ela para viver e trabalhar aqui como estagiária.",
  ui_story_5086_50860402_60_dialog_content = "Eu nunca fiz nada particularmente especial, mas ela escreve sobre mim como se eu fosse algum tipo de santo.",
  ui_story_5086_50860402_61_dialog_content = "Honestamente…",
  ui_story_5086_50860402_62_dialog_content = "(Elvis costumava cuidar dela... Será que Jeno escolheu Maya para ser sua mensageira?)",
  ui_story_5086_50860402_63_dialog_content = "Senhorita Stellandine, eu posso ter uma maneira de ajudar Maya a recuperar algumas de suas memórias.",
  ui_story_5086_50860402_64_dialog_content = "Sério?",
  ui_story_5086_50860402_65_dialog_content = "Sim, e acho que há uma boa chance de isso também funcionar.",
  ui_story_5086_50860402_66_dialog_content = "Então foi isso.",
  ui_story_5086_50860402_67_dialog_content = "Por mais que eu gostaria de aceitar sua oferta, como guardião temporário da Maya, acho que ela deveria ser a quem decidir.",
  ui_story_5086_50860500_1_dialog_content = "Você diz que pode me ajudar a recuperar minhas memórias?",
  ui_story_5086_50860500_2_dialog_content = "Eu não tinha ideia de que você poderia fazer algo tão incrível, PlayerName!",
  ui_story_5086_50860500_3_dialog_content = "Como um celestita, posso usar minhas habilidades psíquicas para me conectar com a mente das pessoas. Ainda não dominei completamente meus poderes, mas posso definitivamente usá-los para algo assim.",
  ui_story_5086_50860500_4_dialog_content = "Ao mergulhar em suas memórias, eu poderia ser capaz de encontrar algo que você não tem como ver por si mesmo.",
  ui_story_5086_50860500_5_dialog_content = "O poder de se conectar com a mente das pessoas... É isso?",
  ui_story_5086_50860500_6_dialog_content = "É, mais ou menos.",
  ui_story_5086_50860500_7_dialog_content = "Hum... Deixe-me olhar minhas anotações mais uma vez.",
  ui_story_5086_50860500_8_dialog_content = "?",
  ui_story_5086_50860500_9_dialog_content = "...",
  ui_story_5086_50860500_10_dialog_content = "Desculpe, mas não posso fazer isso.",
  ui_story_5086_50860500_11_dialog_content = "Hã? É porque tem algo que você não quer que eu veja?",
  ui_story_5086_50860500_12_dialog_content = "Não, não é isso.",
  ui_story_5086_50860500_13_dialog_content = "É só que eu não deveria perturbar o sonho do meu ancestral.",
  ui_story_5086_50860500_14_dialog_content = "Seu antepassado?",
  ui_story_5086_50860500_15_dialog_content = "Isso mesmo. Minhas memórias esquecidas provavelmente estão com meu ancestral agora, junto com meus pais.",
  ui_story_5086_50860500_16_dialog_content = "É por isso que eu não estou realmente apressando as coisas para tê-las de volta agora.",
  ui_story_5086_50860500_17_dialog_content = "Às vezes me sinto um pouco solitário, mas eu posso suportar.",
  ui_story_5086_50860500_18_dialog_content = "Porque um dia, quando meu sonho finalmente acabar, eu serei capaz de recuperar tudo que perdi.",
  ui_story_5086_50860500_19_dialog_content = "Uh, Maya... Do que você está falando?",
  ui_story_5086_50860500_20_dialog_content = "Você quer dizer que não sabe, PlayerName?",
  ui_story_5086_50860500_21_dialog_content = "Todo este mundo é apenas um sonho.",
  ui_story_5086_50860500_22_dialog_content = "Como assim? Estamos claramente no mundo real agora. Belisque suas bochechas, se não acredita em mim!",
  ui_story_5086_50860500_23_dialog_content = "E mesmo se estivéssemos em um sonho, de quem seria o sonho? Seu?",
  ui_story_5086_50860500_24_dialog_content = "Um sonho é apenas um sonho. O seu não é diferente do meu, ou de qualquer outra pessoa.",
  ui_story_5086_50860500_25_dialog_content = "Meus pais me viram em seus sonhos, que é a única razão pela qual estou aqui em primeiro lugar.",
  ui_story_5086_50860500_26_dialog_content = "Meu ancestral também está me observando dentro do sonho.",
  ui_story_5086_50860500_27_dialog_content = "Então você acha que somos todos apenas personagens dentro de algum sonho, Maya?",
  ui_story_5086_50860500_28_dialog_content = "Claro que não! Todos estão apenas vivendo em uma bolha, só isso. Quanto àquelas pessoas importantes que perdemos... elas estão vivendo no sonho mais doce de todos, cuidando de nós.",
  ui_story_5086_50860500_29_dialog_content = "Então, quem exatamente é o seu antepassado?",
  ui_story_5086_50860500_30_dialog_content = "O progenitor de toda a minha linhagem, um guardião submarino cujo olhar vê além do fluxo do tempo.",
  ui_story_5086_50860500_31_dialog_content = "Ou pelo menos foi isso que meu ancestral acabou de dizer.",
  ui_story_5086_50860500_32_dialog_content = "É por isso que eu não deveria perturbar o outro mundo por algo tão pequeno como recuperar minhas memórias.",
  ui_story_5086_50860500_33_dialog_content = "Definitivamente, eu não deveria perturbar meu ancestral sobre isso também.",
  ui_story_5086_50860500_34_dialog_content = "Ainda me sinto bastante perdido agora...",
  ui_story_5086_50860500_35_dialog_content = "Sinto muito...",
  ui_story_5086_50860500_36_dialog_content = "Mas o que eu entendo é que há algo mais importante para você do que recuperar suas memórias.",
  ui_story_5086_50860500_37_dialog_content = "!",
  ui_story_5086_50860500_38_dialog_content = "Mesmo que eu esteja realmente curioso para saber mais sobre isso... Não vou forçá-la a fazer algo que não esteja disposta a fazer, Maya.",
  ui_story_5086_50860500_39_dialog_content = "PlayerName...",
  ui_story_5086_50860500_40_dialog_content = "Eu realmente gosto de você!",
  ui_story_5086_50860500_41_dialog_content = "Huh? Não, espera... Uh... Eu ainda...",
  ui_story_5086_50860500_42_dialog_content = "Já passamos por isso antes, Maya. Você não pode dizer coisas assim para os meninos tão casualmente.",
  ui_story_5086_50860500_43_dialog_content = "Eu também gosto muito de você, Senhorita Stellandine!",
  ui_story_5086_50860500_44_dialog_content = "Oh, você doce criança... Não importa. Ainda tem trabalho a fazer esta tarde, então tente descansar por agora.",
  ui_story_5086_50860500_45_dialog_content = "Mas eu quero ouvir um conto de fadas.",
  ui_story_5086_50860500_46_dialog_content = "Como já esqueci a história desta manhã, ouvir uma nova é a minha maneira de descansar!",
  ui_story_5086_50860500_47_dialog_content = "Você realmente parece gostar de contos de fadas, Maya.",
  ui_story_5086_50860500_48_dialog_content = "Isso porque são registros de sonhos diferentes.",
  ui_story_5086_50860500_49_dialog_content = "E eu adoro ver todos os tipos de sonhos diferentes.",
  ui_story_5086_50860500_50_dialog_content = "Registros de sonhos, huh...",
  ui_story_5086_50860500_51_dialog_content = "Certo, então. Acontece que eu tenho uma história digna de ser contada agora mesmo.",
  ui_story_5086_50860500_52_dialog_content = "É sobre uma garotinha e um sonho sem esperança.",
  ui_story_5086_50860500_53_dialog_content = "Yay! Você é a melhor, Senhorita Stellandine!",
  ui_story_5086_50860500_54_dialog_content = "Era uma vez, uma garota que vivia sob o mar.",
  ui_story_5086_50860500_55_dialog_content = "O mar fornecia todo tipo de coisa para ela - comida deliciosa, tesouros abundantes e todos os brinquedos e diversões que ela poderia querer.",
  ui_story_5086_50860500_56_dialog_content = "Mas também faltavam muitas coisas no mundo dela, como fogo e barulho... e amor.",
  ui_story_5086_50860500_57_dialog_content = "Um dia, durante uma tempestade perigosa, a jovem garota resgatou um jovem príncipe que havia caído de seu navio. Naturalmente, ela se apaixonou perdidamente por ele.",
  ui_story_5086_50860500_58_dialog_content = "Uau! Um príncipe da terra e uma princesa do mar!",
  ui_story_5086_50860500_59_dialog_content = "Logo depois, a tripulação do príncipe o puxou de volta para o navio, e eles retornaram ao seu reino. Muito tempo se passou, mas o príncipe nunca voltou.",
  ui_story_5086_50860500_60_dialog_content = "O que? Mas por quê...",
  ui_story_5086_50860500_61_dialog_content = "Então a garota fez uma visita à bruxa do mar e ofereceu sua posse mais preciosa em troca do poder de caminhar na terra.",
  ui_story_5086_50860500_62_dialog_content = "Quando ela finalmente chegou à praia, ela lutou para usar suas novas pernas. Mas ela estava determinada a ver o príncipe novamente, então ela rastejou até que pudesse andar, e andou até que pudesse correr...",
  ui_story_5086_50860500_63_dialog_content = "Sim! Não desista, princesa! Você consegue!",
  ui_story_5086_50860500_64_dialog_content = "Mas foi quando a garota descobriu que algo terrível havia acontecido. Em troca de suas novas pernas, a bruxa havia tirado o que ela mais valorizava - suas memórias de seu amado príncipe.",
  ui_story_5086_50860500_65_dialog_content = "Ela estava em meio a um público de pessoas desconhecidas, o rosto e a voz de seu amante agora eram um completo mistério para ela.",
  ui_story_5086_50860500_66_dialog_content = "Na verdade, a garota começou a duvidar se ela realmente havia estado apaixonada desde o início.",
  ui_story_5086_50860500_67_dialog_content = "Ela não tinha como encontrar a pessoa que amava nunca mais.",
  ui_story_5086_50860500_68_dialog_content = "O que aconteceu depois?",
  ui_story_5086_50860500_69_dialog_content = "Nada, minha querida. É assim que a história termina.",
  ui_story_5086_50860500_70_dialog_content = "Huh? M-Mas a garota ainda não encontrou seu príncipe!",
  ui_story_5086_50860500_71_dialog_content = "Ela também não recuperou a memória! Ela nem mesmo consegue se lembrar de como ele se parece mais!",
  ui_story_5086_50860500_72_dialog_content = "É uma história tão triste e sem esperança...",
  ui_story_5086_50860500_73_dialog_content = "Você contou tão bem, Miss Stellandine... mas agora não consigo evitar de me sentir triste...",
  ui_story_5086_50860500_74_dialog_content = "Maya...",
  ui_story_5086_50860500_75_dialog_content = "Sinto o mesmo! Por que... Por que a vida tem que ser tão injusta com essa pobre garota?",
  ui_story_5086_50860500_76_dialog_content = "Sanae? E todos os outros... Há quanto tempo vocês estão aqui?",
  ui_story_5086_50860500_77_dialog_content = "Desde que a história começou, é claro! Vê? Sadie está puxando o chapéu para baixo porque ela não quer que ninguém veja suas lágrimas.",
  ui_story_5086_50860500_78_dialog_content = "Eu não estou chorando. É apenas assim que os espadachins mostram seu respeito e gratidão.",
  ui_story_5086_50860500_79_dialog_content = "Uh-huh, o que você disser!",
  ui_story_5086_50860500_80_dialog_content = "Ainda assim, estou surpreso que tantas pessoas nunca ouviram esse conto de fadas antes. Eu sempre pensei que era uma história bastante conhecida.",
  ui_story_5086_50860500_81_dialog_content = "Estou apenas interessado em histórias de espadachins.",
  ui_story_5086_50860500_82_dialog_content = "Se houvesse algum espadachim em seu mundo, tenho certeza de que eles a ajudariam a recuperar suas memórias em um instante.",
  ui_story_5086_50860500_83_dialog_content = "Você está certo, mas mesmo sem um herói assim, tenho certeza de que alguém estaria disposto a ajudá-la.",
  ui_story_5086_50860500_84_dialog_content = "Contos de fadas não deveriam ter finais tristes.",
  ui_story_5086_50860500_85_dialog_content = "Mas... É possível que o príncipe já tenha esquecido dela... Na verdade, ele pode já ter se casado com outra princesa...",
  ui_story_5086_50860500_86_dialog_content = "Enquanto isso, a pobre garota foi deixada sozinha na praia... É tão trágico... *soluçando*",
  ui_story_5086_50860500_87_dialog_content = "Hum, Sanae? É apenas uma história, sabe.",
  ui_story_5086_50860500_88_dialog_content = "Aaaaaaaah—",
  ui_story_5086_50860500_89_dialog_content = "Oh não, Sanae não para de chorar... Faça algo, Manae! Por favor!",
  ui_story_5086_50860500_90_dialog_content = "...",
  ui_story_5086_50860500_91_dialog_content = "Uaaaaau! Por que a garota teve que pagar um preço tão terrível? Essa bruxa não é nada além de uma grande malvada! E por que o príncipe nunca veio procurá-la? Uaaaaaaau!",
  ui_story_5086_50860500_92_dialog_content = "Por que você está piorando, Manae?",
  ui_story_5086_50860500_93_dialog_content = "<color=#e8d9bb>Fwooo—</color>",
  ui_story_5086_50860500_94_dialog_content = "<color=#e8d9bb>De repente, uma música suave começa a tocar.</color>",
  ui_story_5086_50860500_95_dialog_content = "<color=#e8d9bb>Tão leve e distante quanto a suave brisa do mar, a melodia sobe e desce como ondas surgindo do silencioso fundo do oceano.</color>",
  ui_story_5086_50860500_96_dialog_content = "<color=#e8d9bb>Cada nota soa claramente da concha nas mãos de Maya.</color>",
  ui_story_5086_50860500_97_dialog_content = "<color=#e8d9bb>Por um momento, a mente de cada pessoa se desvia ao som de sua música...</color>",
  ui_story_5086_50860500_98_dialog_content = "<color=#e8d9bb>Com seus corações aliviados pela melodia, eles começam a esquecer todos os seus problemas.</color>",
  ui_story_5086_50860500_99_dialog_content = "Que bela canção... O que foi isso agora, Senhorita Maya?",
  ui_story_5086_50860500_100_dialog_content = "Eu não sei muito sobre música, mas aquela canção me fez pensar no meu mangá de espadachim favorito agora mesmo.",
  ui_story_5086_50860500_101_dialog_content = "Sinto-me profundamente honrado por ter tido o privilégio de ouvir uma canção tão esplêndida.",
  ui_story_5086_50860500_102_dialog_content = "Você está aqui também, Minos? ... Hã?",
  ui_story_5086_50860500_103_dialog_content = "Quando Sanae adormeceu?",
  ui_story_5086_50860500_104_dialog_content = "A música da Maya tem o poder de acalmar os corações das pessoas. É especialmente útil em situações como esta.",
  ui_story_5086_50860500_105_dialog_content = "Tenho certeza de que esta criança está tendo um sonho maravilhoso enquanto falamos.",
  ui_story_5086_50860500_106_dialog_content = "Sim. Agora que ela esqueceu toda a sua tristeza, ela pode finalmente relaxar.",
  ui_story_5086_50860500_107_dialog_content = "A jovem Sanae tem se esforçado para completar a tarefa dada a ela por nossa senhora. Esta é uma oportunidade perfeita para ela descansar um pouco.",
  ui_story_5086_50860500_108_dialog_content = "Atrás do aquário estão os quartos para nossos funcionários. Há muitos quartos disponíveis.",
  ui_story_5086_50860500_109_dialog_content = "Se não se importar, ela é mais que bem-vinda para dormir lá.",
  ui_story_5086_50860500_110_dialog_content = "O resto de vocês também é livre para usar esses quartos também.",
  ui_story_5086_50860500_111_dialog_content = "Acredito que farei exatamente isso. Sua hospitalidade é muito apreciada, Srta. Stellandine.",
  ui_story_5086_50860500_112_dialog_content = "Sr. PlayerName, você poderia me ajudar a acompanhar Sanae para o quarto dela?",
  ui_story_5086_50860500_113_dialog_content = "Eu? Sim, claro.",
  ui_story_5086_50860500_114_dialog_content = "Você tem meus agradecimentos.",
  ui_story_5086_50860601_1_dialog_content = "Minos, havia algum motivo específico para você me pedir ajuda?",
  ui_story_5086_50860601_2_dialog_content = "Como é?",
  ui_story_5086_50860601_3_dialog_content = "Eu poderia entender se qualquer outra pessoa pedisse minha ajuda, mas estamos falando de você.",
  ui_story_5086_50860601_4_dialog_content = "Para Minos, o todo-poderoso mordomo da família Andersen, pedir a minha ajuda é tão improvável quanto os Jardins das Nuvens serem o exato centro de todo o universo.",
  ui_story_5086_50860601_5_dialog_content = "Acredito que você me considera com muita estima, meu amigo. No entanto, é exatamente como você suspeita.",
  ui_story_5086_50860601_6_dialog_content = "Você está ciente do conflito que recentemente ocorreu em Harbour City, sim?",
  ui_story_5086_50860601_7_dialog_content = "... Eu sou.",
  ui_story_5086_50860601_8_dialog_content = "Parece que você sabe muito mais sobre a situação do que gosta de admitir.",
  ui_story_5086_50860601_9_dialog_content = "I-É tão óbvio?",
  ui_story_5086_50860601_10_dialog_content = "Estou apenas fazendo outra pequena observação, nada mais.",
  ui_story_5086_50860601_11_dialog_content = "Mas eu divago. Nos últimos dez anos, o Senhor da Cidade Elvis sacrificou tanto sangue quanto suor em medidas igualmente grandes pelo bem de Harbour City.",
  ui_story_5086_50860601_12_dialog_content = "Foi graças aos esforços dele que esta cidade se tornou um lugar de tanta paz e prosperidade.",
  ui_story_5086_50860601_13_dialog_content = "Mas, após aquele incidente recente e seu desaparecimento, Harbour City ficou sob a administração de Lumopolis.",
  ui_story_5086_50860601_14_dialog_content = "É exatamente por essa razão que a senhorita Nina acredita que Harbour City está repleta de oportunidades de negócios.",
  ui_story_5086_50860601_15_dialog_content = "Mas também vale a pena notar que quando uma organização está no meio do tumulto, vermes tendem a se reproduzir até nos menores cantos.",
  ui_story_5086_50860601_16_dialog_content = "O que você quer dizer?",
  ui_story_5086_50860601_17_dialog_content = "Tenho certeza de que você já notou isso até agora, Sr. PlayerName. Todos os tipos de rumores estranhos e perturbadores têm circulado dentro e ao redor de Harbour City.",
  ui_story_5086_50860601_18_dialog_content = "Temo que a recente agitação da cidade seja a culpada por eles, e esses rumores desagradáveis apenas servem para desvalorizar Harbour City aos olhos do mundo.",
  ui_story_5086_50860601_19_dialog_content = "Agora que você mencionou, Sadie e Goldie só vieram aqui de Umbraton porque ouviram algo perturbador sobre Harbour City.",
  ui_story_5086_50860601_20_dialog_content = "Mas mesmo agora, eles ainda não encontraram nada para substanciar os rumores.",
  ui_story_5086_50860601_21_dialog_content = "É tudo tão estranho. Não me surpreende que Sadie tenha vindo para este tipo de coisa, mas por que Goldie também veio junto?",
  ui_story_5086_50860601_22_dialog_content = "Ela também sente perigo aqui?",
  ui_story_5086_50860601_23_dialog_content = "... Espere.",
  ui_story_5086_50860601_24_dialog_content = "Minhas suspeitas estavam corretas da última vez, não estavam? Isso é semelhante ao que aconteceu quando te conheci pela primeira vez, Minos...",
  ui_story_5086_50860601_25_dialog_content = "Está me dizendo que algo terrível assim está prestes a acontecer de novo?",
  ui_story_5086_50860601_26_dialog_content = "Claro que não. Eu sou apenas um humilde mordomo, não um profeta.",
  ui_story_5086_50860601_27_dialog_content = "Ufa, isso é um alívio.",
  ui_story_5086_50860601_28_dialog_content = "No entanto, fiz várias descobertas perturbadoras durante nossa investigação de negócios.",
  ui_story_5086_50860601_29_dialog_content = "Por exemplo, houve vários casos de viajantes desaparecendo em Harbour City.",
  ui_story_5086_50860601_30_dialog_content = "Além disso, cada um deles expressou um certo desejo pouco antes de desaparecer—",
  ui_story_5086_50860601_31_dialog_content = "Ou seja, eles queriam ir ao aquário.",
  ui_story_5086_50860601_32_dialog_content = "Este aquário realmente faz jus à sua reputação!",
  ui_story_5086_50860601_33_dialog_content = "Todos os peixes aqui são tão vivos. É como se eles tivessem acabado de tirá-los do mar hoje.",
  ui_story_5086_50860601_34_dialog_content = "Haha... Ha...",
  ui_story_5086_50860601_35_dialog_content = "Ei... Cadê todo mundo?",
  ui_story_5086_50860601_36_dialog_content = "Olá? Tem alguém aí? Eu poderia usar alguma ajuda aqui!",
  ui_story_5086_50860601_37_dialog_content = "Está um pouco escuro demais aqui. Não deveriam ter uma placa de saída iluminada para as pessoas verem?",
  ui_story_5086_50860601_38_dialog_content = "Ah, vejo luz ali! Tenho quase certeza de que isso leva ao lobby, então eu vou apenas—",
  ui_story_5086_50860601_39_dialog_content = "... Que cheiro é esse?",
  ui_story_5086_50860601_40_dialog_content = "Está... alguém aí?",
  ui_story_5086_50860601_41_dialog_content = "Hã? O-O que você está...",
  ui_story_5086_50860601_42_dialog_content = "Ahhhhhh!",
  ui_story_5086_50860602_1_dialog_content = "Gah!",
  ui_story_5086_50860602_2_dialog_content = "N-Não me assuste assim, Minos!",
  ui_story_5086_50860602_3_dialog_content = "Peço desculpas. Eu só pretendia compartilhar as informações que adquiri com você.",
  ui_story_5086_50860602_4_dialog_content = "A verdade pura e simples é muitas vezes a mais aterrorizante. Você já ouviu esse ditado antes?",
  ui_story_5086_50860602_5_dialog_content = "Em comparação com uma paz de espírito superficial, sinto-me muito mais confortado quando conheço toda a verdade por trás de cada detalhe.",
  ui_story_5086_50860602_6_dialog_content = "Você deve ter nervos de aço, Minos.",
  ui_story_5086_50860602_7_dialog_content = "Contanto que minha senhora precise, uma cidade inteira pode ser construída sobre meus nervos inabaláveis.",
  ui_story_5086_50860602_8_dialog_content = "... Eu não consigo mais dizer se você está brincando ou não.",
  ui_story_5086_50860602_9_dialog_content = "Isso pouco importa agora.",
  ui_story_5086_50860602_10_dialog_content = "O que realmente importa é, você conseguiu descansar durante este breve intervalo?",
  ui_story_5086_50860602_11_dialog_content = "... Eu tenho.",
  ui_story_5086_50860602_12_dialog_content = "Maravilhoso. Seria imperdoável da minha parte perturbar um querido amigo da Srta. Nina com minhas palavras.",
  ui_story_5086_50860602_13_dialog_content = "Se me der licença, preciso atender a jovem Sanae agora.",
  ui_story_5086_50860602_14_dialog_content = "Uhh?",
  ui_story_5086_50860602_15_dialog_content = "Eu me pergunto por que Minos sentiu a necessidade de compartilhar tudo isso comigo...",
  ui_story_5086_50860602_16_dialog_content = "Não parecia que ele estava tentando me assustar ou algo assim.",
  ui_story_5086_50860602_17_dialog_content = "Ainda assim, é possível que todos os desaparecimentos estejam de alguma forma conectados ao aquário...",
  ui_story_5086_50860602_18_dialog_content = "Com base nas minhas experiências, sempre que algo estranho assim acontece, o primeiro culpado que tenho que suspeitar é—",
  ui_story_5086_50860602_19_option_content = "Varredura Psíquica!",
  ui_story_5086_50860602_20_dialog_content = "!",
  ui_story_5086_50860602_21_dialog_content = "De jeito nenhum... Eu não esperava isso, mas senti a presença de um Eclipsite no aquário!",
  ui_story_5086_50860602_22_dialog_content = "Está muito fraco para identificar sua localização exata... Onde poderia estar?",
  ui_story_5086_50860602_23_dialog_content = "<color=#e8d9bb>Fwooo—</color>",
  ui_story_5086_50860602_24_dialog_content = "Desapareceu? Espere... Eu já ouvi essa música antes...",
  ui_story_5086_50860602_25_dialog_content = "...",
  ui_story_5086_50860602_26_dialog_content = "Maya?",
  ui_story_5086_50860602_27_dialog_content = "Shhh.",
  ui_story_5086_50860602_28_dialog_content = "Ele está dormindo.",
  ui_story_5086_50860602_29_dialog_content = "<color=#e8d9bb>Maya se afasta para revelar um garotinho dormindo no banco.</color>",
  ui_story_5086_50860602_30_dialog_content = "É aquele garoto de antes... Froude, certo? Por que ele ainda não foi para casa?",
  ui_story_5086_50860602_31_dialog_content = "As baleias daqui são os animais favoritos dele, então ele gosta de sair escondido depois de ir para casa para visitá-las.",
  ui_story_5086_50860602_32_dialog_content = "Costumo encontrá-lo no expositor de baleias por volta dessa hora. Sempre que o faço, apenas conto a ele outro conto de fadas, e ele volta direto para casa.",
  ui_story_5086_50860602_33_dialog_content = "Heheh, eu sei de tudo isso porque anotei em minhas anotações.",
  ui_story_5086_50860602_34_dialog_content = "Então, que história você contou para ele, Maya?",
  ui_story_5086_50860602_35_dialog_content = "Bem, como eu só conseguia me lembrar da metade, tive que preencher o resto tocando minha concha.",
  ui_story_5086_50860602_36_dialog_content = "Agora que você está aqui, PlayerName... Você pode nos contar uma história!",
  ui_story_5086_50860602_37_dialog_content = "Mas Froude já está dormindo.",
  ui_story_5086_50860602_38_dialog_content = "Você não sabia, PlayerName? Dizem que você ainda pode se lembrar das coisas mesmo quando as ouve durante o sono.",
  ui_story_5086_50860602_39_dialog_content = "Você só quer ouvir outra história, não é?",
  ui_story_5086_50860602_40_dialog_content = "Haha, culpado como acusado!",
  ui_story_5086_50860602_41_dialog_content = "... Acho que estou começando a entender como a Senhorita Stellandine se sente.",
  ui_story_5086_50860602_42_dialog_content = "(É quase impossível dizer não para Maya.)",
  ui_story_5086_50860602_43_dialog_content = "Você ainda se lembra da história que a Senhorita Stellandine nos contou mais cedo?",
  ui_story_5086_50860602_44_dialog_content = "O quê? A senhorita Stellandine nos contou uma história?",
  ui_story_5086_50860602_45_dialog_content = "Eu deveria ter sabido... Tudo bem, eu vou te contar de novo.",
  ui_story_5086_50860602_46_dialog_content = "Era uma vez, uma garota que vivia no mar. Ela resgatou um jovem príncipe quando ele caiu de seu navio...",
  ui_story_5086_50860602_47_dialog_content = "Aham!",
  ui_story_5086_50860602_48_dialog_content = "... E assim a garota fez um acordo com uma bruxa do mar, que lhe deu a habilidade de caminhar em terra.",
  ui_story_5086_50860602_49_dialog_content = "Mas quando a garota chegou à praia, ela percebeu que o preço que pagou por suas novas pernas eram suas memórias do príncipe que tanto amava.",
  ui_story_5086_50860602_50_dialog_content = "Como isso pode ser? Sem suas memórias, ela não se sentirá sozinha?",
  ui_story_5086_50860602_51_dialog_content = "...",
  ui_story_5086_50860602_52_dialog_content = "Não se preocupe! A história ainda não acabou!",
  ui_story_5086_50860602_53_dialog_content = "Agora, como foi o resto disso novamente?",
  ui_story_5086_50860602_54_dialog_content = "Ah, certo! Mesmo depois que o príncipe retornou ao seu reino, ele não conseguia parar de pensar na bela garota que havia salvado sua vida.",
  ui_story_5086_50860602_55_dialog_content = "Então ele voltou para o mar onde os dois se encontraram pela primeira vez, mas a garota não estava em lugar nenhum.",
  ui_story_5086_50860602_56_dialog_content = "Mesmo assim, o príncipe se recusou a desistir. Ele chamou as criaturas do mar e perguntou a cada uma delas se sabiam para onde ela foi.",
  ui_story_5086_50860602_57_dialog_content = "Primeiro, ele perguntou a uma baleia...",
  ui_story_5086_50860602_58_dialog_content = "<color=#e8d9bb>Respingo.</color>",
  ui_story_5086_50860602_59_dialog_content = "<color=#e8d9bb>A concha de Maya começa a fazer sons novamente.</color>",
  ui_story_5086_50860602_60_dialog_content = "<color=#e8d9bb>Como se fosse atraída, uma baleia aparece do outro lado do vidro e nada graciosamente para lá e para cá.</color>",
  ui_story_5086_50860602_61_dialog_content = "Então, ele perguntou a um linguado...",
  ui_story_5086_50860602_62_dialog_content = "<color=#e8d9bb>Em outro tanque, um cardume de linguados passa por eles rapidamente.</color>",
  ui_story_5086_50860602_63_dialog_content = "Depois disso, ele perguntou a um caranguejo...",
  ui_story_5086_50860602_64_dialog_content = "<color=#e8d9bb>De uma exposição de praia próxima, vários caranguejos colocam suas cabeças para fora da areia.</color>",
  ui_story_5086_50860602_65_dialog_content = "<color=#e8d9bb>Inúmeros espíritos da água se reúnem silenciosamente ao redor de Maya e dançam ao som da melodia de sua concha.</color>",
  ui_story_5086_50860602_66_dialog_content = "Com a ajuda deles, o príncipe viaja até a borda mais distante do mar.",
  ui_story_5086_50860602_67_dialog_content = "E lá, na praia, ele finalmente se reencontra com a garota que o salvou.",
  ui_story_5086_50860602_68_dialog_content = "Quem é você? ela pergunta com um olhar de perplexidade.",
  ui_story_5086_50860602_69_dialog_content = "Finalmente sou seu, ele responde. \"Eu te amo.\"",
  ui_story_5086_50860602_70_dialog_content = "E os dois viveram felizes para sempre.",
  ui_story_5086_50860602_71_dialog_content = "No momento em que suas mãos se tocaram, as memórias da garota voltaram a inundar seu coração.",
  ui_story_5086_50860602_72_dialog_content = "Quando se trata de contos de fadas, o amor é sempre mais forte do que até a magia mais poderosa. É a resposta para todo problema!",
  ui_story_5086_50860701_1_dialog_content = "Que história incrível! Poderia me contar outra? Por favor?!",
  ui_story_5086_50860701_2_dialog_content = "Certo, vamos ver...",
  ui_story_5086_50860701_3_dialog_content = "Atenção, visitantes e funcionários. Devido a uma emergência imprevista, o aquário fechará mais cedo hoje.",
  ui_story_5086_50860701_4_dialog_content = "Por favor, siga nossos membros da equipe até o saguão o mais rápido possível.",
  ui_story_5086_50860701_5_dialog_content = "Essa era a voz da Senhorita Stellandine. Eu me pergunto o que aconteceu...",
  ui_story_5086_50860701_6_dialog_content = "Um visitante relatou o desaparecimento de um amigo. O aquário está cooperando com a guarda da cidade para investigar o assunto.",
  ui_story_5086_50860701_7_dialog_content = "Vamos dar uma olhada.",
  ui_story_5086_50860701_8_dialog_content = "Espere—",
  ui_story_5086_50860701_9_dialog_content = "Esses Eclipsitas que se cuidem! Não vou tolerar nenhuma traição enquanto estou de olho!",
  ui_story_5086_50860701_10_dialog_content = "Sadie, relaxa! Eles podem ter apenas se separado; ainda não sabemos nada com certeza.",
  ui_story_5086_50860701_11_dialog_content = "Se Super Swashbuckler Sadie não conseguir manter a calma nesta situação, as pessoas normais entrarão em pânico ainda mais.",
  ui_story_5086_50860701_12_dialog_content = "Senhorita Stellandine! Estão todos bem?!",
  ui_story_5086_50860701_13_dialog_content = "Huff... Mesmo que ele seja apenas uma pequena criança, carregá-lo até aqui foi uma tortura para meus braços e pernas...",
  ui_story_5086_50860701_14_dialog_content = "Bom, Maya e PlayerName também estão aqui... Hum? De onde veio essa criança?",
  ui_story_5086_50860701_15_dialog_content = "Maya diz que ele entrou escondido para ver as baleias.",
  ui_story_5086_50860701_16_dialog_content = "Apenas coloque-o naquela cadeira por enquanto.",
  ui_story_5086_50860701_17_dialog_content = "Acredito que todos no aquário estão presentes e contabilizados agora.",
  ui_story_5086_50860701_18_dialog_content = "Consegue confirmar isso, Srta. Stellandine?",
  ui_story_5086_50860701_19_dialog_content = "Lembro-me dos rostos de todos os visitantes. Mas se você ainda tem dúvidas...",
  ui_story_5086_50860701_20_dialog_content = "Alguém mais está sentindo falta de um amigo ou companheiro?",
  ui_story_5086_50860701_21_dialog_content = "<color=#e8d9bb>Todos presentes olharam em volta, balançando suas cabeças.</color>",
  ui_story_5086_50860701_22_dialog_content = "Ninguém...",
  ui_story_5086_50860701_23_dialog_content = "(Minos deve saber de algo. Eu deveria ir perguntar a ele.)",
  ui_story_5086_50860701_24_dialog_content = "Oi, Minos... Hã? Para onde ele foi? Ele estava bem aqui um segundo atrás.",
  ui_story_5086_50860701_25_dialog_content = "Vi ele escoltando alguém por aquele corredor.",
  ui_story_5086_50860701_26_dialog_content = "Obrigado, Goldie.",
  ui_story_5086_50860701_27_dialog_content = "Heheh, você pode deixar este lugar comigo, agora vá fazer o seu trabalho!",
  ui_story_5086_50860701_28_dialog_content = "Não há como ele teria me deixado para trás sem dizer nada!",
  ui_story_5086_50860701_29_dialog_content = "O aquário não é tão grande assim. Um adulto não poderia ter se perdido aqui por tanto tempo!",
  ui_story_5086_50860701_30_dialog_content = "Não... Algo deve ter acontecido com ele!",
  ui_story_5086_50860701_31_dialog_content = "*chorando* É tudo culpa minha... Eu nunca deveria ter insistido em vir aqui!",
  ui_story_5086_50860701_32_dialog_content = "Por favor, mantenha a calma. Ainda não sabemos nada com certeza.",
  ui_story_5086_50860701_33_dialog_content = "Devemos nos concentrar em buscar pistas e encontrar seu amigo.",
  ui_story_5086_50860701_34_dialog_content = "Felizmente, um Celestita muito útil acabou de aparecer diante de nós.",
  ui_story_5086_50860701_35_dialog_content = "Desculpe?",
  ui_story_5086_50860701_36_dialog_content = "<color=#e8d9bb>Minos pede ao visitante angustiado para retornar ao grupo e me sinaliza para me juntar a ele mais adiante no corredor.</color>",
  ui_story_5086_50860701_37_dialog_content = "Está tão escuro aqui.",
  ui_story_5086_50860701_38_dialog_content = "De acordo com a Senhorita Stellandine, o sistema de iluminação tem apresentado defeitos recentemente.",
  ui_story_5086_50860701_39_dialog_content = "Ela afirma ter fechado o aquário para manutenção no passado, então os problemas elétricos de hoje foram completamente inesperados.",
  ui_story_5086_50860701_40_dialog_content = "Felizmente, apenas os principais dispositivos de iluminação deste salão perderam energia.",
  ui_story_5086_50860701_41_dialog_content = "As luzes ambiente são fracas, mas devem ser suficientes para navegar pelo corredor.",
  ui_story_5086_50860701_42_dialog_content = "De qualquer forma, acredito que o último local conhecido do visitante desaparecido estava exatamente neste lugar.",
  ui_story_5086_50860701_43_dialog_content = "O que te faz dizer isso?",
  ui_story_5086_50860701_44_dialog_content = "Por favor, dê uma olhada neste pilar.",
  ui_story_5086_50860701_45_dialog_content = "O que é isso? Tem algo manchado nele... Espere, isso é sangue?!",
  ui_story_5086_50860701_46_dialog_content = "Há mais na área?",
  ui_story_5086_50860701_47_dialog_content = "<color=#e8d9bb>Respingo.</color>",
  ui_story_5086_50860701_48_dialog_content = "Uau, essa foi por pouco... Quase escorreguei nesta poça. Cuidado por onde anda, Minos.",
  ui_story_5086_50860701_49_dialog_content = "Eu poderia dizer o mesmo para você, PlayerName. Até que este incidente seja resolvido, por favor, tenha o máximo de cautela no local-",
  ui_story_5086_50860701_50_dialog_content = "Devemos evitar danificar quaisquer pistas ou evidências.",
  ui_story_5086_50860701_51_dialog_content = "Se você tivesse dado mais um passo, teria estragado aquela pegada no chão.",
  ui_story_5086_50860701_52_dialog_content = "Ah, agora você me diz!",
  ui_story_5086_50860701_53_dialog_content = "Espere, há mais de uma pegada aqui... Estou feliz que você conseguiu identificá-las mesmo nesta iluminação.",
  ui_story_5086_50860701_54_dialog_content = "Mas eles estão todos misturados...",
  ui_story_5086_50860701_55_dialog_content = "Com base na altura fornecida pelo amigo da pessoa desaparecida, posso estimar o tamanho aproximado do sapato dela.",
  ui_story_5086_50860701_56_dialog_content = "E, julgando pela maneira como se sobrepõem um ao outro, também posso discernir aproximadamente a ordem em que foram feitos.",
  ui_story_5086_50860701_57_dialog_content = "Por fim, dado o modo como as pegadas passam por este pilar manchado de sangue, é altamente possível que pertençam à nossa pessoa desaparecida.",
  ui_story_5086_50860701_58_dialog_content = "Que rápido!",
  ui_story_5086_50860701_59_dialog_content = "Ainda assim, há algo estranho nessas pegadas.",
  ui_story_5086_50860701_60_dialog_content = "Eles parecem totalmente normais a caminho do meio do corredor, mas depois voltam atrás e se transformam em uma bagunça completa.",
  ui_story_5086_50860701_61_dialog_content = "Quase como se... a pessoa que os deixou tivesse encontrado algo assustador.",
  ui_story_5086_50860701_62_dialog_content = "Acredito que você tenha as qualidades de um detetive habilidoso, meu amigo.",
  ui_story_5086_50860701_63_dialog_content = "Eu também fiz uma observação semelhante.",
  ui_story_5086_50860701_64_dialog_content = "Uma pessoa normal naturalmente gritaria por ajuda quando confrontada com algo aterrorizante.",
  ui_story_5086_50860701_65_dialog_content = "Pela aparência dessas pegadas, eu presumiria que ele teve tempo suficiente para gritar.",
  ui_story_5086_50860701_66_dialog_content = "Infelizmente, minhas perguntas aos demais visitantes do aquário revelaram que nenhum deles estava sequer perto deste corredor mais cedo nesta tarde.",
  ui_story_5086_50860701_67_dialog_content = "Aqueles que passaram por aqui também não relataram nada fora do comum, o que significa que o momento do desaparecimento da pessoa desaparecida não pode ser determinado com base em nosso conhecimento atual.",
  ui_story_5086_50860701_68_dialog_content = "Na verdade, Maya e eu estávamos perto quando aconteceu...",
  ui_story_5086_50860701_69_dialog_content = "Mas Maya estava tocando sua concha o tempo todo, o que May explica por que não ouvimos nada.",
  ui_story_5086_50860701_70_dialog_content = "Entendo. Que pena.",
  ui_story_5086_50860701_71_dialog_content = "Parece que a atual trilha de pistas só pode nos levar até aqui.",
  ui_story_5086_50860701_72_dialog_content = "As pegadas param logo antes de chegar ao final do corredor... Então, para onde essa pessoa poderia ter ido?",
  ui_story_5086_50860701_73_dialog_content = "... Espera, acabei de lembrar de algo!",
  ui_story_5086_50860701_74_dialog_content = "Depois de terminarmos nossa conversa mais cedo, senti a presença de um Eclipsite em algum lugar dentro do aquário! Era fraco, mas não havia como negar!",
  ui_story_5086_50860701_75_dialog_content = "É possível que existam salas e passagens escondidas neste lugar, assim como na casa assombrada?",
  ui_story_5086_50860701_76_dialog_content = "Então eles poderiam se esconder no escuro e sair quando as luzes se apagam.",
  ui_story_5086_50860701_77_dialog_content = "O visitante desaparecido encontrou um Eclipsite e foi atacado enquanto tentava escapar...",
  ui_story_5086_50860702_1_dialog_content = "Até que pesquisemos cada canto deste aquário, não posso negar a possibilidade de existirem salas escondidas neste lugar.",
  ui_story_5086_50860702_2_dialog_content = "No entanto, precisamos enfrentar mais um problema urgente...",
  ui_story_5086_50860702_3_dialog_content = "Já terminamos? Quanto tempo mais devemos desperdiçar aqui?",
  ui_story_5086_50860702_4_dialog_content = "Deixe apenas a guarda da cidade lidar com isso. Lidar com casos de pessoas desaparecidas é o trabalho deles, não é?",
  ui_story_5086_50860702_5_dialog_content = "Entendo suas preocupações, pessoal. A guarda da cidade já foi notificada, mas seria melhor se todos permanecessem aqui até que eles cheguem.",
  ui_story_5086_50860702_6_dialog_content = "Sinceramente, há algo seriamente errado com este lugar, e eu não vou ficar por aqui para descobrir o que é! Vou garantir que meus amigos também evitem este lugar!",
  ui_story_5086_50860702_7_dialog_content = "Por favor, não diga isso! Nós estamos...",
  ui_story_5086_50860702_8_dialog_content = "Dadas as circunstâncias atuais, simplesmente não temos tempo para realizar uma inspeção tão minuciosa.",
  ui_story_5086_50860702_9_dialog_content = "Os convidados estão começando a ficar inquietos...",
  ui_story_5086_50860702_10_dialog_content = "Por favor, me perdoe.",
  ui_story_5086_50860702_11_dialog_content = "Wha—Ei!",
  ui_story_5086_50860702_12_dialog_content = "O que deu em você, Minos? Por que me empurrou assim...",
  ui_story_5086_50860702_13_dialog_content = "Algo está errado, PlayerName?",
  ui_story_5086_50860702_14_dialog_content = "(Oh não, todos estão voltando sua atenção para mim porque eu entrei tão de repente!)",
  ui_story_5086_50860702_15_dialog_content = "Ahaha... D-Desculpe interromper...",
  ui_story_5086_50860702_16_dialog_content = "Mas acho que sei uma maneira de descobrir a verdade!",
  ui_story_5086_50860702_17_dialog_content = "?!",
  ui_story_5086_50860702_18_dialog_content = "(O-O foi minha voz?!)",
  ui_story_5086_50860702_19_dialog_content = "Isso é incrível, PlayerName!",
  ui_story_5086_50860702_20_dialog_content = "Enquanto todos os outros estavam em pânico, você já estava trabalhando duro para resolver o mistério, hein?",
  ui_story_5086_50860702_21_dialog_content = "Sua habilidade de assumir o controle da situação é tão impressionante!",
  ui_story_5086_50860702_22_dialog_content = "Uau, PlayerName! Eu não fazia ideia de que você queria ser um detetive em vez de um espadachim como eu!",
  ui_story_5086_50860702_23_dialog_content = "N-Agora só espere um minuto! Não fui eu—",
  ui_story_5086_50860702_24_dialog_content = "Isso não era eu apenas falando bobagens!",
  ui_story_5086_50860702_25_dialog_content = "Ei! Não me interrompa—",
  ui_story_5086_50860702_26_dialog_content = "Porque estou prestes a apontar o verdadeiro culpado!",
  ui_story_5086_50860702_27_dialog_content = "... O que?!?",
  ui_story_5086_50860702_28_dialog_content = "Huh? Você realmente está tão surpreso com esse outro lado seu, PlayerName?",
  ui_story_5086_50860702_29_dialog_content = "Quem você pensa que é, fingindo ser um detetive agora? Leia a sala, seu punk!",
  ui_story_5086_50860702_30_dialog_content = "Ah, deixe-o sozinho. Ele é apenas uma criança.",
  ui_story_5086_50860702_31_dialog_content = "(Todos agora pensam que eu sou um maluco!)",
  ui_story_5086_50860702_32_dialog_content = "Mas eu realmente…",
  ui_story_5086_50860702_33_dialog_content = "Aham.",
  ui_story_5086_50860702_34_dialog_content = "(Minos?!)",
  ui_story_5086_50860702_35_option_content = "Varredura Psíquica!",
  ui_story_5086_50860702_36_dialog_content = "(O que está acontecendo aqui, Minos?)",
  ui_story_5086_50860702_37_dialog_content = "(Peço desculpas a você em um momento posterior, meu amigo. Mas como mordomo, não sou adequado para estar sob os holofotes.)",
  ui_story_5086_50860702_38_dialog_content = "(Por essa razão, devo pedir que você coopere comigo, muito da maneira que Manae faz com Sanae.)",
  ui_story_5086_50860702_39_dialog_content = "(Então você precisa que eu aja como seu fantoche?)",
  ui_story_5086_50860702_40_dialog_content = "(Se você quisesse, sim.)",
  ui_story_5086_50860702_41_dialog_content = "Por favor, ouçam, pessoal! Descobri algumas coisas naquele corredor ali...",
  ui_story_5086_50860702_42_dialog_content = "... Então, quando você junta tudo, especialmente as manchas de sangue na coluna, é provável que a pessoa desaparecida tenha sido atacada.",
  ui_story_5086_50860702_43_dialog_content = "Começando esta tarde, ninguém deixou o aquário ainda. Isso também significa—",
  ui_story_5086_50860702_44_dialog_content = "Que o culpado não saiu. Em outras palavras... O assassino está em algum lugar entre nós.",
  ui_story_5086_50860702_45_dialog_content = "Cai na real, criança! Você está realmente nos acusando de algo?!",
  ui_story_5086_50860702_46_dialog_content = "Sua busca por atenção saiu completamente do controle! Além disso, você realmente acha que pode construir um caso com provas tão frágeis?!",
  ui_story_5086_50860702_47_dialog_content = "Eu sabia! Eu sabia que tinha algo errado com este aquário!",
  ui_story_5086_50860702_48_dialog_content = "Quando os Eclipsitas atacaram a Harbour City, eles devem ter transformado alguns dos funcionários aqui em seu próprio tipo!",
  ui_story_5086_50860702_49_dialog_content = "O quê?! Eu não sou um Eclipsita de jeito nenhum! E não ouse apontar dedos para a Senhorita Stellandine ou o resto da nossa equipe!",
  ui_story_5086_50860702_50_dialog_content = "Isso mesmo! Você não pode simplesmente acusar Maya ou Stellandine assim, especialmente quando você não sabe nada sobre elas!",
  ui_story_5086_50860702_51_dialog_content = "PlayerName, embora eu esteja grato pela sua assistência nesta investigação, devo pedir que você se abstenha de acusar nossos convidados de irregularidades sem fundamento...",
  ui_story_5086_50860702_52_dialog_content = "(Ela está certa, Minos! Eu te disse que senti um Eclipsite antes, então isso não significa que o culpado não é um deles?)",
  ui_story_5086_50860702_53_dialog_content = "(Todos estão começando a suspeitar um do outro por causa do que você disse!)",
  ui_story_5086_50860702_54_dialog_content = "(Isso também faz parte do motivo pelo qual pedi sua cooperação.)",
  ui_story_5086_50860702_55_dialog_content = "(Você é um jovem inteligente, mas sua falta de ceticismo pode ser preocupante às vezes.)",
  ui_story_5086_50860702_56_dialog_content = "(Hã?)",
  ui_story_5086_50860702_57_dialog_content = "Claro que posso fazer essas acusações! Eu sou um celestita, afinal de contas!",
  ui_story_5086_50860702_58_dialog_content = "Também sou um amigo próximo da Senhora Carleen. Os cavaleiros de Lumopolis ficarão mais do que felizes em verificar tudo isso quando chegarem aqui.",
  ui_story_5086_50860702_59_dialog_content = "Como um Celestita e um aliado confiável da Senhora Carleen, é natural que eu queira prender este criminoso, não acha?",
  ui_story_5086_50860702_60_dialog_content = "Tudo o que preciso fazer é dar as mãos a todos os presentes, e minhas habilidades psíquicas me permitirão encontrar o verdadeiro culpado.",
  ui_story_5086_50860702_61_dialog_content = "E se você não encontrar o culpado entre nós?",
  ui_story_5086_50860702_62_dialog_content = "Então esse seria o melhor resultado possível, não concorda?",
  ui_story_5086_50860702_63_dialog_content = "Ahn???",
  ui_story_5086_50860702_64_dialog_content = "Claro que seria ótimo se pudéssemos descobrir o culpado aqui e agora.",
  ui_story_5086_50860702_65_dialog_content = "Mas se eu não o encontrar entre vocês, isso apenas significa que nenhum de vocês é um assassino, certo?",
  ui_story_5086_50860702_66_dialog_content = "Então, ou eu encontrarei o criminoso ou provarei a inocência de todos. É uma situação vantajosa, você não acha?",
  ui_story_5086_50860702_67_dialog_content = "Isso realmente faz muito sentido! Aqui, deixe-me ir primeiro!",
  ui_story_5086_50860702_68_dialog_content = "Suponho que você esteja certo... Tudo bem, vou cooperar.",
  ui_story_5086_50860702_69_dialog_content = "(Uau... Todos essas pessoas não cooperativas estão de repente se alinhando para ajudar.)",
  ui_story_5086_50860702_70_dialog_content = "(Eu sei que eu deveria ser o fantoche aqui, mas Minos está liderando toda a sala pelos seus narizes.)",
  ui_story_5086_50860702_71_dialog_content = "(Também, parece que nenhum deles considerou a possibilidade de que eu realmente não sei de nada, ou que eu não tenho como provar a inocência de ninguém...)",
  ui_story_5086_50860702_72_dialog_content = "(Uma resposta natural. Afinal, as pessoas se tornam míopes com bastante facilidade em situações estressantes como esta. Quando isso acontece, elas só veem as coisas em preto e branco.)",
  ui_story_5086_50860702_73_dialog_content = "(Mas por enquanto, por favor, não os alerte sobre essa possibilidade.)",
  ui_story_5086_50860702_74_dialog_content = "(Dadas as nossas circunstâncias atuais, acredito que unir todos sob um objetivo comum é de vital importância.)",
  ui_story_5086_50860702_75_dialog_content = "(Eu sei... Mas...)",
  ui_story_5086_50860702_76_dialog_content = "(Eles todos querem que eu aperte as mãos deles agora! Eu realmente tenho que usar meus poderes em cada um deles?)",
  ui_story_5086_50860702_77_dialog_content = "(De nada, meu amigo.)",
  ui_story_5086_50860702_78_dialog_content = "(Afinal, eu simplesmente desejo observar...)",
  ui_story_5086_50860702_79_dialog_content = "(Qual dessas pessoas se comportará de maneira anormal em um momento tão crítico.)",
  ui_story_5086_50860702_80_dialog_content = "<color=#e8d9bb>De repente, a fila de pessoas esperando para apertar as mãos para abruptamente.</color>",
  ui_story_5086_50860702_81_dialog_content = "Qual é o problema, Maya? É a sua vez, você sabe.",
  ui_story_5086_50860702_82_dialog_content = "(Eu...)",
  ui_story_5086_50860702_83_dialog_content = "(Isso mesmo; Maya acha que meus poderes de alguma forma perturbarão o Ancestral.)",
  ui_story_5086_50860702_84_dialog_content = "Não se preocupe, Maya, eu...",
  ui_story_5086_50860702_85_dialog_content = "<color=#e8d9bb>Clique!</color>",
  ui_story_5086_50860702_86_dialog_content = "O que está acontecendo?! Quem apagou as luzes?!",
  ui_story_5086_50860702_87_dialog_content = "Fiquem na fila e mantenham a calma, todos...",
  ui_story_5086_50860702_88_dialog_content = "Alguém trancou a entrada! Agora estamos todos presos aqui!",
  ui_story_5086_50860702_89_dialog_content = "Fora do meu caminho! Nenhuma porta pode resistir a-",
  ui_story_5086_50860702_90_dialog_content = "<color=#e8d9bb>Crash!</color>",
  ui_story_5086_50860702_91_dialog_content = "<color=#e8d9bb>Em meio à confusão, o som do vidro se estilhaçando perfura o ar.</color>",
  ui_story_5086_50860702_92_dialog_content = "<color=#e8d9bb>Antes que alguém possa reagir, o tanque ao redor do saguão do aquário explode.</color>",
  ui_story_5086_50860702_93_dialog_content = "<color=#e8d9bb>O saguão é rapidamente inundado com água fria e inúmeros peixes.</color>",
  ui_story_5086_50860801_1_dialog_content = "PlayerName—!",
  ui_story_5086_50860801_2_dialog_content = "Urgh... Tosse, tosse, tosse—",
  ui_story_5086_50860801_3_dialog_content = "Você está bem?",
  ui_story_5086_50860801_4_dialog_content = "Sim, eu apenas engoli um pouco de água, só isso... Obrigado por me salvar.",
  ui_story_5086_50860801_5_dialog_content = "Não me agradeça, agradeça a Goldie.",
  ui_story_5086_50860801_6_dialog_content = "Todos foram levados quando os tanques estouraram, mas ela conseguiu nos tirar da água.",
  ui_story_5086_50860801_7_dialog_content = "Foi apenas sorte, só isso.",
  ui_story_5086_50860801_8_dialog_content = "Eu estava o mais longe possível dos tanques quando eles explodiram, então tive um pouco mais de tempo para reagir.",
  ui_story_5086_50860801_9_dialog_content = "Mas eu não conseguia ver nada no escuro agora mesmo, então me agarrei às duas pessoas mais próximas de mim.",
  ui_story_5086_50860801_10_dialog_content = "Felizmente, enquanto a correnteza nos arrastava, também consegui arrombar a porta desta área de descanso e nos tirar da água.",
  ui_story_5086_50860801_11_dialog_content = "(Isso não parece nada com sorte boba, Goldie...)",
  ui_story_5086_50860801_12_dialog_content = "De qualquer forma... Como tudo isso aconteceu...?",
  ui_story_5086_50860801_13_dialog_content = "<color=#e8d9bb>A água continua a jorrar pelas rachaduras na porta, elevando gradualmente o nível da água na sala.</color>",
  ui_story_5086_50860801_14_dialog_content = "Eu sei que é um aquário, mas por que parece que há uma quantidade infinita de água aqui?",
  ui_story_5086_50860801_15_dialog_content = "Parece que este quarto também não vai durar muito mais tempo.",
  ui_story_5086_50860801_16_dialog_content = "Então, o que devemos fazer agora?",
  ui_story_5086_50860801_17_dialog_content = "Acho que precisamos encontrar uma maneira de nos reagrupar com todos primeiro.",
  ui_story_5086_50860801_18_dialog_content = "Socorro—!",
  ui_story_5086_50860801_19_dialog_content = "Alguém está com problemas!",
  ui_story_5086_50860801_20_dialog_content = "Não se preocupe, Super Sadie Swashbuckler 666 está a caminho!",
  ui_story_5086_50860801_21_dialog_content = "Espere—",
  ui_story_5086_50860801_22_dialog_content = "Nós vamos com você.",
  ui_story_5086_50860801_23_dialog_content = "Ali! Olhe!",
  ui_story_5086_50860801_24_dialog_content = "<color=#e8d9bb>A água no corredor já está à altura da cintura. Um grupo de visitantes pede ajuda em cima de um pedaço de madeira flutuante.</color>",
  ui_story_5086_50860801_25_dialog_content = "<color=#e8d9bb>Nadando em direção a eles está um tubarão massivo—</color>",
  ui_story_5086_50860801_26_dialog_content = "Se perder, seu grande fanfarrão!",
  ui_story_5086_50860801_27_dialog_content = "<color=#e8d9bb>Surpreendentemente, o ataque de Sadie faz o tubarão recuar alguns metros.</color>",
  ui_story_5086_50860801_28_dialog_content = "Não se preocupe, um espadachim sempre protege quem precisa!",
  ui_story_5086_50860801_29_dialog_content = "Aqui, PlayerName! Agarre-se a isso!",
  ui_story_5086_50860801_30_dialog_content = "Uma rede de pesca? Onde você conseguiu isso?",
  ui_story_5086_50860801_31_dialog_content = "Quase me emaranhei nele no caminho para cá. Achei que poderia ser útil mais tarde, então o trouxe comigo.",
  ui_story_5086_50860801_32_dialog_content = "Vamos usá-lo!",
  ui_story_5086_50860801_33_dialog_content = "Acha que podemos conseguir isso juntos, Sadie?",
  ui_story_5086_50860801_34_dialog_content = "Claro! Um swashbuckler nunca se rende!",
  ui_story_5086_50860801_35_dialog_content = "Então, na minha contagem—",
  ui_story_5086_50860801_36_dialog_content = "Três.",
  ui_story_5086_50860801_37_dialog_content = "<color=#e8d9bb>Sadie levanta seu taco de beisebol.</color>",
  ui_story_5086_50860801_38_dialog_content = "Dois.",
  ui_story_5086_50860801_39_dialog_content = "<color=#e8d9bb>Goldie e eu avançamos silenciosamente.</color>",
  ui_story_5086_50860801_40_dialog_content = "Um!",
  ui_story_5086_50860801_41_dialog_content = "<size=50>Você está fora daqui—!</size>",
  ui_story_5086_50860801_42_dialog_content = "<color=#e8d9bb>O tubarão cai perfeitamente dentro da rede à espera.</color>",
  ui_story_5086_50860801_43_dialog_content = "Muito bem, todos.",
  ui_story_5086_50860801_44_dialog_content = "Você mal suou agora, Goldie... Estou realmente tão fora de forma?",
  ui_story_5086_50860801_45_dialog_content = "Heehee!",
  ui_story_5086_50860801_46_dialog_content = "Vamos, Sadie! Vamos lá—!",
  ui_story_5086_50860801_47_dialog_content = "<color=#e8d9bb>De repente, uma enorme sombra aparece na água atrás de Sadie.</color>",
  ui_story_5086_50860801_48_dialog_content = "Saia de lá, Sadie!",
  ui_story_5086_50860801_49_dialog_content = "Rugido!!!",
  ui_story_5086_50860801_50_dialog_content = "!",
  ui_story_5086_50860801_51_dialog_content = "(E-Está tarde demais...)",
  ui_story_5086_50860801_52_dialog_content = "<size=50>Veredicto rápido.</size>",
  ui_story_5086_50860801_53_dialog_content = "<size=50>Manae Inigualável!</size>",
  ui_story_5086_50860801_54_dialog_content = "Nossas desculpas por demorar tanto, pessoal.",
  ui_story_5086_50860801_55_dialog_content = "Eu apenas me afastei para buscar Sanae, mas parece que um número de criaturas vis apareceram na nossa ausência.",
  ui_story_5086_50860801_56_dialog_content = "<color=#e8d9bb>Minos fica perfeitamente equilibrado no topo de uma fita no ar e faz uma reverência cortês.</color>",
  ui_story_5086_50860801_57_dialog_content = "<color=#e8d9bb>Sob seu braço esquerdo está um Sanae com aparência muito angustiada.</color>",
  ui_story_5086_50860801_58_dialog_content = "Um... P-Por favor, me perdoe! Eu não quis dormir durante tudo!",
  ui_story_5086_50860801_59_dialog_content = "B-Mas agora que estou aqui, farei tudo o que puder para consertar as coisas!",
  ui_story_5086_50860801_60_dialog_content = "Isso é muito melhor, Sanae. Agora comece, se você quiser.",
  ui_story_5086_50860801_61_dialog_content = "Uhh?",
  ui_story_5086_50860801_62_dialog_content = "Cuidado, todos! Mais Eclipsites estão a caminho!",
  ui_story_5086_50860802_1_dialog_content = "Graaah...",
  ui_story_5086_50860802_2_dialog_content = "Finalmente acabou... Quantos Eclipsitas estão se escondendo debaixo d'água?",
  ui_story_5086_50860802_3_dialog_content = "Pode não provar sua teoria de salas escondidas no aquário, mas ainda é uma peça de evidência convincente.",
  ui_story_5086_50860802_4_dialog_content = "É realmente a hora para isso, Minos?",
  ui_story_5086_50860802_5_dialog_content = "Absolutamente. Até que a verdade se torne clara, não devemos perder de vista a nossa investigação.",
  ui_story_5086_50860802_6_dialog_content = "Ei!",
  ui_story_5086_50860802_7_dialog_content = "Eu não sei do que vocês estão falando, mas aquele tubarão está vindo direto para nós!",
  ui_story_5086_50860802_8_dialog_content = "<color=#e8d9bb>O som da rede de pesca estalando enche o corredor enquanto o tubarão se liberta de suas restrições!</color>",
  ui_story_5086_50860802_9_dialog_content = "<color=#e8d9bb>Mais distante, mais e mais sombras perigosas aparecem sob a superfície da água.</color>",
  ui_story_5086_50860802_10_dialog_content = "Atrás de nós! E há muito mais deles!",
  ui_story_5086_50860802_11_dialog_content = "Vamos ser comidos vivos!!!",
  ui_story_5086_50860802_12_dialog_content = "... Todos ainda têm força suficiente para lutar?",
  ui_story_5086_50860802_13_dialog_content = "Estou bastante cansado, mas lutar até o amargo fim é a única maneira de sair.",
  ui_story_5086_50860802_14_dialog_content = "Enquanto houver um único fã presente, um ídolo nunca pode mostrar nem um sinal de exaustão!",
  ui_story_5086_50860802_15_dialog_content = "Empregadas e mordomos não são diferentes. No entanto...",
  ui_story_5086_50860802_16_dialog_content = "<color=#e8d9bb>O som familiar de uma concha ressoa.</color>",
  ui_story_5086_50860802_17_dialog_content = "<color=#e8d9bb>O tubarão enfurecido vira abruptamente e nada na direção da música.</color>",
  ui_story_5086_50860802_18_dialog_content = "Parece que podemos abaixar nossas armas agora.",
  ui_story_5086_50860802_19_dialog_content = "Vamos segui-lo.",
  ui_story_5086_50860802_20_dialog_content = "<color=#e8d9bb>Refletida por inúmeros pedaços de vidro estilhaçado, uma luz nebulosa e cintilante preenche a totalidade do aquário.</color>",
  ui_story_5086_50860802_21_dialog_content = "<color=#e8d9bb>A figura borrada de Maya pode ser vista de pé no outro extremo do corredor escurecido.</color>",
  ui_story_5086_50860802_22_dialog_content = "<color=#e8d9bb>Encantadas pela bela melodia da concha, inúmeras criaturas aquáticas de várias formas e tamanhos nadam em sua direção.</color>",
  ui_story_5086_50860802_23_dialog_content = "Maya—",
  ui_story_5086_50860802_24_dialog_content = "Fique onde está!",
  ui_story_5086_50860802_25_dialog_content = "Senhorita Stellandine? E Froude, e o resto dos visitantes... Graças a Deus vocês estão todos bem!",
  ui_story_5086_50860802_26_dialog_content = "Você chama isso de \"bem\"?! Não viu aquela garota ordenar todos aqueles peixes para nos atacar?!",
  ui_story_5086_50860802_27_dialog_content = "Seríamos isca de peixe agora se o dono do aquário não estivesse aqui para nos proteger!",
  ui_story_5086_50860802_28_dialog_content = "A pessoa desaparecida de antes provavelmente também era vítima dessa garota! Se vocês se acham tão durões, vão lidar com ela agora mesmo!",
  ui_story_5086_50860802_29_dialog_content = "Uhh?",
  ui_story_5086_50860802_30_dialog_content = "Claro que não...",
  ui_story_5086_50860802_31_dialog_content = "Ela está tentando escapar!",
  ui_story_5086_50860802_32_dialog_content = "...",
  ui_story_5086_50860802_33_dialog_content = "Espere, Maya!",
  ui_story_5086_50860802_34_dialog_content = "Argh, não consigo me mover rápido o suficiente na água! Não consigo acompanhar—",
  ui_story_5086_50860802_35_dialog_content = "Deixe isso comigo, Sr. PlayerName. Por favor, cuide dos outros por mim.",
  ui_story_5086_50860802_36_dialog_content = "<color=#e8d9bb>Minos salta habilmente através dos destroços flutuantes e vai atrás de Maya.</color>",
  ui_story_5086_50860802_37_dialog_content = "... Não podemos continuar ficando aqui. Precisamos encontrar um lugar seguro para todos se abrigarem.",
  ui_story_5086_50860802_38_dialog_content = "A água ainda não chegou ao segundo andar. Devemos tentar fazer o nosso caminho até lá.",
  ui_story_5086_50860802_39_dialog_content = "Eu não vou com vocês! Eu tenho que ir encontrar a Senhorita Maya!",
  ui_story_5086_50860802_40_dialog_content = "Peço desculpas, pequenino, mas realmente deveríamos discutir isso quando todos estiverem seguros.",
  ui_story_5086_50860802_41_dialog_content = "De jeito nenhum! Você é uma senhora má, então tire suas mãos de mim!",
  ui_story_5086_50860802_42_dialog_content = "Permita-me, Srta. Stellandine.",
  ui_story_5086_50860802_43_dialog_content = "Eu sei que você está chateado, pequeno, mas tem que permanecer positivo em momentos como este! Se você não sorrir quando as coisas ficam difíceis, não vai ficar feliz por muito tempo!",
  ui_story_5086_50860802_44_dialog_content = "M-Mas eles disseram todas aquelas coisas maldosas sobre a senhorita Maya!",
  ui_story_5086_50860802_45_dialog_content = "Eu sei, e essa não é maneira de falar sobre ninguém. Mas você não concorda com eles de jeito nenhum, concorda?",
  ui_story_5086_50860802_46_dialog_content = "H-Huh? Você... Acredita em mim?",
  ui_story_5086_50860802_47_dialog_content = "Hmm... Não tenho certeza, já que a conheci pela primeira vez hoje.",
  ui_story_5086_50860802_48_dialog_content = "Então, Froude, por favor me diga e a todos os outros por que Maya nunca faria nada de ruim.",
  ui_story_5086_50860802_49_dialog_content = "Ok! Ok!",
  ui_story_5086_50860802_50_dialog_content = "Parece que está tudo bem agora. Vamos, Senhorita Stellandine.",
  ui_story_5086_50860802_51_dialog_content = "Vou tentar manter minha distância.",
  ui_story_5086_50860802_52_dialog_content = "Parece que a criança não gosta de mim.",
  ui_story_5086_50860802_53_dialog_content = "Uh... Talvez ele esteja apenas ansioso porque está perto da Maya.",
  ui_story_5086_50860802_54_dialog_content = "Na verdade, é o mesmo para mim.",
  ui_story_5086_50860802_55_dialog_content = "Realmente não consigo acreditar que Maya seja uma pessoa ruim.",
  ui_story_5086_50860802_56_dialog_content = "Ela é apenas... Um pouco desajeitada.",
  ui_story_5086_50860802_57_dialog_content = "Mas ela é uma boa menina, sem dúvida.",
  ui_story_5086_50860802_58_dialog_content = "Deve haver algum mal-entendido, mas esperamos que Minos possa esclarecer as coisas!",
  ui_story_5086_50860802_59_dialog_content = "Hum... Senhorita Stellandine...",
  ui_story_5086_50860802_60_dialog_content = "Este é o único caminho para chegar ao segundo andar?",
  ui_story_5086_50860802_61_dialog_content = "Sim. Por que você perguntou?",
  ui_story_5086_50860802_62_dialog_content = "Mas... Goldie e os outros desapareceram.",
  ui_story_5086_50860802_63_dialog_content = "E nossos arredores... Parece que tudo foi distorcido de alguma forma.",
  ui_story_5086_50860802_64_dialog_content = "Isso é muito preocupante, sim...",
  ui_story_5086_50860802_65_dialog_content = "Você está bem? Você parece muito pálido.",
  ui_story_5086_50860802_66_dialog_content = "Para dizer a verdade... Eu não me sinto tão bem...",
  ui_story_5086_50860802_67_dialog_content = "Mas eu vou ficar bem. Por favor, continue sem mim...",
  ui_story_5086_50860802_68_dialog_content = "Como eu poderia fazer isso?! Vamos lá! Eu posso não ser o mais forte, mas com certeza posso te ajudar a andar.",
  ui_story_5086_50860802_69_dialog_content = "!",
  ui_story_5086_50860802_70_dialog_content = "... O que é isso?",
  ui_story_5086_50860802_71_dialog_content = "Acho que... estou sentindo um Eclipsita...",
  ui_story_5086_50860901_1_dialog_content = "La-la-la♪",
  ui_story_5086_50860901_2_dialog_content = "Um... Senhorita Goldie?",
  ui_story_5086_50860901_3_dialog_content = "Você descobriu alguma coisa?",
  ui_story_5086_50860901_4_dialog_content = "Eu tenho! O segundo andar não está inundado, e ninguém está brigando também.",
  ui_story_5086_50860901_5_dialog_content = "Só precisamos localizar a saída para sair daqui!",
  ui_story_5086_50860901_6_dialog_content = "Não, eu não estou falando sobre isso...",
  ui_story_5086_50860901_7_dialog_content = "Acho que ela está tentando dizer que todas as pessoas que estavam nos seguindo desapareceram.",
  ui_story_5086_50860901_8_dialog_content = "Uhh?",
  ui_story_5086_50860901_9_dialog_content = "Eles realmente se foram! Alô? PlayerName? Froude? Senhorita Stellandine?!",
  ui_story_5086_50860901_10_dialog_content = "A única resposta é um eco.",
  ui_story_5086_50860901_11_dialog_content = "Esse lugar... Algo nele parece diferente agora...",
  ui_story_5086_50860901_12_dialog_content = "A atmosfera... Está tão intensa agora.",
  ui_story_5086_50860901_13_dialog_content = "Eu sei, né? É como a mudança repentina no estilo de arte.",
  ui_story_5086_50860901_14_dialog_content = "Há imagens super-assustadoras no vidro, e parece que um monstro poderia saltar sobre nós a qualquer segundo.",
  ui_story_5086_50860901_15_dialog_content = "<size=50>Iiiihh!</size>",
  ui_story_5086_50860901_16_dialog_content = "Parem de se assustar assim! Não importa o quão aterrorizante possa parecer, ainda é apenas um aquário.",
  ui_story_5086_50860901_17_dialog_content = "Você não se lembra do que a senhorita Maya disse? Este é o lugar onde vivenciamos sonhos, e uma vez que você perceba isso, não há nada a temer.",
  ui_story_5086_50860901_18_dialog_content = "Este lugar agora é mais como um pesadelo.",
  ui_story_5086_50860901_19_dialog_content = "Então vamos cantar.",
  ui_story_5086_50860901_20_dialog_content = "Cantar de coração tem o poder de perfurar a escuridão e os pesadelos!",
  ui_story_5086_50860901_21_dialog_content = "Fiquei verdadeiramente feliz ao ler isso nos jornais após o último show!",
  ui_story_5086_50860901_22_dialog_content = "De qualquer forma, vamos começar a reunir nossos companheiros perdidos.",
  ui_story_5086_50860901_23_dialog_content = "P-Por favor, aguarde...",
  ui_story_5086_50860901_24_dialog_content = "Ali... Eclipsitas!",
  ui_story_5086_50860901_25_dialog_content = "Aguente só um pouco mais! Aquele Eclipsita está definitivamente por perto!",
  ui_story_5086_50860901_26_dialog_content = "Tá bem... Obrigado...",
  ui_story_5086_50860901_27_dialog_content = "Esse lugar é diferente de antes. Parece um labirinto agora... Ah!",
  ui_story_5086_50860901_28_dialog_content = "Olha! É o Sanae e os outros!",
  ui_story_5086_50860901_29_dialog_content = "Nós...",
  ui_story_5086_50860901_30_dialog_content = "<size=50>Manae Inigualável!</size>",
  ui_story_5086_50860901_31_dialog_content = "?!",
  ui_story_5086_50860901_32_dialog_content = "Ah...",
  ui_story_5086_50860901_33_dialog_content = "Senhorita Stellandine!",
  ui_story_5086_50860901_34_dialog_content = "Espere, Sanae! Somos nós!",
  ui_story_5086_50860901_35_dialog_content = "Huh? C-Como isso pode ser...",
  ui_story_5086_50860901_36_dialog_content = "Tá doendo...",
  ui_story_5086_50860901_37_dialog_content = "C-C-Como eu pude te atacar assim?! Eu sinto muito! Eu-Eu pensei que você...",
  ui_story_5086_50860901_38_dialog_content = "A-você está bem?",
  ui_story_5086_50860901_39_dialog_content = "... Por favor, não me toque.",
  ui_story_5086_50860901_40_dialog_content = "Buá... Eu sinto muito, de verdade! Eu confundi você com um Eclipsita agora mesmo...",
  ui_story_5086_50860901_41_dialog_content = "<color=#e8d9bb>Fwooo—</color>",
  ui_story_5086_50860901_42_dialog_content = "Esse é o som da concha da Maya! Ela está perto!",
  ui_story_5086_50860901_43_dialog_content = "eu... ah...",
  ui_story_5086_50860901_44_dialog_content = "P-Por favor, fique parado por um tempo. E-Eu...",
  ui_story_5086_50860901_45_dialog_content = "AH! Sadie e a senhorita Goldie se foram... Eles devem ter sido atraídos pelo som.",
  ui_story_5086_50860901_46_dialog_content = "Vou ficar aqui e proteger a Senhorita Stellandine. Por favor, vá ajudá-los, PlayerName!",
  ui_story_5086_50860901_47_dialog_content = "Nngh... Você também deve ir, e cuide da Maya.",
  ui_story_5086_50860901_48_dialog_content = "Então estou indo!",
  ui_story_5086_50860901_49_dialog_content = "(O som da concha parece completamente diferente.)",
  ui_story_5086_50860901_50_dialog_content = "<color=#e8d9bb>Fwooo—</color>",
  ui_story_5086_50860901_51_dialog_content = "(Urgh... Só de ouvir esse som, minha mente fica turva.)",
  ui_story_5086_50860901_52_dialog_content = "(Maya, o que você está...)",
  ui_story_5086_50860901_53_dialog_content = "!",
  ui_story_5086_50860901_54_dialog_content = "Você realmente não é diferente dos heróis de dramas clássicos, meu amigo.",
  ui_story_5086_50860901_55_dialog_content = "Quando você coloca dessa maneira, me faz pensar que você realmente precisa da minha ajuda novamente.",
  ui_story_5086_50860901_56_dialog_content = "É como você suspeita, sim.",
  ui_story_5086_50860901_57_dialog_content = "Me envergonha admitir, mas mal conseguia lutar enquanto resistia aos efeitos da ilusão da concha dela.",
  ui_story_5086_50860901_58_dialog_content = "<color=#e8d9bb>Fwooo—</color>",
  ui_story_5086_50860901_59_dialog_content = "Maya!",
  ui_story_5086_50860901_60_dialog_content = "...",
  ui_story_5086_50860901_61_dialog_content = "Não se preocupe, Minos! Eu vou proteger sua mente enquanto você luta!",
  ui_story_5086_50860901_62_dialog_content = "Confio na sua habilidade e julgamento, então apenas foque em se aproximar da Maya!",
  ui_story_5086_50860901_63_option_content = "Varredura Psíquica!",
  ui_story_5086_50860901_64_dialog_content = "<color=#e8d9bb>Graw!</color>",
  ui_story_5086_50860901_65_dialog_content = "Mal posso me dar ao luxo de decepcionar meu camarada agora que ele depositou tanta fé em mim. Perdoe-me, senhorita Maya, mas preciso pedir sua cooperação agora.",
  ui_story_5086_50860901_66_dialog_content = "!",
  ui_story_5086_50860901_67_dialog_content = "Fique atrás!",
  ui_story_5086_50860901_68_dialog_content = "Por favor, abaixe a concha e eu te asseguro que nenhum mal virá até você.",
  ui_story_5086_50860901_69_dialog_content = "Eu... Eu não entendo o que está acontecendo agora... Mas eu não posso!",
  ui_story_5086_50860901_70_dialog_content = "Argh...",
  ui_story_5086_50860901_71_dialog_content = "Os ataques psíquicos de repente ficaram mais fortes— Argh, minha cabeça!",
  ui_story_5086_50860901_72_dialog_content = "Parece que eu preciso lutar a sério agora.",
  ui_story_5086_50860901_73_dialog_content = "Perdoe-me, Senhorita Maya. Eu vou oferecer um pedido de desculpas adequado assim que isso acabar.",
  ui_story_5086_50860901_74_dialog_content = "<size=50>Veredicto Rápido!</size>",
  ui_story_5086_50860901_75_dialog_content = "Espera... Não!",
  ui_story_5086_50860901_76_dialog_content = "Não posso sangrar! Não era para eu!",
  ui_story_5086_50860901_77_dialog_content = "Por favor, me ajude—",
  ui_story_5086_50860901_78_dialog_content = "<color=#FFB400>Antepassado!</color>",
  ui_story_5086_50860901_79_dialog_content = "<color=#e8d9bb>Ah!</color>",
  ui_story_5086_50860901_80_dialog_content = "<color=#e8d9bb>De repente, ouvimos um canto longo e claro.</color>",
  ui_story_5086_50860901_81_dialog_content = "<color=#e8d9bb>Sem limites e substancial, mas fugaz e etéreo. Todas as contradições são simultaneamente validadas neste único momento.</color>",
  ui_story_5086_50860901_82_dialog_content = "<color=#e8d9bb>Incontáveis cores tremulam e convergem atrás de Maya.</color>",
  ui_story_5086_50860901_83_dialog_content = "Que magnífico...",
  ui_story_5086_50860901_84_dialog_content = "<color=#e8d9bb>Eu nunca tinha posto os olhos em uma criatura tão fantástica, mas assim que o fiz, de alguma forma eu a entendi.</color>",
  ui_story_5086_50860901_85_dialog_content = "<color=#e8d9bb>É algo nascido de fantasias, sonhos e a infinita projeção de pensamentos...</color>",
  ui_story_5086_50860901_86_dialog_content = "<color=#e8d9bb>Um antigo fantasma que poderia despedaçar a realidade com facilidade.</color>",
  ui_story_5086_50860901_87_dialog_content = "<color=#e8d9bb>Com um único sopro, este dragão efêmero...</color>",
  ui_story_5086_50860901_88_dialog_content = "<color=#e8d9bb>... poderia remodelar toda a existência.</color>",
  ui_story_5086_50860901_89_dialog_content = "Isso é uma ilusão? Ou realmente chegamos em outro lugar?",
  ui_story_5086_50860901_90_dialog_content = "Este mundo deve ser a criação da Senhorita Maya, um lugar onde <color=#FFB400>ilusões</color> e <color=#FFB400>realidade</color> são uma e a mesma coisa.",
  ui_story_5086_50860901_91_dialog_content = "Por favor, aja com cautela.",
  ui_story_5086_50860901_92_dialog_content = "Duvido que ela criou este espaço simplesmente para nós apreciarmos as vistas.",
  ui_story_5086_50860901_93_dialog_content = "Duvido que ela criou este espaço para nós apreciarmos as vistas.",
  ui_story_5086_50860902_1_dialog_content = "Bom trabalho, Minos.",
  ui_story_5086_50860902_2_dialog_content = "... Minos?",
  ui_story_5086_50860902_3_dialog_content = "Foi de novo...",
  ui_story_5086_50860902_4_dialog_content = "Miau!",
  ui_story_5086_50860902_5_dialog_content = "Huh? Um gato?",
  ui_story_5086_50860902_6_dialog_content = "Miau! Miau!",
  ui_story_5086_50860902_7_dialog_content = "Você está tentando me fazer seguir você?",
  ui_story_5086_50860902_8_dialog_content = "Miau!",
  ui_story_5086_50860902_9_dialog_content = "Tudo bem, de qualquer maneira, eu não sei para onde ir.",
  ui_story_5086_50860902_10_dialog_content = "<color=#e8d9bb>Resumo—</color>",
  ui_story_5086_50860902_11_dialog_content = "Argh!",
  ui_story_5086_50860902_12_dialog_content = "Ack... Glub, glub, glub...",
  ui_story_5086_50860902_13_dialog_content = "Ele... Glub, glub, glub... Socorro...",
  ui_story_5086_50860902_14_dialog_content = "É você...",
  ui_story_5086_50860902_15_dialog_content = "<color=#e8d9bb>Respingo.</color>",
  ui_story_5086_50860902_16_dialog_content = "Pffft! Tosse, tosse, tosse...",
  ui_story_5086_50860902_17_dialog_content = "Eu... estou salvo! Obrigada...",
  ui_story_5086_50860902_18_dialog_content = "O chão simplesmente desapareceu sob mim, e eu mergulhei no mar. Eu pensei que era um caso perdido.",
  ui_story_5086_50860902_19_dialog_content = "O-O que você está fazendo aqui, Senhorita Stellandine?",
  ui_story_5086_50860902_20_dialog_content = "Ouvi o som de uma concha logo depois que você saiu, e a próxima coisa que eu sabia, eu estava aqui.",
  ui_story_5086_50860902_21_dialog_content = "Com nada além do oceano ao meu redor, tudo que eu podia fazer era esperar nesta praia. Foi quando eu vi você cair na água.",
  ui_story_5086_50860902_22_dialog_content = "Fui levado a um lugar estranho por um gato, depois resgatado após cair no oceano.",
  ui_story_5086_50860902_23_dialog_content = "É quase como um conto de fadas.",
  ui_story_5086_50860902_24_dialog_content = "Talvez... isso seja um conto de fadas.",
  ui_story_5086_50860902_25_dialog_content = "Parece que o poder da linhagem de Maya vai muito além de acalmar os corações dos outros. Ele também pode criar ilusões poderosas.",
  ui_story_5086_50860902_26_dialog_content = "Este pode muito bem ser o cenário de outro conto de fadas.",
  ui_story_5086_50860902_27_dialog_content = "Ainda assim, eu nunca imaginei que ela usaria seus poderes contra os outros dessa maneira...",
  ui_story_5086_50860902_28_dialog_content = "Pode haver mais do que isso do que aparenta.",
  ui_story_5086_50860902_29_dialog_content = "Quando vi a Maya mais cedo, ela parecia estar preocupada com algo.",
  ui_story_5086_50860902_30_dialog_content = "Ah! Ah-ah-aaaaaah!",
  ui_story_5086_50860902_31_dialog_content = "Acho que ouvi alguém cantando.",
  ui_story_5086_50860902_32_dialog_content = "Olhe para lá, Senhorita Stellandine! Próximo à água!",
  ui_story_5086_50860902_33_dialog_content = "Isso é... A filha do oceano...",
  ui_story_5086_50860902_34_dialog_content = "Você quer dizer a sereia daquela história? Ela é linda...",
  ui_story_5086_50860902_35_dialog_content = "Ei, tem um navio chegando! Será que esta é a parte em que o príncipe e a sereia se encontram pela primeira vez?",
  ui_story_5086_50860902_36_dialog_content = "Será que aquele navio pode nos tirar daqui? Ei—",
  ui_story_5086_50860902_37_dialog_content = "... Isso não está funcionando. É como se as pessoas no navio não pudessem nos ver de jeito nenhum.",
  ui_story_5086_50860902_38_dialog_content = "...",
  ui_story_5086_50860902_39_dialog_content = "Acho que simplesmente não podemos vencer a princesa sereia em um concurso de charme.",
  ui_story_5086_50860902_40_dialog_content = "<color=#e8d9bb>Cabuum!</color>",
  ui_story_5086_50860902_41_dialog_content = "Trovão? E o céu também escureceu... É a tempestade da história, hein?",
  ui_story_5086_50860902_42_dialog_content = "Mas o navio está bem, e eles até navegaram até ela e jogaram uma escada de corda para ela...",
  ui_story_5086_50860902_43_dialog_content = "<color=#e8d9bb>Amidst o estrondo dos trovões, testemunho algo inconcebível.</color>",
  ui_story_5086_50860902_44_dialog_content = "<color=#e8d9bb>A sereia estende sua mão branca como a neve e puxa seus salvadores para a água.</color>",
  ui_story_5086_50860902_45_dialog_content = "<color=#e8d9bb>Enquanto gritos preenchem o ar, um fedor fétido surge da água, que está lentamente se tornando um tom profundo de carmesim.</color>",
  ui_story_5086_50860902_46_dialog_content = "<color=#e8d9bb>Quando o sangue finalmente chega à costa, a cena horrível desaparece de repente.</color>",
  ui_story_5086_50860902_47_dialog_content = "<color=#e8d9bb>Depois, nos encontramos de volta no aquário.</color>",
  ui_story_5086_50860902_48_dialog_content = "<color=#e8d9bb>Mas o fedor desagradável parece persistir no ar ao nosso redor.</color>",
  ui_story_5086_50860902_49_dialog_content = "O que foi isso... Agora mesmo...",
  ui_story_5086_50860902_50_dialog_content = "Isso... Isso não foi... Não é assim que a história vai!",
  ui_story_5086_50860902_51_dialog_content = "... Moya é uma criança de coração puro.",
  ui_story_5086_50860902_52_dialog_content = "Tão pura que ela vê, aceita e ama tudo no mundo exatamente da mesma maneira.",
  ui_story_5086_50860902_53_dialog_content = "É possível que o que acabamos de ver não seja bom ou mau aos olhos dela.",
  ui_story_5086_50860902_54_dialog_content = "Então, até mesmo os Eclipsitas podem de alguma forma se tornar companheiros dela.",
  ui_story_5086_50861001_1_dialog_content = "... Não podemos parar agora.",
  ui_story_5086_50861001_2_dialog_content = "Senhorita Stellandine, consegue ficar de pé?",
  ui_story_5086_50861001_3_dialog_content = "Argh...",
  ui_story_5086_50861001_4_dialog_content = "Não posso.",
  ui_story_5086_50861001_5_dialog_content = "Então eu vou te carregar.",
  ui_story_5086_50861001_6_dialog_content = "O quê? Mas você mesmo não está indo muito bem, não é?",
  ui_story_5086_50861001_7_dialog_content = "Sim... um pouco...",
  ui_story_5086_50861001_8_dialog_content = "Mas não faço ideia de quantos Eclipsitas ainda estão à espreita ao nosso redor, e estou sentindo uma presença estranha em algum lugar próximo.",
  ui_story_5086_50861001_9_dialog_content = "Eu também não posso te deixar aqui.",
  ui_story_5086_50861001_10_dialog_content = "Apenas se segure em mim e me avise se doer demais para continuar.",
  ui_story_5086_50861001_11_dialog_content = "Você é uma alma tão gentil, PlayerName.",
  ui_story_5086_50861001_12_dialog_content = "Peço desculpas por envolver você nessa confusão.",
  ui_story_5086_50861001_13_dialog_content = "Está tudo bem, estou acostumado com esse tipo de coisa. Além disso, tenho certeza de que você quer preservar o aquário mais do que qualquer outra pessoa, certo?",
  ui_story_5086_50861001_14_dialog_content = "Sim. Eu prefiro que não...",
  ui_story_5086_50861001_15_dialog_content = "*Rugido*",
  ui_story_5086_50861001_16_dialog_content = "!",
  ui_story_5086_50861001_17_dialog_content = "Eclipsitas! Teremos que ir por outro caminho.",
  ui_story_5086_50861001_18_dialog_content = "Você sabe onde estamos agora, senhorita Stellandine?",
  ui_story_5086_50861001_19_dialog_content = "Peço desculpas, mas parece que o aquário foi completamente deformado.",
  ui_story_5086_50861001_20_dialog_content = "A ordem dos quartos foi misturada, então nem consigo discernir a direção para a qual estamos indo.",
  ui_story_5086_50861001_21_dialog_content = "Acho que vamos ter que arriscar.",
  ui_story_5086_50861001_22_dialog_content = "Olhe para lá... Quem é aquela?",
  ui_story_5086_50861001_23_dialog_content = "Oi, eu sou—",
  ui_story_5086_50861001_24_dialog_content = "H-Me ajude!",
  ui_story_5086_50861001_25_dialog_content = "Huh? Espere, por que você está fugindo?",
  ui_story_5086_50861001_26_dialog_content = "Não me mate—",
  ui_story_5086_50861001_27_dialog_content = "O que está acontecendo? Ele está sendo perseguido? Urgh...",
  ui_story_5086_50861001_28_dialog_content = "Senhorita Stellandine, você está sentindo algum cheiro estranho?",
  ui_story_5086_50861001_29_dialog_content = "Algo estranho, você diz...?",
  ui_story_5086_50861001_30_dialog_content = "Eu pensei que era apenas um efeito residual daquela ilusão de sereia mais cedo, mas ainda consigo sentir o cheiro agora.",
  ui_story_5086_50861001_31_dialog_content = "É um cheiro podre, e parece estar se aproximando...",
  ui_story_5086_50861001_32_dialog_content = "Huff... Huff...",
  ui_story_5086_50861001_33_dialog_content = "Huh? Quem está aí?",
  ui_story_5086_50861001_34_dialog_content = "... Sanae? V-Você está coberto de sangue! Você se machucou?!",
  ui_story_5086_50861001_35_dialog_content = "Por favor, me diga que você está bem!!",
  ui_story_5086_50861001_36_dialog_content = "Iiiihh!",
  ui_story_5086_50861001_37_dialog_content = "O que há de errado, Sanae?! Somos apenas nós!",
  ui_story_5086_50861001_38_dialog_content = "*Rugido*",
  ui_story_5086_50861001_39_dialog_content = "Nossa!",
  ui_story_5086_50861001_40_dialog_content = "Essa coisa esteve nos seguindo esse tempo todo?!",
  ui_story_5086_50861001_41_dialog_content = "Desculpe, Senhorita Stellandine, mas tenho que te colocar no chão. Por favor, me passe aquele bastão no canto e fique com Sanae.",
  ui_story_5086_50861001_42_dialog_content = "Esqueça de mim... Apenas fuja.",
  ui_story_5086_50861001_43_dialog_content = "De jeito nenhum! Eu vou ficar aqui para lutar!",
  ui_story_5086_50861001_44_dialog_content = "Só porque eu geralmente fico atrás de todos não significa que eu não saiba como proteger meus amigos!",
  ui_story_5086_50861001_45_dialog_content = "*Rugido*",
  ui_story_5086_50861001_46_dialog_content = "Hah—",
  ui_story_5086_50861001_47_dialog_content = "<color=#e8d9bb>Que droga!</color>",
  ui_story_5086_50861001_48_dialog_content = "Graaah—",
  ui_story_5086_50861001_49_dialog_content = "Hã? De jeito nenhum... Eu acabei de derrotar um Eclipsite com um único golpe? Eu?!",
  ui_story_5086_50861001_50_dialog_content = "De nada.",
  ui_story_5086_50861001_51_dialog_content = "Sadie! Então você é quem tirou isso.",
  ui_story_5086_50861001_52_dialog_content = "Não perca o foco. Há muito mais de onde aquele veio.",
  ui_story_5086_50861001_53_dialog_content = "<size=50>Você está fora daqui!</size>",
  ui_story_5086_50861001_54_dialog_content = "Eu também ajudo! Hyaa—",
  ui_story_5086_50861001_55_dialog_content = "Só porque eu geralmente fico atrás de todos não significa que eu não saiba como proteger meus amigos! Essa foi uma fala tão legal!",
  ui_story_5086_50861001_56_dialog_content = "Goldie! Sadie! Vocês dois apareceram bem na hora certa!",
  ui_story_5086_50861001_57_dialog_content = "Ídolos e swashbucklers nunca devem se atrasar, você sabe!",
  ui_story_5086_50861001_58_dialog_content = "Agora é a nossa hora de brilhar!",
  ui_story_5086_50861002_1_dialog_content = "Graaah—",
  ui_story_5086_50861002_2_dialog_content = "Obrigado por ouvir!",
  ui_story_5086_50861002_3_dialog_content = "Estamos seguros agora. Graças a Deus você chegou a tempo.",
  ui_story_5086_50861002_4_dialog_content = "Eu não poderia ter feito isso sem esses visitantes.",
  ui_story_5086_50861002_5_dialog_content = "Disseram-nos que havia Eclipsitas assustadores à espreita nesta direção, então viemos dar uma olhada.",
  ui_story_5086_50861002_6_dialog_content = "Deve ter sido aquele cara que fugiu agora mesmo. Ele decolou assim que nos viu...",
  ui_story_5086_50861002_7_dialog_content = "Você esteve sozinho todo esse tempo, PlayerName?",
  ui_story_5086_50861002_8_dialog_content = "Estive com Sanae e a Senhorita Stellandine. Eu os fiz se esconder ali... Hã?",
  ui_story_5086_50861002_9_dialog_content = "Onde eles estão? Tudo que eu vejo é...",
  ui_story_5086_50861002_10_dialog_content = "Uma poça de sangue?",
  ui_story_5086_50861002_11_dialog_content = "<color=#828282>Clic.</color>",
  ui_story_5086_50861002_12_dialog_content = "Hum... Senhorita Stellandine?",
  ui_story_5086_50861002_13_dialog_content = "Não se preocupe, eu vou trancar a porta.",
  ui_story_5086_50861002_14_dialog_content = "Somos os únicos aqui agora.",
  ui_story_5086_50861002_15_dialog_content = "Então, estamos seguros.",
  ui_story_5086_50861002_16_dialog_content = "Tem certeza, Srta. Stellandine?",
  ui_story_5086_50861002_17_dialog_content = "Claro.",
  ui_story_5086_50861002_18_dialog_content = "Então por que...",
  ui_story_5086_50861002_19_dialog_content = "... você parece...",
  ui_story_5086_50861002_20_dialog_content = "... um Eclipsite?",
  ui_story_5086_50861002_21_dialog_content = "...",
  ui_story_5086_50861002_22_dialog_content = "Poderia ser que Sanae e Dona Stellandine...",
  ui_story_5086_50861002_23_dialog_content = "Não podemos tirar conclusões precipitadas até encontrá-los!",
  ui_story_5086_50861002_24_dialog_content = "Verifique cada canto do quarto. As pessoas não desaparecem sem deixar rastros, então deve haver algumas pistas.",
  ui_story_5086_50861002_25_dialog_content = "Goldie está certo! Eu vou procurar no corredor ali.",
  ui_story_5086_50861002_26_dialog_content = "PlayerName! Espere!",
  ui_story_5086_50861002_27_dialog_content = "Espere, suas costas... Tem algo grudento nelas. O que são esses... Pedaços?",
  ui_story_5086_50861002_28_dialog_content = "Parece um pouco nojento... Esses cacos quase parecem carne...",
  ui_story_5086_50861002_29_dialog_content = "Então, quando o som atraiu todos para longe, apenas você e eu ficamos para trás...",
  ui_story_5086_50861002_30_dialog_content = "Foi você quem me atacou por trás?",
  ui_story_5086_50861002_31_dialog_content = "Exatamente.",
  ui_story_5086_50861002_32_dialog_content = "... Você estava controlando todos aqueles Eclipsitas também, Senhorita Stellandine?",
  ui_story_5086_50861002_33_dialog_content = "Então você descobriu, hein?",
  ui_story_5086_50861002_34_dialog_content = "Claro. Porque eu sou bastante habilidoso na manipulação.",
  ui_story_5086_50861002_35_dialog_content = "Aqueles Eclipsitas ocasionalmente agem como... marionetes.",
  ui_story_5086_50861002_36_dialog_content = "Isso é bastante surpreendente. Mas... agora é tarde demais.",
  ui_story_5086_50861002_37_dialog_content = "Estou... realmente faminto.",
  ui_story_5086_50861002_38_dialog_content = "Desculpe, faz tanto tempo desde que tive uma refeição normal.",
  ui_story_5086_50861002_39_dialog_content = "Eu também não quero isso...",
  ui_story_5086_50861002_40_dialog_content = "Mas eu simplesmente não aguento mais...",
  ui_story_5086_50861002_41_dialog_content = "Eu tenho um favor a pedir. Por favor... seja minha comida!",
  ui_story_5086_50861002_42_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5086_50861002_43_dialog_content = "Por que você deve resistir? Por que nada vai do meu jeito?!",
  ui_story_5086_50861002_44_dialog_content = "Perdoe-me, mas sou uma donzela da família Andersen.",
  ui_story_5086_50861002_45_dialog_content = "Eu não completei a tarefa que o Sr. Minos me confiou. Sem mencionar que a Srta. Nina está aguardando meu retorno.",
  ui_story_5086_50861002_46_dialog_content = "E-Eu ainda tenho amigos que quero ver novamente, então por favor...",
  ui_story_5086_50861002_47_dialog_content = "Eu não posso permitir que você me coma.",
  ui_story_5086_50861002_48_dialog_content = "Se você está com tanta fome assim, tente se comer, maldito monstro!",
  ui_story_5086_50861002_49_dialog_content = "<color=#e8d9bb>Estrondo-</color>",
  ui_story_5086_50861002_50_dialog_content = "O que é essa força louca?! É como se eu estivesse enfrentando uma pessoa completamente diferente!",
  ui_story_5086_50861002_51_dialog_content = "Mas não importa o quão poderoso você seja, você ainda está machucado.",
  ui_story_5086_50861002_52_dialog_content = "Ataque!",
  ui_story_5086_50861002_53_dialog_content = "*Rugido*",
  ui_story_5086_50861002_54_dialog_content = "<color=#e8d9bb>Bang! Bang! Bang!</color>",
  ui_story_5086_50861002_55_dialog_content = "<color=#e8d9bb>Os Eclipsitas invadem a sala, mas são expulsos apenas um momento depois—Claro, nenhum deles está respirando agora.</color>",
  ui_story_5086_50861002_56_dialog_content = "O quê?!",
  ui_story_5086_50861002_57_dialog_content = "Em circunstâncias normais, os convidados devem tratar seu anfitrião com o máximo respeito.",
  ui_story_5086_50861002_58_dialog_content = "Desde que você atacou a donzela da minha família, você não me deixou escolha.",
  ui_story_5086_50861002_59_dialog_content = "Pelo bem da honra da família Andersen e para acalmar minha própria raiva...",
  ui_story_5086_50861002_60_dialog_content = "Devo me afastar da minha habitual cortesia.",
  ui_story_5086_50861002_61_dialog_content = "Que intrometido...",
  ui_story_5086_50861002_62_dialog_content = "*Rugido*",
  ui_story_5086_50861002_63_dialog_content = "Afaste-se, sua fera imunda.",
  ui_story_5086_50861002_64_dialog_content = "Humph, que criaturas covardes.",
  ui_story_5086_50861100_1_dialog_content = "Sanae—onde você está—",
  ui_story_5086_50861100_2_dialog_content = "Se você pode nos ouvir, diga algo!",
  ui_story_5086_50861100_3_dialog_content = "Sanae—",
  ui_story_5086_50861100_4_dialog_content = "Senhorita Moya! Não vá!",
  ui_story_5086_50861100_5_dialog_content = "Essa voz...!",
  ui_story_5086_50861100_6_dialog_content = "Froude! Maya!",
  ui_story_5086_50861100_7_dialog_content = "Ah, PlayerName...",
  ui_story_5086_50861100_8_dialog_content = "Você estará seguro aqui, Froude. Desculpe, mas tenho que ir agora.",
  ui_story_5086_50861100_9_dialog_content = "Eu não vou fazer isso! Eu não vou deixar você ir!",
  ui_story_5086_50861100_10_dialog_content = "Você a encontrou? A garota que estava controlando aqueles tubarões...",
  ui_story_5086_50861100_11_dialog_content = "Não deixe ela fugir!",
  ui_story_5086_50861100_12_dialog_content = "...",
  ui_story_5086_50861100_13_dialog_content = "Por favor, acalmem-se todos! Maya é—",
  ui_story_5086_50861100_14_dialog_content = "Vocês não sabem nada sobre ela! Vocês são todos um bando de idiotas!",
  ui_story_5086_50861100_15_dialog_content = "Froude...",
  ui_story_5086_50861100_16_dialog_content = "A senhorita Maya é a maior tola de todas! Ela nem mesmo sabe cuidar de si mesma!",
  ui_story_5086_50861100_17_dialog_content = "Ela nunca fez nada de errado! Tenho certeza que ela também quer pegar o malfeitor!",
  ui_story_5086_50861100_18_dialog_content = "Desculpe-me, mas não foi a Maya quem devolveu todos aqueles peixes para seus tanques antes que mordessem alguém?",
  ui_story_5086_50861100_19_dialog_content = "Eu... Eu sou daqui, e posso garantir por Maya! Nos últimos anos, tudo o que ela fez foi ajudar as pessoas por toda a cidade!",
  ui_story_5086_50861100_20_dialog_content = "Não acho que ela poderia ter machucado alguém.",
  ui_story_5086_50861100_21_dialog_content = "Ei! Qual é o problema com vocês?!",
  ui_story_5086_50861100_22_dialog_content = "Você está realmente defendendo ela em um momento como este?!",
  ui_story_5086_50861100_23_dialog_content = "Há uma maneira de descobrir de uma vez por todas.",
  ui_story_5086_50861100_24_dialog_content = "(Minos... Obrigado pela ajuda.)",
  ui_story_5086_50861100_25_dialog_content = "Não você de novo, criança... Espere, eu lembro agora! Você é o Celestita!",
  ui_story_5086_50861100_26_dialog_content = "Isso mesmo, o que significa que possuo habilidades psíquicas.",
  ui_story_5086_50861100_27_dialog_content = "Lembro-me de que você foi a primeira pessoa que apertou minha mão mais cedo. Já confirmei que você é completamente inocente neste caso.",
  ui_story_5086_50861100_28_dialog_content = "Th-Isso é verdade.",
  ui_story_5086_50861100_29_dialog_content = "Não há como negar o talento da criança.",
  ui_story_5086_50861100_30_dialog_content = "Isso também significa que posso provar se Maya é inocente ou não agora mesmo.",
  ui_story_5086_50861100_31_dialog_content = "Desculpe, Maya. Eu sei que disse que não usaria meus poderes em você se não estivesse de acordo.",
  ui_story_5086_50861100_32_dialog_content = "Mas estou convencido de que você é uma boa pessoa, e muitas pessoas também sentem o mesmo.",
  ui_story_5086_50861100_33_dialog_content = "Você vai me deixar fazer isso, Maya?",
  ui_story_5086_50861100_34_dialog_content = "Mas...",
  ui_story_5086_50861100_35_dialog_content = "Ouça com atenção, Maya.",
  ui_story_5086_50861100_36_dialog_content = "O que eu disse agora foi apenas para fazer aquelas pessoas se afastarem.",
  ui_story_5086_50861100_37_dialog_content = "Então você não vai ler minha mente?",
  ui_story_5086_50861100_38_dialog_content = "E eu acho que é porque eu acreditei em você desde o início.",
  ui_story_5086_50861100_39_dialog_content = "Os meus poderes psíquicos funcionam nos dois sentidos. Até eu teria dificuldade em contar uma mentira quando nossas mentes estão conectadas.",
  ui_story_5086_50861100_40_dialog_content = "É por isso que eu quero que você olhe em minha mente primeiro, Maya.",
  ui_story_5086_50861100_41_dialog_content = "Se você acha que sou digno de sua confiança, então por favor me diga seus motivos para fazer tudo isso.",
  ui_story_5086_50861100_42_dialog_content = "Isso... está realmente bem?",
  ui_story_5086_50861100_43_dialog_content = "Você decide.",
  ui_story_5086_50861100_44_dialog_content = "<color=#e8d9bb>Com um pequeno aceno, Maya concorda silenciosamente.</color>",
  ui_story_5086_50861100_45_dialog_content = "<color=#e8d9bb>Depois disso, ela nervosamente estendeu a mão e deixou nossas pontas dos dedos se tocarem.</color>",
  ui_story_5086_50861100_46_option_content = "Mindlink!",
  ui_story_5086_50861100_47_dialog_content = "<color=#e8d9bb>Sob um sol deslumbrante, as flores se transformam em borboletas e voam para o céu para petiscar nuvens de marshmallows.</color>",
  ui_story_5086_50861100_48_dialog_content = "<color=#e8d9bb>Incontáveis bolhas iridescentes flutuam pelo céu, banhando o sonho com sua luminosidade caprichosa.</color>",
  ui_story_5086_50861100_49_dialog_content = "(Então este é o mundo dos sonhos da Maya... É lindo.)",
  ui_story_5086_50861100_50_dialog_content = "(Mas...)",
  ui_story_5086_50861100_51_dialog_content = "(Ah, cara! Por que eu sou um sapo de novo?!)",
  ui_story_5086_50861100_52_dialog_content = "Coaxo, coaxo!",
  ui_story_5086_50861100_53_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5086_50861100_54_dialog_content = "(Ai... Essa bola é feita de ouro sólido?!)",
  ui_story_5086_50861100_55_dialog_content = "Desculpe por isso, Sr. Froggy! Poderia <color=#FFB400>eu</color> ter minha bola de volta?",
  ui_story_5086_50861100_56_dialog_content = "Coaxo.",
  ui_story_5086_50861100_57_dialog_content = "Obrigado! Muah!",
  ui_story_5086_50861100_58_dialog_content = "!!!",
  ui_story_5086_50861100_59_dialog_content = "O-O que você está fazendo, Maya?! Você não pode simplesmente sair beijando as pessoas—Ei, eu voltei ao normal!",
  ui_story_5086_50861100_60_dialog_content = "Podemos jogar juntos se você quiser! Vamos lá!",
  ui_story_5086_50861100_61_dialog_content = "<color=#e8d9bb>De repente, nos encontramos sentados em uma carruagem dourada puxada por seis belos cavalos enquanto eles avançam para uma enorme bolha no céu.</color>",
  ui_story_5086_50861100_62_dialog_content = "Esta é a floresta de doces! O chão e as árvores são feitos de bolos e biscoitos, então coma o que quiser.",
  ui_story_5086_50861100_63_dialog_content = "Lembre-se de não comer a casa de pão de gengibre aqui, ou a bruxa ficará brava!",
  ui_story_5086_50861100_64_dialog_content = "<color=#e8d9bb>Depois de comer à vontade doces, pulamos nas costas de um cisne branco como a neve e voamos para outra bolha.</color>",
  ui_story_5086_50861100_65_dialog_content = "O palácio está organizando um baile, e todos estão convidados!",
  ui_story_5086_50861100_66_dialog_content = "Se escolhermos algumas vinhas à beira da estrada, podemos tecer algumas roupas que brilham mais do que a lua e as estrelas!",
  ui_story_5086_50861100_67_dialog_content = "<color=#e8d9bb>Depois de trocar para nossas belas novas roupas, nós subimos em um pé de feijão e entramos em outra bolha.</color>",
  ui_story_5086_50861100_68_dialog_content = "<color=#e8d9bb>Juntos, nós ampliamos através de incontáveis bolhas de sonho.</color>",
  ui_story_5086_50861100_69_dialog_content = "<color=#e8d9bb>Havia montanhas de ouro e prata, e até mesmo uma feita de vidro...</color>",
  ui_story_5086_50861100_70_dialog_content = "<color=#e8d9bb>Também ouvimos um concerto tocado por um burrinho, um galo, um gato e um cachorro...</color>",
  ui_story_5086_50861100_71_dialog_content = "... E do outro lado da cidade está um doutor onisciente.",
  ui_story_5086_50861100_72_dialog_content = "Ele sabe tudo sobre o mundo e pode responder qualquer pergunta!",
  ui_story_5086_50861100_73_dialog_content = "Sério? Se tivermos a chance de vê-lo, quero perguntar algo a ele-",
  ui_story_5086_50861100_74_dialog_content = "Você pode me dizer onde encontrar a verdadeira Maya?",
  ui_story_5086_50861100_75_dialog_content = "...",
  ui_story_5086_50861100_76_dialog_content = "Que estranho.",
  ui_story_5086_50861100_77_dialog_content = "<color=#e8d9bb>Uma luz peculiar brilha nos olhos de Maya.</color>",
  ui_story_5086_50861100_78_dialog_content = "Quando você percebeu isso?",
  ui_story_5086_50861100_79_dialog_content = "Desde o começo mesmo.",
  ui_story_5086_50861100_80_dialog_content = "Quando Maya nos contou sua história, pensei que seria bom se alguém se lembrasse de sua existência.",
  ui_story_5086_50861100_81_dialog_content = "Maya disse que nos tornamos amigos assim que nos apresentamos.",
  ui_story_5086_50861100_82_dialog_content = "Então, lembrar dela é o mínimo que eu poderia fazer, certo?",
  ui_story_5086_50861100_83_dialog_content = "Um caderno não deveria ser a única coisa que prova a existência dela no mundo.",
  ui_story_5086_50861100_84_dialog_content = "Mas então... Quem cuidava dela antes de ela conhecer outras pessoas?",
  ui_story_5086_50861100_85_dialog_content = "...",
  ui_story_5086_50861100_86_dialog_content = "Além do meu sangue, meus descendentes também herdam o poder de manipular o ambiente ao redor, e até mesmo a própria realidade.",
  ui_story_5086_50861100_87_dialog_content = "Com o passar do tempo, minha linhagem enfraqueceu e meus descendentes já não conseguem mais controlar esse poder.",
  ui_story_5086_50861100_88_dialog_content = "Não só ela é incapaz de manejar meu poder, mas nossa conexão sanguínea também se tornou tênue. Isso faz com que ela perca suas memórias e se entregue a mundos de fantasia.",
  ui_story_5086_50861100_89_dialog_content = "Se o portador não conseguir comandar meu poder, ele também influenciará as pessoas ao seu redor. Apenas ver ou cheirar meu sangue ou ouvir minha voz os prenderá em uma ilusão.",
  ui_story_5086_50861100_90_dialog_content = "Então, quando Maya disse que não conseguia sangrar...",
  ui_story_5086_50861100_91_dialog_content = "No entanto, a situação no aquário deve ter algo a ver com o poder de Maya.",
  ui_story_5086_50861100_92_dialog_content = "Se você é o Ancestral que ela mencionou antes... Poderia me dizer o que aconteceu aqui?",
  ui_story_5086_50861100_93_dialog_content = "Como eu disse antes, meus descendentes não têm a capacidade de controlar sonhos.",
  ui_story_5086_50861100_94_dialog_content = "No entanto, ela conseguiu tudo isso.",
  ui_story_5086_50861100_95_dialog_content = "Se você realmente é amigo dela, então deveria saber a causa desses eventos.",
  ui_story_5086_50861100_96_dialog_content = "Você tem razão...",
  ui_story_5086_50861100_97_dialog_content = "May Posso te fazer uma última pergunta?",
  ui_story_5086_50861100_98_dialog_content = "O mundo de Maya é como um conto de fadas. É um lugar perfeito que tem tudo o que uma pessoa poderia querer.",
  ui_story_5086_50861100_99_dialog_content = "Mas eu notei algo estranho enquanto estávamos voando por todos esses sonhos... Por que eu não vi o oceano em nenhum deles?",
  ui_story_5086_50861100_100_dialog_content = "Você deve ter visto o mar até agora.",
  ui_story_5086_50861100_101_dialog_content = "Dentro do pesadelo que meus descendentes não ousam ver.",
  ui_story_5086_50861100_102_dialog_content = "Compreendo... Agora entendi.",
  ui_story_5086_50861100_103_dialog_content = "Você responderá a uma pergunta minha?",
  ui_story_5086_50861100_104_dialog_content = "Claro. Pergunte qualquer coisa.",
  ui_story_5086_50861100_105_dialog_content = "Se...",
  ui_story_5086_50861100_106_dialog_content = "Hã? Você...",
  ui_story_5086_50861100_107_dialog_content = "Se eu te desse todos os meus vestidos, gemas e pérolas...",
  ui_story_5086_50861100_108_dialog_content = "Você ficaria aqui comigo para sempre?",
  ui_story_5086_50861100_109_dialog_content = "...",
  ui_story_5086_50861100_110_dialog_content = "Eu não quero seus tesouros de jeito nenhum, Maya.",
  ui_story_5086_50861100_111_dialog_content = "Eu só quero que você sorria.",
  ui_story_5086_50861100_112_dialog_content = "E essa é a verdade, tanto aqui quanto no mundo real.",
  ui_story_5086_50861100_113_dialog_content = "!",
  ui_story_5086_50861100_114_dialog_content = "<color=#e8d9bb>O longo e distante canto começa novamente.</color>",
  ui_story_5086_50861100_115_dialog_content = "<color=#e8d9bb>A cena onírica ao redor deles se transforma em névoa e desaparece gradualmente, revelando novamente o aquário fracamente iluminado.</color>",
  ui_story_5086_50861100_116_dialog_content = "Estamos de volta... Huh? Por que todos estão dormindo?",
  ui_story_5086_50861100_117_dialog_content = "Ahhh—Que soneca maravilhosa! Heehee!",
  ui_story_5086_50861100_118_dialog_content = "Bem-vinda de volta, Maya.",
  ui_story_5086_50861100_119_dialog_content = "Sei que disse tudo isso agora, mas você não precisa se forçar a sorrir se não estiver com vontade.",
  ui_story_5086_50861100_120_dialog_content = "Não seria certo se você o fizesse.",
  ui_story_5086_50861100_121_dialog_content = "...",
  ui_story_5086_50861100_122_dialog_content = "Desde que aquele convidado desapareceu, você não sorriu uma vez sequer. Não um sorriso verdadeiro, de qualquer forma.",
  ui_story_5086_50861100_123_dialog_content = "... Eu simplesmente não sei mais o que fazer.",
  ui_story_5086_50861100_124_dialog_content = "Então você sabia exatamente quem fez aquela pessoa desaparecer o tempo todo.",
  ui_story_5086_50861100_125_dialog_content = "Quero que as pessoas sintam remorso quando fazem coisas ruins...",
  ui_story_5086_50861100_126_dialog_content = "Eu a enviei para aquele sonho para se arrepender até que esteja pronta para compensar a todos.",
  ui_story_5086_50861100_127_dialog_content = "Eu... Eu só tenho que me esforçar um pouco mais para preservar o sonho dela!",
  ui_story_5086_50861100_128_dialog_content = "Tenho certeza de que ela sabe que o que fez foi errado!",
  ui_story_5086_50861100_129_dialog_content = "Então por favor, só me dê um pouco mais de tempo...",
  ui_story_5086_50861100_130_dialog_content = "Você não pode apagar os erros de outras pessoas, Maya.",
  ui_story_5086_50861100_131_dialog_content = "E também não podemos viver em um sonho para sempre.",
  ui_story_5086_50861100_132_dialog_content = "E no seu coração, você já sabe disso. É por isso que o aquário voltou a este estado novamente.",
  ui_story_5086_50861100_133_dialog_content = "Você ainda não dominou a habilidade de controlar sonhos, é por isso que eles se tornam assustadores sempre que você se força a fazer isso.",
  ui_story_5086_50861100_134_dialog_content = "Eu não entendo... Por que ela não se arrepende de suas ações? Por que ela insiste em nos fazer machucar um ao outro?",
  ui_story_5086_50861100_135_dialog_content = "Talvez seja porque nem todos são tão fortes quanto você, Maya.",
  ui_story_5086_50861100_136_dialog_content = "Seria eu... sendo forte?",
  ui_story_5086_50861100_137_dialog_content = "Mesmo que eu esteja chorando?",
  ui_story_5086_50861100_138_dialog_content = "Não é nada disso.",
  ui_story_5086_50861100_139_dialog_content = "Tudo bem chorar e ficar com raiva quando sentimos dor ou desesperança. É uma reação perfeitamente normal.",
  ui_story_5086_50861100_140_dialog_content = "Pessoas fortes não se tornam fracas só porque choram.",
  ui_story_5086_50861100_141_dialog_content = "Não entendi.",
  ui_story_5086_50861100_142_dialog_content = "Hmm, então deixe-me colocar de outra forma.",
  ui_story_5086_50861100_143_dialog_content = "Se você algum dia se encontrar em sérios problemas...",
  ui_story_5086_50861100_144_dialog_content = "Por exemplo, imagine se o aquário começasse a receber menos visitantes e estivesse em perigo de fechar.",
  ui_story_5086_50861100_145_dialog_content = "Qual a primeira coisa que você vai fazer?",
  ui_story_5086_50861100_146_dialog_content = "Fechando...? De jeito nenhum! Se isso acontecesse, eu sairia e encontraria mais convidados!",
  ui_story_5086_50861100_147_dialog_content = "Então, o que você faria se ninguém em Harbour City estivesse disposto a visitar o aquário?",
  ui_story_5086_50861100_148_dialog_content = "Vá para um lugar bem, bem distante! Eu vou para fora de Harbour City, ou para o outro lado do mar, ou até mesmo para o outro lado do céu!",
  ui_story_5086_50861100_149_dialog_content = "Eu apenas continuaria procurando! Tenho certeza que vou encontrar alguém que queira nos visitar eventualmente!",
  ui_story_5086_50861100_150_dialog_content = "E se você falhar?",
  ui_story_5086_50861100_151_dialog_content = "Se a princípio você não conseguir, tente e tente novamente!",
  ui_story_5086_50861100_152_dialog_content = "E você não se sentiria desanimado com isso?",
  ui_story_5086_50861100_153_dialog_content = "Vou me sentir mal, mas sempre haverá amanhã! Além disso, não é como se eu fosse me lembrar de algo!",
  ui_story_5086_50861100_154_dialog_content = "Mas eu sei que, enquanto eu continuar tentando o meu melhor, eventualmente terei sucesso!",
  ui_story_5086_50861100_155_dialog_content = "Porque é simplesmente assim que o mundo funciona!",
  ui_story_5086_50861100_156_dialog_content = "E é isso que me torna forte.",
  ui_story_5086_50861100_157_dialog_content = "A maioria das pessoas no mundo não ousa ter esperanças como você, Maya.",
  ui_story_5086_50861100_158_dialog_content = "Isso porque eles vivem em uma bolha conhecida como realidade.",
  ui_story_5086_50861100_159_dialog_content = "Nessa bolha, o trabalho duro não é garantido para dar frutos, e milagres não acontecem apenas porque as pessoas acreditam neles.",
  ui_story_5086_50861100_160_dialog_content = "Algumas pessoas nunca chegam a ver um final feliz para suas histórias. Eles apenas sofrem dificuldade após dificuldade dolorosa.",
  ui_story_5086_50861100_161_dialog_content = "Seria um fardo tão pesado e difícil de carregar, e não há como dizer por quanto tempo você teria que carregá-lo.",
  ui_story_5086_50861100_162_dialog_content = "Às vezes, eles nem mesmo sabem se essas histórias amargas algum dia chegarão ao fim.",
  ui_story_5086_50861100_163_dialog_content = "A maioria das pessoas acabaria sucumbindo ao peso eventualmente, sem maneira de se levantar e se mover novamente.",
  ui_story_5086_50861100_164_dialog_content = "Mas eu não gosto disso...",
  ui_story_5086_50861100_165_dialog_content = "Ninguém faz, Maya.",
  ui_story_5086_50861100_166_dialog_content = "Então, aqueles que acham impossível suportar mais tempo impõem isso aos outros.",
  ui_story_5086_50861100_167_dialog_content = "Ahn???",
  ui_story_5086_50861100_168_dialog_content = "Enquanto alguém mais luta por ele, ele pode sofrer um pouco mais. Enquanto alguém mais se machuca em seu lugar, ele continuará avançando.",
  ui_story_5086_50861100_169_dialog_content = "Contanto que haja pessoas dispostas a compartilhar seu fardo, ele pode viver para ver um final feliz em sua história um dia.",
  ui_story_5086_50861100_170_dialog_content = "...",
  ui_story_5086_50861100_171_dialog_content = "Aquela pessoa... Ele também era assim.",
  ui_story_5086_50861100_172_dialog_content = "Ele transferiu sua dor para outras pessoas apenas para continuar.",
  ui_story_5086_50861100_173_dialog_content = "Ela fez uma coisa ruim, algo que nunca deveria ter feito.",
  ui_story_5086_50861100_174_dialog_content = "Bem, eu entendo seu desejo de fazer os malfeitores se arrependerem.",
  ui_story_5086_50861100_175_dialog_content = "Mas aqueles que cometem o mal são fracos de coração, então eles não conseguem suportar o peso de seus erros sozinhos.",
  ui_story_5086_50861100_176_dialog_content = "Mesmo que seja triste, só podemos enfrentá-los e buscar justiça.",
  ui_story_5086_50861100_177_dialog_content = "Desculpe, Maya... Mas é inatingível apenas com sonhos.",
  ui_story_5086_50861100_178_dialog_content = "Pessoas boas merecem ser recompensadas, e pessoas más merecem ser punidas. Até eu sei disso...",
  ui_story_5086_50861100_179_dialog_content = "E essa é a única maneira de uma história alcançar seu fim.",
  ui_story_5086_50861100_180_dialog_content = "Presenciei inúmeros sonhos tristes. Obrigada por me permitir presenciar tais sonhos preciosos.",
  ui_story_5086_50861100_181_dialog_content = "Não se preocupe, Maya... Vou ficar ao seu lado, mesmo que eu não possa fazer muito para ajudar.",
  ui_story_5086_50861100_182_dialog_content = "Não, isso já é mais do que suficiente.",
  ui_story_5086_50861100_183_dialog_content = "Não vou desistir. Vou resolver as coisas na realidade para que todos voltem a sorrir!",
  ui_story_5086_50861100_184_dialog_content = "Peço desculpas, Ancestral. Por favor, me ajude a mandar todos de volta!",
  ui_story_5086_50861100_185_dialog_content = "<color=#e8d9bb>No próximo momento, o aquário escurecido desaparece como uma bolha estourada.</color>",
  ui_story_5086_50861100_186_dialog_content = "<color=#e8d9bb>Vagamente, ouço uma voz em algum lugar por perto...</color>",
  ui_story_5086_50861100_187_dialog_content = "Descendente dos Celestitas, imploro que proteja meu sangue.",
  ui_story_5086_50861100_188_dialog_content = "Ela é uma raridade, uma pessoa de sinceridade pura e intocada.",
  ui_story_5086_50861100_189_dialog_content = "<color=#e8d9bb>E assim a ilusão distorcida finalmente chegou ao fim.</color>",
  ui_story_5086_50861201_1_dialog_content = "Urgh... Quando foi que eu adormeci... Huh? Tudo voltou ao normal?",
  ui_story_5086_50861201_2_dialog_content = "A energia está ligada e o aquário está totalmente bem.",
  ui_story_5086_50861201_3_dialog_content = "Até a porta está intacta, e nada está inundado.",
  ui_story_5086_50861201_4_dialog_content = "Foi tudo apenas um sonho?",
  ui_story_5086_50861201_5_dialog_content = "Ah! Ei! Você está bem?!",
  ui_story_5086_50861201_6_dialog_content = "Nngh... O-O que está acontecendo...?",
  ui_story_5086_50861201_7_dialog_content = "Eu pensei que você tinha desaparecido! Graças a Deus você só tem alguns ferimentos leves...",
  ui_story_5086_50861201_8_dialog_content = "Que diabos acabamos de experimentar...?",
  ui_story_5086_50861201_9_dialog_content = "Foi tudo uma ilusão, mas graças à Maya, ninguém mais se machucou.",
  ui_story_5086_50861201_10_dialog_content = "Eu... eu não consigo me lembrar mais.",
  ui_story_5086_50861201_11_dialog_content = "Tenho certeza de que Maya ficou intrigada com esses casos e trabalhou duro para resolvê-los.",
  ui_story_5086_50861201_12_dialog_content = "Então, quando ela finalmente capturou a malícia do culpado, ela imprudentemente lançou aquela ilusão.",
  ui_story_5086_50861201_13_dialog_content = "Maya estava com medo de que alguém se machucasse, então ela usou desesperadamente uma habilidade que May até mesmo prejudicar a si mesma, e é por isso que o pesadelo permaneceu apenas um pesadelo.",
  ui_story_5086_50861201_14_dialog_content = "Consegui compensar alguns dos erros daquela pessoa?",
  ui_story_5086_50861201_15_dialog_content = "... Sim.",
  ui_story_5086_50861201_16_dialog_content = "Cadê a senhorita Stellandine?",
  ui_story_5086_50861201_17_dialog_content = "Como ela é a única que não está aqui?",
  ui_story_5086_50861201_18_dialog_content = "Aconteceu alguma coisa? Havia um grupo de Eclipsitas lá atrás...",
  ui_story_5086_50861201_19_dialog_content = "Isso não é necessário.",
  ui_story_5086_50861201_20_dialog_content = "Tenho medo que ela seja a única entre nós que não precisa se preocupar com os Eclipsitas de forma alguma.",
  ui_story_5086_50861201_21_dialog_content = "Minos, você sabia desde o início?",
  ui_story_5086_50861201_22_dialog_content = "Você pensa muito bem de mim. Eu também gradualmente confirmei minhas suspeitas através de certas características.",
  ui_story_5086_50861201_23_dialog_content = "Do que você está falando?",
  ui_story_5086_50861201_24_dialog_content = "Tenho certeza que todos vocês ouviram o conto de fadas sobre a princesa sereia.",
  ui_story_5086_50861201_25_dialog_content = "Contos de fadas podem ser uma fantasia, eles ainda têm um lado que está enraizado na realidade - Metáforas ou lições.",
  ui_story_5086_50861201_26_dialog_content = "Uma das maneiras de interpretar esse conto de fadas é que ele exibe a forma e os hábitos de um tipo de forma de vida marinha.",
  ui_story_5086_50861201_27_dialog_content = "Uma criatura que assume a forma de uma bela Aurorian usa sua voz e aparência para atrair marinheiros ou visitantes.",
  ui_story_5086_50861201_28_dialog_content = "Uma vez que seu alvo foi atraído...",
  ui_story_5086_50861201_29_dialog_content = "Ele puxa o alvo para as profundezas do oceano, transformando-os em sua comida.",
  ui_story_5086_50861201_30_dialog_content = "Então, a princesa sereia não é nada mais do que um monstro que caça com o \"desejo\" como sua isca.",
  ui_story_5086_50861201_31_dialog_content = "Não me diga que...",
  ui_story_5086_50861201_32_dialog_content = "Então todos os desaparecimentos foram causados pela criatura que se infiltrou no nosso grupo?",
  ui_story_5086_50861201_33_dialog_content = "Não importa como se transforme, um monstro sempre...",
  ui_story_5086_50861201_34_dialog_content = "Cale a boca!",
  ui_story_5086_50861201_35_dialog_content = "Eclipsitas!",
  ui_story_5086_50861201_36_dialog_content = "Cale a boca! Cale a boca! Cale a boca!!!",
  ui_story_5086_50861201_37_dialog_content = "Não, essa voz... Senhorita Stellandine?!",
  ui_story_5086_50861201_38_dialog_content = "?!",
  ui_story_5086_50861201_39_dialog_content = "Monstro? Criatura?!",
  ui_story_5086_50861201_40_dialog_content = "Se você está com fome, você come! É o mesmo para todos!",
  ui_story_5086_50861201_41_dialog_content = "Nenhuma desculpa no mundo mudará o fato de que você também depende da carne e do sangue de outros seres vivos para sobreviver!",
  ui_story_5086_50861201_42_dialog_content = "É só que nossa comida é diferente...",
  ui_story_5086_50861201_43_dialog_content = "Então por que você se segurou até agora?",
  ui_story_5086_50861201_44_dialog_content = "!",
  ui_story_5086_50861201_45_dialog_content = "Mesmo que você estivesse lutando em uma ilusão, ainda valia a pena estudar.",
  ui_story_5086_50861201_46_dialog_content = "Você é anormalmente fraco quando comparado a outros da sua espécie.",
  ui_story_5086_50861201_47_dialog_content = "É quase como se... Você não se alimentasse há muito tempo.",
  ui_story_5086_50861201_48_dialog_content = "O quê? Você realmente pensou que comer Aurorians suficientes permitiria que você vivesse como um?",
  ui_story_5086_50861201_49_dialog_content = "Eu disse para você calar a boca!",
  ui_story_5086_50861201_50_dialog_content = "Pelo que entendi, criaturas como você podem ler e aprender com as memórias dos Aurorianos que você devorou.",
  ui_story_5086_50861201_51_dialog_content = "No entanto, você não possui um sistema de processamento abrangente. Então, quanto mais você devora, mais caóticas as memórias se tornam.",
  ui_story_5086_50861201_52_dialog_content = "Você nunca deveria ter vivido em terra, mas a Stellandine existe há muito tempo.",
  ui_story_5086_50861201_53_dialog_content = "Não, eu deveria dizer que você está \"preso\" há muito tempo.",
  ui_story_5086_50861201_54_dialog_content = "Não só você deixou o oceano e viveu como um Aurorian, mas também tem se recusado a se alimentar por muito tempo.",
  ui_story_5086_50861201_55_dialog_content = "Eu realmente quero saber. Por que você fez isso?",
  ui_story_5086_50861201_56_dialog_content = "E-Eu quero...",
  ui_story_5086_50861201_57_dialog_content = "Então foi isso.",
  ui_story_5086_50861201_58_dialog_content = "Você esqueceu.",
  ui_story_5086_50861201_59_dialog_content = "Não tenho mais perguntas. No final, você ainda é um Eclipsite lamentável.",
  ui_story_5086_50861201_60_dialog_content = "Ora, você...!",
  ui_story_5086_50861201_61_dialog_content = "Senhorita Stellandine...",
  ui_story_5086_50861201_62_dialog_content = "Você fez muitas coisas ruins e imperdoáveis!",
  ui_story_5086_50861201_63_dialog_content = "Mas... Eu sei que você realmente desejava se tornar um Auroriano... É por isso que nunca senti nenhuma maldade.",
  ui_story_5086_50861201_64_dialog_content = "Se você ainda está disposto a mudar, então estou disposto a buscar a expiação com você...",
  ui_story_5086_50861201_65_dialog_content = "Senhorita Maya, ela é uma Eclipsita.",
  ui_story_5086_50861201_66_dialog_content = "Enquanto isso permanecer um fato, sempre seremos inimigos.",
  ui_story_5086_50861201_67_dialog_content = "Eu não estou tentando defendê-la ou algo assim... Mas a Srta. Stellandine realmente se foi para sempre?",
  ui_story_5086_50861201_68_dialog_content = "... Já chega.",
  ui_story_5086_50861201_69_dialog_content = "Senhorita Stellandine?",
  ui_story_5086_50861201_70_dialog_content = "Ah, Maya...",
  ui_story_5086_50861201_71_dialog_content = "Que enorme tolo!!",
  ui_story_5086_50861201_72_dialog_content = "...Hã?",
  ui_story_5086_50861201_73_dialog_content = "É isso! Essa é a expressão que conquista o carinho de todos.",
  ui_story_5086_50861201_74_dialog_content = "É tão triste que eu não consigo me lembrar de nada, mas sei que todos vão gostar de mim se eu der o meu melhor na vida!",
  ui_story_5086_50861201_75_dialog_content = "Tenho certeza de que você está gostando muito, certo? Você deve estar tão satisfeito consigo mesmo agora!",
  ui_story_5086_50861201_76_dialog_content = "Minha pequena e adorável Maya... Mas qual era o uso? Em toda a sua vida, você nunca fez nada significativo...",
  ui_story_5086_50861201_77_dialog_content = "Mas por que você é o único que desfruta do amor de todos?!!",
  ui_story_5086_50861201_78_dialog_content = "Não, Senhorita Stellandine... Por favor... Não diga coisas assim...",
  ui_story_5086_50861201_79_dialog_content = "Esse foi o único motivo pelo qual fui tão gentil com você! Para que a dor da traição doesse ainda mais!",
  ui_story_5086_50861201_80_dialog_content = "Você menina tola! Você realmente acreditou que um monstro teria emoções de Aurorian?! Hahaha! Você realmente caiu nisso, hein?",
  ui_story_5086_50861201_81_dialog_content = "Mas senhorita Stellandine, eu posso ver que você ainda está chorando por dentro...",
  ui_story_5086_50861201_82_dialog_content = "<color=#e8d9bb>Bata!</color>",
  ui_story_5086_50861201_83_dialog_content = "<color=#e8d9bb>Uma boneca de baleia bate repentinamente contra Stellandine.</color>",
  ui_story_5086_50861201_84_dialog_content = "A senhorita Moya é uma pessoa muito melhor do que você jamais será!",
  ui_story_5086_50861201_85_dialog_content = "Ela nos conta histórias e trabalha duro pelo aquário...",
  ui_story_5086_50861201_86_dialog_content = "Mesmo que ela mal se lembre de qualquer coisa, ela sempre me encontra perto das baleias sempre que eu escapo!",
  ui_story_5086_50861201_87_dialog_content = "Mas você? Você nunca se deu ao trabalho de lembrar nenhum dos nossos nomes!",
  ui_story_5086_50861201_88_dialog_content = "Isso mesmo, Maya trata todos com sinceridade! Você não deveria ter decepcionado ela, Senhorita Stellandine.",
  ui_story_5086_50861201_89_dialog_content = "Receba sua retribuição! Monstro!",
  ui_story_5086_50861201_90_dialog_content = "<color=#e8d9bb>Bata! Bata! Bata!</color>",
  ui_story_5086_50861201_91_dialog_content = "<color=#e8d9bb>Bonecas, chaves e até pedras de dentro das piscinas do aquário... Os visitantes começam a atirar em Stellandine com quaisquer objetos que conseguem encontrar.</color>",
  ui_story_5086_50861201_92_dialog_content = "Nossa, que cena tocante...",
  ui_story_5086_50861201_93_dialog_content = "Então vocês podem todos morrer juntos!!",
  ui_story_5086_50861202_1_dialog_content = "Acabou, Senhorita Stellandine. Tanto a sua vida quanto os seus desejos.",
  ui_story_5086_50861202_2_dialog_content = "Posso... ir até ela?",
  ui_story_5086_50861202_3_dialog_content = "Isso não é aconselhável, Senhorita Maya.",
  ui_story_5086_50861202_4_dialog_content = "Vá em frente, Maya.",
  ui_story_5086_50861202_5_dialog_content = "Obrigada!",
  ui_story_5086_50861202_6_dialog_content = "Isso é imprudente.",
  ui_story_5086_50861202_7_dialog_content = "No entanto, as emoções às vezes entram em conflito com a razão, Minos.",
  ui_story_5086_50861202_8_dialog_content = "...",
  ui_story_5086_50861202_9_dialog_content = "Isso é verdade. Prossiga, Maya!",
  ui_story_5086_50861202_10_dialog_content = "Eu tenho enfatizado constantemente nossa posição contra os Eclipsitas...",
  ui_story_5086_50861202_11_dialog_content = "Estou ciente, Minos.",
  ui_story_5086_50861202_12_dialog_content = "Os crimes da Srta. Stellandine são imperdoáveis, e por isso a punimos.",
  ui_story_5086_50861202_13_dialog_content = "Mas para Maya, ela ainda é alguém importante que uma vez cuidou dela.",
  ui_story_5086_50861202_14_dialog_content = "Mesmo se ela derrotou a própria Miss Stellandine... Ela ainda não consegue se livrar dessas emoções.",
  ui_story_5086_50861202_15_dialog_content = "Quando se trata de nós e os Eclipsitas, não temos escolha senão ver as coisas em preto e branco.",
  ui_story_5086_50861202_16_dialog_content = "Se a senhorita Maya deseja permanecer em Harbour City, essas experiências só irão manchar sua vida aqui.",
  ui_story_5086_50861202_17_dialog_content = "... A menos que a \"mancha\" seja convertida em \"dor.\"",
  ui_story_5086_50861202_18_dialog_content = "O que a faria parecer uma vítima inocente que havia sido enganada o tempo todo.",
  ui_story_5086_50861202_19_dialog_content = "Espere... É por isso que você e a Senhorita Stellandine apenas—",
  ui_story_5086_50861202_20_dialog_content = "Shhh.",
  ui_story_5086_50861202_21_dialog_content = "Não importa o quão metafóricos eles sejam, os contos de fadas sempre serão populares entre as crianças.",
  ui_story_5086_50861202_22_dialog_content = "Desde que os justos triunfem e os malvados sofram derrota, isso deve ser mais do que suficiente para um final feliz.",
  ui_story_5086_50861202_23_dialog_content = "Pensar demais só vai roubar de você essa alegria pura.",
  ui_story_5086_50861202_24_dialog_content = "...",
  ui_story_5086_50861202_25_dialog_content = "Senhorita Stellandine...",
  ui_story_5086_50861202_26_dialog_content = "Sinto muito. Eu não fazia ideia.",
  ui_story_5086_50861202_27_dialog_content = "Não importa se era seu desejo, dor, ou algo que você tem suportado constantemente...",
  ui_story_5086_50861202_28_dialog_content = "Se eu tivesse notado isso antes, talvez eu pudesse ter ajudado...",
  ui_story_5086_50861202_29_dialog_content = "Você é um grande tolo...",
  ui_story_5086_50861202_30_dialog_content = "Você me odeia depois de ouvir tudo isso?",
  ui_story_5086_50861202_31_dialog_content = "A senhorita Stellandine me deu um lar em seu aquário.",
  ui_story_5086_50861202_32_dialog_content = "Jamais, jamais esquecerei!",
  ui_story_5086_50861202_33_dialog_content = "Sou muito esquecido, então me recuso a simplesmente deixar alguém ir!",
  ui_story_5086_50861202_34_dialog_content = "Eu nem consigo lembrar quantos aurorianos eu já comi.",
  ui_story_5086_50861202_35_dialog_content = "Vou te ajudar a expiar.",
  ui_story_5086_50861202_36_dialog_content = "Eu os matei! Não é da sua conta... Como você vai compensar as vidas perdidas?",
  ui_story_5086_50861202_37_dialog_content = "Não posso trazer de volta os inocentes que se foram, mas pretendo ajudar todos a superar sua dor!",
  ui_story_5086_50861202_38_dialog_content = "May seja prostrando-me a eles ou fazendo reparações pela dor que sofrem, trabalharei duro para esse fim!",
  ui_story_5086_50861202_39_dialog_content = "Se você está morrendo de fome agora, pode comer um pouco da minha carne, Senhorita Stellandine!",
  ui_story_5086_50861202_40_dialog_content = "Vou esquecer a dor e também vou me curar rápido!",
  ui_story_5086_50861202_41_dialog_content = "Só desejo chorar meu coração por você, aquele que uma vez cuidou de mim, e eu compensarei a todos no futuro.",
  ui_story_5086_50861202_42_dialog_content = "Então... Não me afaste...",
  ui_story_5086_50861202_43_dialog_content = "Xiu... Não diga coisas assim, eu já estou...",
  ui_story_5086_50861202_44_dialog_content = "Você não tem nada para retribuir, minha criança... Sou eu quem tem uma dívida para pagar...",
  ui_story_5086_50861202_45_dialog_content = "Então, as pessoas realmente falam sinceramente quando é a última vez, hein?",
  ui_story_5086_50861202_46_dialog_content = "Você é... muito parecido com ele.",
  ui_story_5086_50861202_47_dialog_content = "Imponente... Admirável...",
  ui_story_5086_50861202_48_dialog_content = "...",
  ui_story_5086_50861202_49_dialog_content = "Ele ignorou meu canto e se concentrou apenas em combater a tempestade.",
  ui_story_5086_50861202_50_dialog_content = "Ele parecia absolutamente bonito enquanto estabilizava desesperadamente o navio em meio à tempestade furiosa.",
  ui_story_5086_50861202_51_dialog_content = "Eu queria esperar pelo seu retorno, mas ele nunca o fez... Eu desembarquei em busca dele, mas não consegui encontrá-lo...",
  ui_story_5086_50861202_52_dialog_content = "Comi muitos Aurorianos, e muitos rostos novos apareceram em minhas memórias.",
  ui_story_5086_50861202_53_dialog_content = "E conforme o tempo passava... eu não conseguia mais dizer qual rosto pertencia a ele.",
  ui_story_5086_50861202_54_dialog_content = "Parecia que eu ainda estava esperando, mas toda a minha espera...",
  ui_story_5086_50861202_55_dialog_content = "Não foi nada mais do que um devaneio.",
  ui_story_5086_50861202_56_dialog_content = "E-Eu vou encontrá-lo para você.",
  ui_story_5086_50861202_57_dialog_content = "Não... Você não precisa.",
  ui_story_5086_50861202_58_dialog_content = "Porque eu peguei uma garotinha bem na entrada do aquário, uma garotinha tola e ingênua que nunca duvidou de ninguém...",
  ui_story_5086_50861202_59_dialog_content = "Uma garotinha barulhenta que nunca conseguia ficar quieta. E eu não pude deixar de me preocupar...",
  ui_story_5086_50861202_60_dialog_content = "O que ela faria sem mim?",
  ui_story_5086_50861202_61_dialog_content = "Pensei nisso... Pensei em ser Stellandine e ficar com minha Maya...",
  ui_story_5086_50861202_62_dialog_content = "Mas eu estava com tanta fome... Eu estava realmente... faminto...",
  ui_story_5086_50861202_63_dialog_content = "...",
  ui_story_5086_50861202_64_dialog_content = "Eu sabia que isso partiria o coração da minha Maya... Mas... Eu sou apenas um monstro que não conseguiu superar sua natureza...",
  ui_story_5086_50861202_65_dialog_content = "A única maneira de eu sobreviver era comer Aurorianos... E o que resultou disso? Hah!",
  ui_story_5086_50861202_66_dialog_content = "No final... Eu perdi tudo...",
  ui_story_5086_50861202_67_dialog_content = "Realmente sou um monstro deplorável...",
  ui_story_5086_50861202_68_dialog_content = "Se ao menos... eu tivesse o coração de um Auroriano... Então eu poderia ter...",
  ui_story_5086_50861202_69_dialog_content = "<color=#e8d9bb>Resumo—</color>",
  ui_story_5086_50861202_70_dialog_content = "?",
  ui_story_5086_50861202_71_dialog_content = "Esse lugar... Por quê? Não era eu...",
  ui_story_5086_50861202_72_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5086_50861202_73_dialog_content = "Uma tempestade?! Não pode ser!",
  ui_story_5086_50861202_74_dialog_content = "Nem pense em virar nosso navio, tempestade!",
  ui_story_5086_50861202_75_dialog_content = "Irmãos! Vamos mostrar a Poseidon o quão corajosos somos!",
  ui_story_5086_50861202_76_dialog_content = "Vamos atravessar essa tempestade! Levante! Ho!",
  ui_story_5086_50861202_77_dialog_content = "Ei! Desça lá e proteja aquele navio!",
  ui_story_5086_50861202_78_dialog_content = "E não faça mais nada a menos que eu dê a ordem.",
  ui_story_5086_50861202_79_dialog_content = "*Rugido*",
  ui_story_5086_50861202_80_dialog_content = "Hã? O navio de repente se estabilizou... Perfeito! Vamos correr agora!",
  ui_story_5086_50861202_81_dialog_content = "<color=#e8d9bb>O navio desaparece gradualmente no horizonte em meio à tempestade que diminui.</color>",
  ui_story_5086_50861202_82_dialog_content = "...",
  ui_story_5086_50861202_83_dialog_content = "Você não vai atrás deles?",
  ui_story_5086_50861202_84_dialog_content = "Não.",
  ui_story_5086_50861202_85_dialog_content = "Assim, eu não vou cometer os mesmos erros novamente, e não vou machucar aquela garotinha de novo.",
  ui_story_5086_50861202_86_dialog_content = "Posso extrair a aparência desse marinheiro de suas memórias.",
  ui_story_5086_50861202_87_dialog_content = "Pelo menos no final, você pode...",
  ui_story_5086_50861202_88_dialog_content = "Este é um sonho que a criança criou para mim, certo?",
  ui_story_5086_50861202_89_dialog_content = "... Sim.",
  ui_story_5086_50861202_90_dialog_content = "Estou morrendo?",
  ui_story_5086_50861202_91_dialog_content = "De uma vez só.",
  ui_story_5086_50861202_92_dialog_content = "Ótimo.",
  ui_story_5086_50861202_93_dialog_content = "Um monstro como eu deveria morrer com arrependimentos.",
  ui_story_5086_50861202_94_dialog_content = "Devo expiar meus pecados sofrendo uma dor eterna.",
  ui_story_5086_50861202_95_dialog_content = "Ela pode me ver?",
  ui_story_5086_50861202_96_dialog_content = "... Não.",
  ui_story_5086_50861202_97_dialog_content = "Então diga a ela que foi um sonho bom.",
  ui_story_5086_50861202_98_dialog_content = "Então...",
  ui_story_5086_50861202_99_dialog_content = "<color=#e8d9bb>Respingo.</color>",
  ui_story_5086_50861202_100_dialog_content = "<color=#e8d9bb>Minhas palavras são recebidas com uma força repentina que me empurra para longe e um leve respingo no oceano.</color>",
  ui_story_5086_50861202_101_dialog_content = "<color=#e8d9bb>Stellandine afunda na água e sua figura gradualmente se desfoca à medida que o vínculo é cortado.</color>",
  ui_story_5086_50861202_102_dialog_content = "<color=#e8d9bb>Ela nasceu do oceano e agora, parece ter retornado ao seu abraço. Imóvel... apenas afundando, e afundando até o fundo.</color>",
  ui_story_5086_50861202_103_dialog_content = "Stellandina!",
  ui_story_5086_50861202_104_dialog_content = "Hum-hum.",
  ui_story_5086_50861202_105_dialog_content = "<color=#e8d9bb>Ignorando minhas chamadas e obstrução, o monstro começa a cantar enquanto afunda no abismo.</color>",
  ui_story_5086_50861202_106_dialog_content = "<color=#e8d9bb>Uma canção de sereia pode enganar a mente e transformar todos que a ouvem em presas.</color>",
  ui_story_5086_50861202_107_dialog_content = "<color=#e8d9bb>Mas essa melodia não prejudicou ninguém.</color>",
  ui_story_5086_50861202_108_dialog_content = "<color=#e8d9bb>É apenas... Uma bênção triste e terna das profundezas geladas do oceano.</color>",
  ui_story_5086_50861202_109_dialog_content = "Minha... pobre... adorável... pequena Maya...",
  ui_story_5086_50861202_110_dialog_content = "May você... viva feliz... com aqueles que você ama.",
  ui_story_5086_50861202_111_dialog_content = "<color=#e8d9bb>O corpo de Stellandine começa a desaparecer no saguão do aquário.</color>",
  ui_story_5086_50861202_112_dialog_content = "É verdade que posso sentir o bem e o mal em uma pessoa.",
  ui_story_5086_50861202_113_dialog_content = "Então, mesmo que eu seja esquecido, não posso ser enganado tão facilmente.",
  ui_story_5086_50861202_114_dialog_content = "A Senhorita Stellandine era uma Eclipsita, mas desde o dia em que nos conhecemos, e até mesmo agora...",
  ui_story_5086_50861202_115_dialog_content = "Ela nunca teve sequer a menor maldade para comigo.",
  ui_story_5086_50861202_116_dialog_content = "Então, o mínimo que posso fazer é dar a ela um bom sonho, certo?",
  ui_story_5086_50861202_117_dialog_content = "De uma vez só.",
  ui_story_5086_50861202_118_dialog_content = "No passado, ela não conseguia abandonar seu desejo de sobreviver, nem podia desistir de seus pensamentos esperançosos.",
  ui_story_5086_50861202_119_dialog_content = "Mas quando ela deixou tudo ir e perdeu tudo, ainda estava disposta a dar suas sinceras bênçãos...",
  ui_story_5086_50861202_120_dialog_content = "Na minha opinião, ela se arrependeu, e então ela não era mais apenas um monstro.",
  ui_story_5086_50861202_121_dialog_content = "Ela desejava o coração de um auroriano, e agora, no momento de sua morte, ela pode gradualmente retribuir tudo.",
  ui_story_5086_50861202_122_dialog_content = "<color=#e8d9bb>Nas profundezas silenciosas do sonho oceânico.</color>",
  ui_story_5086_50861202_123_dialog_content = "<color=#e8d9bb>De repente, um raio de luz deslumbrante aparece diante da figura afundando de Stellandine.</color>",
  ui_story_5086_50861202_124_dialog_content = "<color=#e8d9bb>Um marinheiro se estende a ela de dentro da luz, seu rosto bonito claramente refletido em seus olhos.</color>",
  ui_story_5086_50861202_125_dialog_content = "Venha comigo.",
  ui_story_5086_50861202_126_dialog_content = "... Tá bem.",
  ui_story_5086_50861202_127_dialog_content = "<color=#e8d9bb>Stellandine sorri antes de desaparecer completamente.</color>",
  ui_story_5086_50861202_128_dialog_content = "Obrigada, PlayerName.",
  ui_story_5086_50861202_129_dialog_content = "Um... Eu não sei como dizer isso, mas obrigado por tudo.",
  ui_story_5086_50861202_130_dialog_content = "De modo algum. Eu apenas ajudei a Srta. Stellandine a lembrar do rosto do marinheiro.",
  ui_story_5086_50861202_131_dialog_content = "Na verdade, é você quem deu salvação à Senhorita Stellandine, Maya.",
  ui_story_5086_50861202_132_dialog_content = "Porque o amor é eterno...",
  ui_story_5086_50861202_133_dialog_content = "Ah, é! Minhas anotações!",
  ui_story_5086_50861202_134_dialog_content = "Devo anotar isso... Ah!",
  ui_story_5086_50861202_135_dialog_content = "<color=#e8d9bb>Enquanto Maya procura suas anotações, um cartão cai por trás da capa.</color>",
  ui_story_5086_50861202_136_dialog_content = "É esse... o Convés de Origem do Jeno?!",
  ui_story_5086_50861300_1_dialog_content = "<color=#e8d9bb>Após o incidente no circo—</color>",
  ui_story_5086_50861300_2_dialog_content = "Jeno...",
  ui_story_5086_50861300_3_dialog_content = "Não haverá mais apresentações.",
  ui_story_5086_50861300_4_dialog_content = "Eu sabia que você podia ler mentes, Jeno!",
  ui_story_5086_50861300_5_dialog_content = "Não, é porque você perguntaria se alguém procurou sua ajuda.",
  ui_story_5086_50861300_6_dialog_content = "Vamos deixar Harbour City assim que o Emerald for consertado.",
  ui_story_5086_50861300_7_dialog_content = "Hã? Mas tantos estão ansiosos pela apresentação, e... Elvis...",
  ui_story_5086_50861300_8_dialog_content = "Elvis é o motivo pelo qual devemos partir.",
  ui_story_5086_50861300_9_dialog_content = "Venha comigo, Maya.",
  ui_story_5086_50861300_10_dialog_content = "Minha partida está definida, mas você é novo, então não vou te forçar.",
  ui_story_5086_50861300_11_dialog_content = "Então você vai vir com a gente? Ou vai ficar aqui?",
  ui_story_5086_50861300_12_dialog_content = "Se eu for com você, posso ajudar você e o Elvis?",
  ui_story_5086_50861300_13_dialog_content = "Parece-me difícil porque você não pode controlar seu poder.",
  ui_story_5086_50861300_14_dialog_content = "Entendo...",
  ui_story_5086_50861300_15_dialog_content = "Entendi! Então vou ficar aqui mesmo!",
  ui_story_5086_50861300_16_dialog_content = "Elvis sempre cuidou de mim, e é hora de eu ajudá-lo a cuidar de Harbour City.",
  ui_story_5086_50861300_17_dialog_content = "Eu posso não ser o mais confiável... Mas prometo fazer o meu melhor para ajudar a todos!",
  ui_story_5086_50861300_18_dialog_content = "Agora que Elvis não é mais o Senhor da Cidade, ele não pode enviar ninguém para proteger você mais.",
  ui_story_5086_50861300_19_dialog_content = "Você terá que viver de forma independente como costumava fazer.",
  ui_story_5086_50861300_20_dialog_content = "Sou um trabalhador árduo, então não vou passar fome! Não se preocupe comigo! Tenho muita experiência de trabalho! Embora pareça ter esquecido tudo...",
  ui_story_5086_50861300_21_dialog_content = "Mas...",
  ui_story_5086_50861300_22_dialog_content = "A senhorita Stellandine do aquário foi muito gentil. Eu fiz muito dinheiro lá!",
  ui_story_5086_50861300_23_dialog_content = "Você deve se concentrar em assuntos mais importantes, Jeno!",
  ui_story_5086_50861300_24_dialog_content = "Então eu tenho um favor a pedir a você.",
  ui_story_5086_50861300_25_dialog_content = "Não me importo nem com cem favores!",
  ui_story_5086_50861300_26_dialog_content = "Não é nada grandioso. Eu só preciso que você passe uma mensagem.",
  ui_story_5086_50861300_27_dialog_content = "Bem... Tenho medo de que vou esquecer...",
  ui_story_5086_50861300_28_dialog_content = "É exatamente isso que faz de você uma pessoa tão confiável.",
  ui_story_5086_50861300_29_dialog_content = "Viva bem no aquário. Nós iremos te visitar algum dia.",
  ui_story_5086_50861300_30_dialog_content = "Então... isso significa que Maya era o mensageiro de Jeno, afinal?",
  ui_story_5086_50861300_31_dialog_content = "Uma mensagem?",
  ui_story_5086_50861300_32_dialog_content = "Eu não me lembro de nada assim...",
  ui_story_5086_50861300_33_dialog_content = "Mas eu vagamente me lembro de algo sobre cuidar bem deste cartão.",
  ui_story_5086_50861300_34_dialog_content = "Esqueci algo importante de novo?",
  ui_story_5086_50861300_35_dialog_content = "Não, acho que é parte do truque de Jeno.",
  ui_story_5086_50861300_36_dialog_content = "A maioria só percebe a água desaparecendo misteriosamente do copo.",
  ui_story_5086_50861300_37_dialog_content = "Mas aos olhos de um mágico, é tão simples quanto tirar um copo vazio de debaixo da mesa.",
  ui_story_5086_50861300_38_dialog_content = "Eu vejo! O enigma sempre esteve bem diante de nós! Embora ninguém além de mim pudesse descobri-lo!",
  ui_story_5086_50861300_39_dialog_content = "PlayerName, você vai tirar algo?",
  ui_story_5086_50861300_40_dialog_content = "São suas memórias.",
  ui_story_5086_50861300_41_dialog_content = "Ah, mas não se preocupe. Jeno não deixaria o Convés de Origem para trás.",
  ui_story_5086_50861300_42_dialog_content = "Se eu usar isso como meu guia, devo ser capaz de localizar a mensagem sem tocar em qualquer uma de suas outras memórias.",
  ui_story_5086_50861300_43_dialog_content = "Tudo bem.",
  ui_story_5086_50861300_44_dialog_content = "Uhh?",
  ui_story_5086_50861300_45_dialog_content = "PlayerName, mesmo que você tenha recusado roupas bonitas, gemas e até pérolas...",
  ui_story_5086_50861300_46_dialog_content = "Mas você é sempre bem-vindo para se divertir nos meus sonhos, os Ancestrais permitiram isso!",
  ui_story_5086_50861300_47_dialog_content = "Seria uma honra.",
  ui_story_5086_50861300_48_dialog_content = "Então—",
  ui_story_5086_50861300_49_option_content = "Mindlink!",
  ui_story_5086_50861300_50_dialog_content = "(Foco! Concentre-se na onda que sincroniza com o Deck de Origem...)",
  ui_story_5086_50861300_51_dialog_content = "(Encontrei!)",
  ui_story_5086_50861300_52_dialog_content = "Você é o único que poderia chegar aqui, então vou direto ao ponto.",
  ui_story_5086_50861300_53_dialog_content = "Elvis está acordado.",
  ui_story_5086_50861300_54_dialog_content = "(!)",
  ui_story_5086_50861300_55_dialog_content = "Embora tenha sido por apenas um momento, e ele tenha adormecido logo depois, é suficiente para provar que o método de tratamento da <color=#FFB400>mulher</color> está indo na direção certa.",
  ui_story_5086_50861300_56_dialog_content = "Elvis... nunca considera o quadro geral. Ele apenas avança cegamente ao vislumbrar até mesmo um lampejo de esperança e deixa todos para trás.",
  ui_story_5086_50861300_57_dialog_content = "Ele é um homem absolutamente egoísta, mas justo.",
  ui_story_5086_50861300_58_dialog_content = "Mas eu não tenho o direito de falar mal dele. Porque não importa o que ele faça, eu acho impossível odiá-lo.",
  ui_story_5086_50861300_59_dialog_content = "Então, minha única opção é ser seu cúmplice.",
  ui_story_5086_50861300_60_dialog_content = "Levarei ele para a próxima etapa do seu tratamento.",
  ui_story_5086_50861300_61_dialog_content = "Celestita, eu posso precisar da sua ajuda para garantir que a consciência de Elvis permaneça intacta.",
  ui_story_5086_50861300_62_dialog_content = "É por isso que fiz Maya transmitir essa informação para você.",
  ui_story_5086_50861300_63_dialog_content = "Por favor, mantenha isso em segredo de qualquer pessoa ligada a Lumopolis, incluindo seus companheiros.",
  ui_story_5086_50861300_64_dialog_content = "Encontrarei uma maneira de contatá-lo quando for a hora certa.",
  ui_story_5086_50861300_65_dialog_content = "Só isso?",
  ui_story_5086_50861300_66_dialog_content = "Hmm... Não, há mais uma coisa.",
  ui_story_5086_50861300_67_dialog_content = "Não sou um grande líder, então pensei em deixar o circo para trás. É uma pena que o Emerald esteja tão cheio de pessoas teimosas e inflexíveis.",
  ui_story_5086_50861300_68_dialog_content = "Eles insistem em me seguir, e se eu adicionar Elvis à equação... Bem, a conclusão é que estamos deixando Maya sozinha em Harbor City.",
  ui_story_5086_50861300_69_dialog_content = "Ouvi dizer que Elvis prometeu ao pai dela que ele sempre estaria lá para ela.",
  ui_story_5086_50861300_70_dialog_content = "Então, não tenho escolha a não ser pedir que você nos ajude com isso.",
  ui_story_5086_50861300_71_dialog_content = "Não se preocupe, eu vou ficar bem!",
  ui_story_5086_50861300_72_dialog_content = "Maya... Você realmente não vai com a gente?",
  ui_story_5086_50861300_73_dialog_content = "Boo-hoo... Vou sentir sua falta...",
  ui_story_5086_50861300_74_dialog_content = "(Vamos parar por aqui.)",
  ui_story_5086_50861300_75_dialog_content = "Nós iremos?",
  ui_story_5086_50861300_76_dialog_content = "Você encontrou o que estava procurando?",
  ui_story_5086_50861300_77_dialog_content = "Eu fiz! Obrigado, Maya. Você realmente me fez um favor ali.",
  ui_story_5086_50861300_78_dialog_content = "Legal!",
  ui_story_5086_50861300_79_dialog_content = "De qualquer forma... Agora que a senhorita Stellandine se foi...",
  ui_story_5086_50861300_80_dialog_content = "Você gostaria de vir comigo?",
  ui_story_5086_50861300_81_dialog_content = "Embora eu não possa te dar o melhor, há muitos quartos vazios no Colossus...",
  ui_story_5086_50861300_82_dialog_content = "Eu realmente gosto de você, PlayerName!",
  ui_story_5086_50861300_83_dialog_content = "Hã?! De onde veio isso...",
  ui_story_5086_50861300_84_dialog_content = "Heehee! Mas eu também gosto de Elvis, do mar e de Harbour City.",
  ui_story_5086_50861300_85_dialog_content = "E mesmo que eu deva manter isso em segredo...",
  ui_story_5086_50861300_86_dialog_content = "Eu realmente gosto muito da Senhorita Stellandine também!",
  ui_story_5086_50861300_87_dialog_content = "Por essa razão, quero ficar e manter este aquário vivo.",
  ui_story_5086_50861300_88_dialog_content = "O aquário sempre será meu lar.",
  ui_story_5086_50861300_89_dialog_content = "E farei o meu melhor para compensar tudo e curar as cicatrizes de todos, para que possamos todos sorrir novamente.",
  ui_story_5086_50861300_90_dialog_content = "Tudo bem... Se eu encontrar um médico capaz de tratar sua perda de memória, pode ter certeza de que eu o trarei para você.",
  ui_story_5086_50861300_91_dialog_content = "Obrigado, embora você realmente não precise se preocupar com isso.",
  ui_story_5086_50861300_92_dialog_content = "Tenho confiança de que conseguirei viver uma vida melhor.",
  ui_story_5086_50861300_93_dialog_content = "Além disso, <color=#FFB400>eu</color> descobri algumas coisas.",
  ui_story_5086_50861300_94_dialog_content = "O que seria?",
  ui_story_5086_50861300_95_dialog_content = "Hehe! <color=#FFB400>Eu</color> anotei isso nas minhas anotações. Vou deixar você ler quando nos encontrarmos novamente.",
  ui_story_5086_50861300_96_dialog_content = "Mas é um segredo por enquanto!",
  ui_story_5086_50861300_97_dialog_content = "<color=#e8d9bb>Os cavaleiros de Lumópolis assumiram o trabalho restante.</color>",
  ui_story_5086_50861300_98_dialog_content = "<color=#e8d9bb>Aqueles que se destacaram foram recompensados e partiram.</color>",
  ui_story_5086_50861300_99_dialog_content = "<color=#e8d9bb>E os visitantes exaustos partiram depois de relatar tudo o que sabiam.</color>",
  ui_story_5086_50861300_100_dialog_content = "<color=#e8d9bb>Uma vez que os funcionários também saíram, Maya ficou completamente sozinha no aquário à noite... E outro que estava silenciosamente fazendo seu caminho de volta.</color>",
  ui_story_5086_50861300_101_dialog_content = "Olá, senhorita Maya.",
  ui_story_5086_50861300_102_dialog_content = "Sr. Minos? O que você está fazendo de volta aqui? Você esqueceu algo?",
  ui_story_5086_50861300_103_dialog_content = "Eu só queria confirmar algo.",
  ui_story_5086_50861300_104_dialog_content = "Hã? O que isso deveria significar?",
  ui_story_5086_50861300_105_dialog_content = "Então, deixe-me explicar brevemente.",
  ui_story_5086_50861300_106_dialog_content = "Você contou uma história para as crianças.",
  ui_story_5086_50861300_107_dialog_content = "Era sobre um garoto e um monstro do mar em uma pequena cidade...",
  ui_story_5086_50861300_108_dialog_content = "Eu contei uma história assim? Parece realmente interessante!",
  ui_story_5086_50861300_109_dialog_content = "De fato, foi. Srta. Maya, você tem uma imaginação absolutamente livre e vibrante.",
  ui_story_5086_50861300_110_dialog_content = "Mas tive o prazer de ler a história original.",
  ui_story_5086_50861300_111_dialog_content = "No original, uma vez que o garoto cresceu, ele partiu em busca da cidade novamente.",
  ui_story_5086_50861300_112_dialog_content = "Mas não importa quantas praias e florestas ele cruzou, ele nunca conseguiu encontrar o caminho de volta para lá.",
  ui_story_5086_50861300_113_dialog_content = "Acontece que a cidade reside entre as fissuras de um sonho, e só é projetada na realidade quando alguém a vê ou observa.",
  ui_story_5086_50861300_114_dialog_content = "O garoto e a garota chorando tornaram-se amigos, e ele ajudou as pessoas a eliminar o monstro do mar. No entanto, nunca mais visitantes visitaram a cidade novamente.",
  ui_story_5086_50861300_115_dialog_content = "Conforme o tempo passava, a própria cidade desapareceu.",
  ui_story_5086_50861300_116_dialog_content = "Se isso acontecesse, você acha que o gato se arrependeria de arrastar o garoto para tudo isso?",
  ui_story_5086_50861300_117_dialog_content = "O gato possui um poder incrível, e \"os\" pensamentos dela afetarão meu julgamento em certos assuntos.",
  ui_story_5086_50861300_118_dialog_content = "Eu... na verdade não entendo muito bem sua história, Sr. Minos.",
  ui_story_5086_50861300_119_dialog_content = "Mas a menina que chorava sozinha todos os dias fez um amigo por causa do garoto.",
  ui_story_5086_50861300_120_dialog_content = "E os visitantes que foram atraídos até lá pela lenda parecem ter ido embora após se divertirem ao máximo.",
  ui_story_5086_50861300_121_dialog_content = "No final, todos do sonho voltaram para onde vieram.",
  ui_story_5086_50861300_122_dialog_content = "Então talvez o gato... não tenha pensado nada sobre isso.",
  ui_story_5086_50861300_123_dialog_content = "Embora haja alguns arrependimentos, todos fizeram o seu melhor, e isso torna um final feliz.",
  ui_story_5086_50861300_124_dialog_content = "Um bom final... Huh?",
  ui_story_5086_50861300_125_dialog_content = "Se eu tivesse que dizer, o gato definitivamente gostaria de ver o garoto novamente.",
  ui_story_5086_50861300_126_dialog_content = "Gostaria de dar outro passeio na praia juntos.",
  ui_story_5086_50861300_127_dialog_content = "Observe as ondas quebrando sobre o recife de corais, peixes voadores saltando da água, e role na areia e ria enquanto assiste a um caranguejo desajeitado cambaleando para lá e para cá.",
  ui_story_5086_50861300_128_dialog_content = "E no final do dia, eles se enrolariam sob uma palmeira e deixariam a brisa do mar levá-los para dormir.",
  ui_story_5086_50861300_129_dialog_content = "É esse o desejo atual do gato?",
  ui_story_5086_50861300_130_dialog_content = "Poderia ter realizado esse desejo indo com o garoto.",
  ui_story_5086_50861300_131_dialog_content = "Mas a casa do gato está na cidade.",
  ui_story_5086_50861300_132_dialog_content = "Então, o gato vai esperar até o garoto voltar. Afinal de contas...",
  ui_story_5086_50861300_133_dialog_content = "O amor é eterno.",
  ui_story_5086_50861300_134_dialog_content = "Entendi agora. Obrigado, era tudo que eu queria perguntar.",
  ui_story_5086_50861300_135_dialog_content = "Bem, estou voltando para relatar o resultado da investigação de negócios à Srta. Nina. Adeus!",
  ui_story_5086_50861300_136_dialog_content = "...",
  ui_story_5086_50861300_137_dialog_content = "Espero que o gato consiga o que deseja.",
  ui_story_5086_50861300_138_dialog_content = "Não se preocupe.",
  ui_story_5086_50861300_139_dialog_content = "Porque contos de fadas...",
  ui_story_5086_50861300_140_dialog_content = "Sempre tenha um final feliz.",
  ui_story_5086_50861300_141_dialog_content = "Ei! Você está tentando se matar?",
  ui_story_5086_50861300_142_dialog_content = "Argh! Fui pego?!",
  ui_story_5086_50861300_143_dialog_content = "Não vá correr por aí sob a brisa do mar quando ainda estiver doente.",
  ui_story_5086_50861300_144_dialog_content = "Já dormi o suficiente, Jeno. Quero contemplar minha casa enquanto estou acordado.",
  ui_story_5086_50861300_145_dialog_content = "Será que a Maya está bem...?",
  ui_story_5086_50861300_146_dialog_content = "A linhagem de sangue do Dragão Miragem, o último do clã Miragem...",
  ui_story_5086_50861300_147_dialog_content = "E você verificou que a pulseira dela contém autênticos bigodes de dragão.",
  ui_story_5086_50861300_148_dialog_content = "Nada pode impedi-la.",
  ui_story_5086_50861300_149_dialog_content = "De fato. É um item lendário que seu pai superou inúmeros desafios para obter do Santuário.",
  ui_story_5086_50861300_150_dialog_content = "Não estou preocupado com a sobrevivência dela.",
  ui_story_5086_50861300_151_dialog_content = "Eu apenas... não quero que ela jamais perca seu sorriso.",
  ui_story_5086_50861300_152_dialog_content = "Espero que Harbour City, e eu, tenhamos sido dignos de seus belos contos de fadas.",
  ui_story_5086_50861300_153_dialog_content = "Então, faça o seu melhor para expiar assim que melhorar.",
  ui_story_5086_50861300_154_dialog_content = "Faça as pazes por tudo.",
  ui_story_5086_50861300_155_dialog_content = "... Eu estarei lá ao seu lado.",
  ui_story_5086_50861300_156_dialog_content = "Pode deixar."
}
return config
